    'maint.aide_tech_title' => "De melder",
    'maint.aide_tech_sub' => "Wie meldt deze interventie?",
    'maint.aide_tech_body' => <<<'HTML'
<p>De melder is de persoon die het ticket opent — degene die de storing heeft vastgesteld of een taak te laten uitvoeren heeft.</p>
            <ul class="aide-list">
                <li><i class="fa-solid fa-lock" style="color:var(--accent);"></i> Als u technicus bent, is dit veld vergrendeld op uw eigen naam.</li>
                <li><i class="fa-solid fa-user-shield" style="color:var(--accent);"></i> Een beheerder kan elk teamlid aanwijzen.</li>
            </ul>
HTML,

    'maint.aide_assign_tech_title' => "Geplande technici",
    'maint.aide_assign_tech_sub' => "Vooraf één of meer technici toewijzen bij aanmaak (optioneel)",
    'maint.aide_assign_tech_body' => <<<'HTML'
<p>Dit veld, voorbehouden aan beheerders, laat u vooraf één of meer technici aanvinken die deze interventie gaan uitvoeren — handig om de planning te organiseren. Laat "Niet toegewezen" aangevinkt als nog niemand is aangeduid: wie het ticket oppakt, wijst het dan zelf aan zich toe.</p>
            <div class="aide-callout aide-callout-info"><i class="fa-solid fa-circle-info"></i><div>Dit is slechts een indicatie: wie daadwerkelijk tijd registreert op het ticket wordt de officiële technicus.</div></div>
HTML,

    'maint.aide_sous_traitant_title' => "Uitbestede interventie",
    'maint.aide_sous_traitant_sub' => "Wanneer een extern bedrijf de interventie uitvoert",
    'maint.aide_sous_traitant_body' => <<<'HTML'
<p>Vink dit vakje aan als de interventie wordt toevertrouwd aan een externe dienstverlener in plaats van het interne team.</p>
            <ul class="aide-list">
                <li><i class="fa-solid fa-list-check" style="color:var(--brand-orange);"></i> Kies vervolgens het bedrijf uit de lijst die net daaronder verschijnt.</li>
                <li><i class="fa-solid fa-file-pdf" style="color:var(--brand-orange);"></i> Zodra de order is aangemaakt, verschijnt een knop "PVP genereren" (Preventieplan) op het dossier.</li>
            </ul>
HTML,

    'maint.aide_localisation_title' => "De machine lokaliseren",
    'maint.aide_localisation_sub' => "Zoeken of navigeren via tegels",
    'maint.aide_localisation_body' => <<<'HTML'
<p>Twee manieren om de machine te vinden: typ de naam (of een zone, een sector...) in de <b>zoekbalk</b>, of klik stap voor stap door de tegels <b>Fabriek → Sector → Lijn → Zone → Machine</b>.</p>
            <div class="aide-callout aide-callout-tip"><i class="fa-solid fa-lightbulb"></i><div>Het broodkruimelpad boven de tegels laat u op elk moment teruggaan om van fabriek, sector, enz. te veranderen. Geen paniek als een sector geen "Lijn" heeft: deze stap wordt automatisch overgeslagen.</div></div>
HTML,

    'maint.aide_machine_title' => "De machine selecteren",
    'maint.aide_machine_sub' => "De laatste schakel van de locatie",
    'maint.aide_machine_body' => <<<'HTML'
<p>De zoekbalk filtert direct op alle machines (naam, zone, sector, fabriek): ideaal wanneer u de machine al kent. Anders kunt u met de tegels hieronder stap voor stap navigeren naar de betreffende uitrusting. Dit houdt een nette onderhoudshistoriek per machine bij.</p>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-triangle-exclamation"></i><div>Machine niet gevonden? Het veld wordt een vrij tekstveld — laat deze door een beheerder toevoegen aan het Machinepark voor de volgende keer.</div></div>
HTML,

    'maint.aide_date_title' => "Interventiedatum",
    'maint.aide_date_sub' => "Standaard vandaag",
    'maint.aide_date_body' => "<p>De datum van vandaag wordt automatisch vooraf ingevuld. U kunt deze wijzigen als u een interventie uit het verleden meldt, bijvoorbeeld om een vergeten invoer in te halen.</p>",

    'maint.aide_type_title' => "Type interventie",
    'maint.aide_type_sub' => "Curatief, Preventief of Project?",
    'maint.aide_type_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-screwdriver-wrench" style="color:var(--accent);"></i> <b>Curatief</b>: een reeds opgetreden storing herstellen.</li>
                <li><i class="fa-solid fa-calendar-check" style="color:var(--accent);"></i> <b>Preventief</b>: geplande controle of onderhoud, vóór de storing.</li>
                <li><i class="fa-solid fa-helmet-safety" style="color:var(--accent);"></i> <b>Project</b>: een installatie-, wijzigings- of verbeteringsproject.</li>
            </ul>
HTML,

    'maint.aide_prio_title' => "Prioriteit",
    'maint.aide_prio_sub' => "Normaal of Dringend?",
    'maint.aide_prio_body' => <<<'HTML'
<ul class="aide-list">
                <li><i class="fa-solid fa-circle-check" style="color:var(--accent);"></i> <b>Normaal</b>: standaardinterventie, in volgorde te behandelen.</li>
                <li><i class="fa-solid fa-bell" style="color:var(--danger);"></i> <b>Dringend</b>: lijn stilgelegd of veiligheidsgevaar.</li>
            </ul>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-bell"></i><div>Een "Dringend" ticket knippert rood in de tabel totdat het is opgepakt — reserveer dit niveau voor echte noodgevallen.</div></div>
HTML,

    'maint.aide_casse_title' => "Schade",
    'maint.aide_casse_sub' => "Accidentele materiële schade",
    'maint.aide_casse_body' => "<p>Aanvinken als de interventie het gevolg is van verkeerde bediening of een accidentele schok aan het materieel. Hiermee kan het breukpercentage in de statistieken worden gevolgd.</p>",

    'maint.aide_verif_vis_title' => "Controle bevestiging",
    'maint.aide_verif_vis_sub' => "Kwaliteits-/auditvereiste",
    'maint.aide_verif_vis_body' => <<<'HTML'
<p>Door dit vakje aan te vinken, certificeert u formeel dat u de integriteit van de bevestigingen van de uitrusting heeft gecontroleerd.</p>
            <div class="aide-callout aide-callout-warn"><i class="fa-solid fa-shield-halved"></i><div>U verklaart dat alle schroeven, moeren en bevestigingen die tijdens de interventie zijn gedemonteerd, zijn teruggeplaatst en correct zijn aangedraaid — waarmee elk risico op een vallend vreemd voorwerp wordt uitgesloten.</div></div>
