    'aide_connexion.route_maint_li2' => "U voert <b>uw persoonlijke geheime code</b> in, uniek voor u.",
    'aide_connexion.route_maint_li3' => "U komt op de <b>GMAO-startpagina</b> terecht, met alle tegels (Invoer & Historiek, Planning, KPI...).",
    'aide_connexion.route_service_tag' => "Productie, Kwaliteit, Veiligheid, HR, Boekhouding, Logistiek, Agronomie...",
    'aide_connexion.route_service_title' => "Andere diensten",
    'aide_connexion.route_service_li1' => "U selecteert <b>de naam van uw dienst</b> (bv. \"S. Productie\"), niet uw persoonlijke naam.",
    'aide_connexion.route_service_li2' => "U voert de <b>algemene code van de dienst</b> in — dezelfde voor het hele team, geen individuele code.",
    'aide_connexion.route_service_li3' => "U komt op het portaal <b>\"Een werkaanvraag indienen\"</b> terecht, niet op de GMAO zelf.",
    'aide_connexion.modes_warn' => "<b>Alleen andere diensten:</b> de dienstcode opent enkel het portaal. Voor <b>elke aanvraag</b> die u indient, vraagt een extra stap uw <b>naam</b> en een <b>persoonlijke code van minstens 4 cijfers</b> — verschillend van de inlogcode van de dienst. Deze persoonlijke code dient als elektronische handtekening: ze bewijst dat u degene bent die deze specifieke aanvraag heeft ingediend. Alles wordt uitgelegd in <a href=\"aide_service.php\">het artikel gewijd aan het aanvraagportaal</a>.",
    'aide_connexion.connexion_lede' => "Geen e-mailadres of klassiek wachtwoord hier: u kiest uw naam (of uw dienst) uit een lijst, en voert dan de bijhorende code in.",
    'aide_connexion.shot_login_alt' => "Inlogscherm van de GMAO",
    'aide_connexion.shot_login_cap' => "Het inlogscherm: een naam, een code, een knop.",
    'aide_connexion.step1_title' => "Kies uw naam, of uw dienst",
    'aide_connexion.step1_desc' => "Open de keuzelijst <b>\"Wie bent u?\"</b>. Het onderhoudsteam vindt er zijn persoonlijke naam; andere diensten selecteren de naam van hun dienst (bv. \"S. Kwaliteit\").",
    'aide_connexion.step2_title' => "Voer de bijhorende code in",
    'aide_connexion.step2_desc' => "Onderhoudsteam: uw persoonlijke geheime code. Andere diensten: de algemene code van uw dienst, degene die het hele team gebruikt. Ze wordt op het scherm verborgen, zoals een wachtwoord.",
    'aide_connexion.step3_title' => "Klik op \"SE CONNECTER\" (Inloggen)",
    'aide_connexion.step3_desc' => "U wordt automatisch doorgestuurd naar uw startscherm.",
    'aide_connexion.tip_code' => "Nooit een code ontvangen, of moet u ze wijzigen? Gebruik de link <b>\"Mijn geheime code wijzigen\"</b> onder de inlogknop, of vraag het een beheerder.",
    'aide_connexion.langue_lede' => "De hele GMAO — dit inlogscherm inbegrepen — is beschikbaar in het Frans, Engels en Nederlands.",
    'aide_connexion.langue_step1_title' => "Zoek de drie vakjes \"FR / EN / NL\"",
    'aide_connexion.langue_step1_desc' => "Ze worden rechtsboven op het inlogscherm getoond, en in de bovenbalk op elke pagina zodra u bent ingelogd.",
    'aide_connexion.langue_step2_title' => "Klik op de gewenste taal",
    'aide_connexion.langue_step2_desc' => "De pagina wordt onmiddellijk herladen in die taal — niet nodig om opnieuw in te loggen.",
    'aide_connexion.langue_step3_title' => "De keuze wordt onthouden",
    'aide_connexion.langue_step3_desc' => "U hoeft dit maar eenmaal per toestel/browser te doen: de GMAO onthoudt daarna uw taal bij elk bezoek.",
    'aide_connexion.langue_tip' => "Enkel de interface zelf wordt vertaald (menu's, knoppen, labels). Inhoud die u of uw collega's hebben ingevoerd — machinenamen, interventieverslagen, in Instellingen aangemaakte categorieën, enz. — blijft weergegeven zoals ze geschreven werd, ongeacht de gekozen taal.",
    'aide_connexion.erreur_lede' => "Een rood bericht verschijnt als de naam en de code niet overeenkomen.",
    'aide_connexion.shot_erreur_alt' => "Foutmelding: onjuiste gebruikersnaam of code",
    'aide_connexion.shot_erreur_cap' => "Dit bericht geeft niet aan welk van de twee velden fout is — dat is bewust zo, om veiligheidsredenen.",
    'aide_connexion.erreur_check_intro' => "Controleer voor u opnieuw begint, in deze volgorde:",
    'aide_connexion.erreur_check_list' => "<b>1.</b> Is de juiste naam geselecteerd in de lijst?<br>\n<b>2.</b> Is de code getypt zonder spatie of typfout?<br>\n<b>3.</b> Staat Caps Lock niet aan?",
    'aide_connexion.erreur_contact' => "Nog steeds vastgelopen? Neem contact op met een beheerder om uw code te laten controleren of resetten — het account kan ook gedeactiveerd zijn.",
    'aide_connexion.accueil_lede' => "Het scherm dat meteen na het inloggen verschijnt, is niet voor iedereen hetzelfde: het hangt af van het gebruikte account. Twee scenario's, hieronder elk getoond met een echte schermafbeelding.",
    'aide_connexion.accueil_maint_h3' => "Onderhoudsteam: de volledige GMAO",
    'aide_connexion.accueil_maint_p' => "Met een <b>admin- of technicusaccount</b> komt u op het tegelscherm van de GMAO terecht: het startpunt naar alle functies (Invoer & Historiek, Planning, KPI...).",
    'aide_connexion.shot_accueil_tuiles_alt' => "GMAO-startscherm met navigatietegels, beheerdersweergave",
    'aide_connexion.shot_accueil_tuiles_cap' => "Het GMAO-startscherm, bekeken met een beheerdersaccount — alle tegels zijn toegankelijk.",
    'aide_connexion.accueil_lock_note' => "Met een <b>technicusaccount</b> verschijnen de tegels voorbehouden aan beheerders (Preventief, Technicusstatistieken, KPI, Machinepark, Gebruikersbeheer) <b>grijs met een hangslot</b>. Dat is geen fout: die functies zijn gewoon niet voor uw dagelijkse gebruik.",
    'aide_connexion.accueil_menu_tip' => "Eenmaal op de GMAO-schermen opent een ronde knop linksboven (<i class=\"fa-solid fa-bars\"></i>) op elk moment het volledige zijmenu, om te navigeren zonder naar het startscherm terug te keren. (De ronde knop die u op deze helppagina ziet, brengt u gewoon terug.)",
    'aide_connexion.accueil_service_h3' => "Andere diensten: het Dienstenportaal",
    'aide_connexion.accueil_service_p' => "Met een <b>dienstaccount</b> (Productie, Kwaliteit, Veiligheid, HR, Boekhouding, Logistiek, Agronomie...) komt u op een veel eenvoudigere pagina met 4 tegels terecht, ontworpen voor uw dagelijkse behoeften: een werkaanvraag indienen, de status ervan volgen, een verbeteridee voorstellen, of de help raadplegen.",
    'aide_connexion.shot_accueil_service_alt' => "Startscherm van het Dienstenportaal met zijn 4 tegels",
    'aide_connexion.shot_accueil_service_cap' => "Het startscherm van het Dienstenportaal — 4 tegels: Nieuwe aanvraag, Opvolging, Ideeën, Help.",
    'aide_connexion.accueil_service_tip' => "Deze pagina geeft geen toegang tot enige functie van de GMAO zelf: het is een vereenvoudigd, volledig begeleid toegangspunt. Elke tegel wordt toegelicht in <a href=\"aide_service.php\">het artikel gewijd aan het aanvraagportaal</a>, ook toegankelijk via de tegel \"Help & veelgestelde vragen\" van het portaal zelf.",

