    'aide_kpi.shot_cartes_cap' => "De 5 kaarten: Totaal interventies, Uitvoeringspercentage, Totale uren, Breukpercentage (Periode), Terugkerende interventies. Screenshot van vóór de update van 03/09/2026 — het label op het scherm is gewijzigd, zie tabel hieronder.",
    'aide_kpi.tbl2_carte' => "Kaart",
