    'aide_kpi.card_total_nom' => "Totaal interventies",
    'aide_kpi.card_total_desc' => "Aantal tickets in de gefilterde periode/technicus, alle statussen samen.",
    'aide_kpi.card_taux_nom' => "Uitvoeringspercentage",
    'aide_kpi.card_taux_desc' => "Percentage tickets waarvan de status \"voltooid\" bevat, op het gefilterde totaal.",
    'aide_kpi.card_heures_nom' => "Totale uren",
    'aide_kpi.card_heures_desc' => "Som van alle geregistreerde tijd in de gefilterde set, alle ticketstatussen samen.",
    'aide_kpi.card_casse_nom' => "Breukpercentage (Periode)",
    'aide_kpi.card_casse_desc' => "Aandeel \"Breuk\"-tickets over de <b>gefilterde periode</b> (VAN/TOT-velden) — over de volledige historiek als geen datumfilter actief is. Volgt nu hetzelfde filter als de rest van het scherm.",
    'aide_kpi.card_panne_nom' => "Meest terugkerende storing",
    'aide_kpi.card_panne_desc' => "De uitrusting die het vaakst terugkomt als <b>curatief of werf</b> in de gefilterde set (preventief onderhoud, dat van nature dagelijks/wekelijks terugkeert, wordt uitgesloten van deze ranglijst); klikken opent een Top 5-donutgrafiek.",
    'aide_kpi.filtres_footer_p' => "Elke kaart is klikbaar en opent een gedetailleerd historiekvenster (BI-nr., datum, uitrusting, technicus, status) van de bijbehorende dataset.",
    'aide_kpi.graphiques_callout' => "De screenshots in deze sectie dateren van vóór de update van <b>03/09/2026</b> (toevoeging van de categorie Werf en de hieronder beschreven carrousel). Het echte scherm is qua uiterlijk licht gewijzigd — onderstaande tekst beschrijft het huidige gedrag.",
    'aide_kpi.shot_ratio_alt' => "Verdelingsbalk Curatief / Preventief / Werf",
    'aide_kpi.shot_ratio_cap' => "Verdeling Curatief / Preventief / Werf van de gefilterde set: aantal BI's, percentage en geregistreerde uren voor elk van de 3 categorieën.",
    'aide_kpi.graphiques_p1' => "Elk van de 3 bolletjes (Curatief, Preventief, Werf) is klikbaar en opent de volledige lijst interventiebonnen van die categorie in de gefilterde set.",
    'aide_kpi.carrousel_h3' => "De carrousel Curatief / Preventief / Werf",
    'aide_kpi.carrousel_intro' => "Net onder deze verdelingsbalk stuurt een rij van 3 bolletjes + een Pauzeknop de weergave aan van de panelen <b>\"Terugkerende storingen per sector\"</b>, <b>\"Terugkerende storingen per uitrusting\"</b> en <b>\"Maandelijkse storingstrend\"</b>:",
    'aide_kpi.carrousel_li1' => "Deze 3 panelen wisselen <b>samen</b>, automatisch, om de <b>5 seconden</b>: Curatief → Preventief → Werf → Curatief…",
    'aide_kpi.carrousel_li2' => "De badge in de kop van elk paneel (bv. \"Werf · Top 15\") geeft altijd de momenteel getoonde categorie aan.",
    'aide_kpi.carrousel_li3' => "Klikken op een bolletje (Curatief/Preventief/Werf) schakelt er onmiddellijk naar over en herstart de timer van 5 seconden vanaf dat moment.",
    'aide_kpi.carrousel_li4' => "De knop <b>Pauze</b> stopt het automatisch doorlopen om tijd te geven een specifieke categorie te lezen; ze wordt <b>Hervatten</b> om de cyclus opnieuw te starten.",
    'aide_kpi.carrousel_p2' => "In \"Terugkerende storingen per sector\" opent een klik op een rij het detail van de interventiebonnen van die sector — <b>gefilterd op de momenteel getoonde categorie</b> van de carrousel (Curatief, Preventief of Werf, afhankelijk van wat geselecteerd is op het moment van de klik).",
    'aide_kpi.shot_panneaux_alt' => "Panelen Terugkerende storingen per sector en per uitrusting",
    'aide_kpi.shot_panneaux_cap' => "\"Terugkerende storingen per sector\" en \"Terugkerende storingen per uitrusting\" (Top 15) — de getoonde inhoud hangt af van de actieve categorie van de hierboven beschreven carrousel.",
    'aide_kpi.shot_donut_alt' => "Ringdiagram van de Top 5 uitrustingen met terugkerende storingen",
    'aide_kpi.shot_donut_cap' => "Bij een klik op de kaart \"Meest terugkerende storing\": Top 5 uitrustingen (curatief + werf) + \"Overige\", klikbaar om het detail van een sector te zien. Deze donut is onafhankelijk van de carrousel — hij blijft altijd op curatief + werf gecombineerd.",
    'aide_kpi.stats_tech_lede' => "In tegenstelling tot KPI heeft dit scherm <b>geen enkel filter</b>: de drie grafieken zijn vast, en worden gelezen door erop te klikken voor meer detail.",
    'aide_kpi.shot_stats_alt' => "De drie grafieken van het scherm Technicusstatistieken",
    'aide_kpi.shot_stats_cap' => "Van boven naar onder: verloop van de uren (laatste 7 dagen), verdeling per technicus (totale cumul), verdeling Curatief vs Preventief.",
    'aide_kpi.stats_li1' => "<b>Verloop van de interventie-uren</b>: som van de per dag geregistreerde uren, over een vast venster van 7 voortschrijdende dagen — niet instelbaar vanaf het scherm.",
    'aide_kpi.stats_li2' => "<b>Verdeling per Technicus</b>: cumul van alle geregistreerde uren <i>sinds het begin</i> (geen datumlimiet), alle ticketstatussen samen. Klikken op een deel opent de interventielijst van de technicus.",
    'aide_kpi.stats_li3' => "<b>Verdeling Curatief vs Preventief</b>: bekijk goed de legende van deze kaart in de screenshot hierboven — zie valkuil nr. 4 net hieronder.",
    'aide_kpi.export_p' => "Er bestaat <b>geen globale export</b> (PDF/Excel) van een volledig dashboard. De enige mogelijke export is individueel: door het detail van een ticket te openen vanuit een van de historiekvensters, genereert de knop <b>\"EXPORTEREN ALS PDF\"</b> het rapport van die specifieke interventiebon.",
    'aide_kpi.pieges_h2' => "Leesvalkuilen — te kennen voordat u een cijfer interpreteert",
    'aide_kpi.pieges_lede' => "Deze dashboards zijn betrouwbaar, maar enkele gedragingen zijn goed om te kennen om een cijfer niet verkeerd te interpreteren in een vergadering.",
    'aide_kpi.pf1_title' => "De panelen \"Terugkerende storingen\" wisselen zelf van categorie",
    'aide_kpi.pf1_desc' => "\"Terugkerende storingen per sector/uitrusting\" en \"Maandelijkse storingstrend\" wisselen automatisch tussen Curatief, Preventief en Werf om de 5 seconden. Controleer voor u een cijfer van deze panelen aanhaalt de getoonde badge (bv. \"Werf\") — of klik op Pauze om de weergave op de gewenste categorie te bevriezen.",
    'aide_kpi.pf2_title' => "Niet-gevalideerde \"In afwachting\"-aanvragen worden meegeteld",
    'aide_kpi.pf2_desc' => "Totaal interventies, Uitvoeringspercentage en de verdelingen omvatten ook aanvragen die nog niet door onderhoud zijn gevalideerd, wat het schijnbare volume kan opblazen en het getoonde uitvoeringspercentage kan verlagen.",
    'aide_kpi.pf3_title' => "Een slecht ingevuld type telt als \"Curatief\"",
    'aide_kpi.pf3_desc' => "Enkel een ticket waarvan het type exact \"Preventief\" of \"Werf\" is, wordt als zodanig geteld — al de rest (inclusief een leeg of verkeerd gespeld typeveld) valt automatisch onder Curatief.",
    'aide_kpi.pf4_title' => "Het taartdiagram \"Curatief vs Preventief\" van Technicusstatistieken is altijd leeg",
    'aide_kpi.pf4_desc' => "Dit is geen echt gebrek aan gegevens: deze functie is niet afgewerkt in de huidige code. Concludeer nooit \"er is nooit preventief onderhoud geweest\" op basis van deze specifieke grafiek — gebruik in plaats daarvan de Curatief/Preventief-balk van het KPI-scherm.",
    'aide_kpi.pf5_title' => "De totale uren mengen alle statussen door elkaar",
    'aide_kpi.pf5_desc' => "Een ticket dat nog \"te doen\" is maar waarop al tijd is geregistreerd, telt volledig mee in de totale uren en in de werklast per technicus.",
    'aide_kpi.pf6_title' => "De technicuslijst van het KPI-filter is vast",
    'aide_kpi.pf6_desc' => "Een achteraf aangemaakte technicus verschijnt niet in de keuzelijst \"TECHNICUS\" van het KPI-scherm, ook al komen zijn uren correct terug in het paneel \"Werklast per Technicus\".",
    'aide_kpi.pf7_title' => "Een technicus op 0u verdwijnt, in plaats van \"0u\" te tonen",
    'aide_kpi.pf7_desc' => "Het paneel \"Werklast per Technicus\" verbergt volledig de technici zonder geregistreerde uren over de periode — afwezigheid in de lijst betekent niet \"geen gegevens\", maar wel degelijk \"nul uur\".",
    'aide_kpi.pf8_title' => "Twee verschillende tijdslogica's tussen de twee schermen",
    'aide_kpi.pf8_desc' => "KPI heeft geen standaardperiode (volledige historiek), terwijl de grafiek van Technicusstatistieken vastligt op een niet-aanpasbare voortschrijdende 7 dagen — houd dit verschil in gedachten bij het wisselen tussen beide.",
    'aide_kpi.gloss_taux_dt' => "Uitvoeringspercentage",
    'aide_kpi.gloss_taux_dd' => "Percentage \"voltooide\" tickets op het totaal van de gefilterde set.",
    'aide_kpi.gloss_pointage_dt' => "Tijdregistratie",
    'aide_kpi.gloss_pointage_dd' => "Een regel doorgebrachte tijd door een technicus op een ticket — basis van alle urenberekeningen.",
    'aide_kpi.gloss_panne_dt' => "Meest terugkerende storing",
    'aide_kpi.gloss_panne_dd' => "De uitrusting die het vaakst terugkomt als curatief of werf (storingen/breuken) in de tickets van de gefilterde set — routinematig preventief onderhoud telt niet mee.",
    'aide_kpi.gloss_chantier_dt' => "Werf",
    'aide_kpi.gloss_chantier_dd' => "Derde categorie interventiebon, naast Curatief en Preventief: een installatie-, wijzigings- of verbeteringsproject (in tegenstelling tot een herstelde storing of een geplande controle).",
    'aide_kpi.devnote_summary' => "Technische nota (admin/dev-team)",
    'aide_kpi.devnote_li1' => "<code>stats_tech.php</code>: de query <code>\$sql3</code> (verdeling Curatief/Preventief) staat in commentaar in de code en <code>dataTypes</code> is hardgecodeerd op <code>[0, 0]</code> — de bijbehorende grafiek zal nooit gegevens tonen zolang dit niet is aangesloten.",
    'aide_kpi.devnote_li2' => "<code>api.php</code> geeft alle taken terug zonder de status <code>In afwachting</code> te filteren, ook voor de KPI/Stats-schermen — in tegenstelling tot wat het gedeeltelijke (maar niet-functionele) filter in <code>maintenance.php</code> laat vermoeden.",

