    'aide_utilisateurs.pill_version' => "Versie <b>1.0</b>",
    'aide_utilisateurs.pill_updated' => "Bijgewerkt op <b>20/08/2026</b>",
    'aide_utilisateurs.pill_ecran' => "Betrokken scherm <b>Gebruikersbeheer</b>",
    'aide_utilisateurs.toc_vue_ensemble' => "Overzicht",
    'aide_utilisateurs.toc_roles' => "Beschikbare rollen",
    'aide_utilisateurs.toc_creer' => "Een account aanmaken",
    'aide_utilisateurs.toc_modifier' => "Een fiche wijzigen",
    'aide_utilisateurs.toc_mdp' => "Een wachtwoord wijzigen",
    'aide_utilisateurs.toc_pin' => "De persoonlijke pincode",
    'aide_utilisateurs.toc_activer' => "Een account activeren / deactiveren",
    'aide_utilisateurs.toc_supprimer' => "Een account verwijderen",
    'aide_utilisateurs.toc_securite' => "Veiligheid, wat u moet weten",
    'aide_utilisateurs.toc_droits' => "Wie mag wat",
    'aide_utilisateurs.toc_astuces' => "Tips & valkuilen",
    'aide_utilisateurs.toc_glossaire' => "Woordenlijst",
    'aide_utilisateurs.vue_ensemble_lede' => "<b>Gebruikersbeheer</b> centraliseert alle accounts van de applicatie: het onderhoudsteam dat de GMAO dagelijks gebruikt, de \"portaal\"-accounts van de diensten, en het personeel geïdentificeerd door een eenvoudige pincode. De pagina groepeert ze in drie blokken.",
    'aide_utilisateurs.case1_h4' => "Onderhoudsteam",
    'aide_utilisateurs.case1_p' => "<b>Admin</b>- en <b>technicus</b>accounts — volledige toegang tot de GMAO.",
    'aide_utilisateurs.case2_h4' => "Toegang Dienstenportalen",
    'aide_utilisateurs.case2_p' => "Dienstaccounts (Productie, Kwaliteit...) beveiligd met een wachtwoord, die toegang geven tot het vereenvoudigde aanvragersportaal.",
    'aide_utilisateurs.case3_h4' => "Personeel & Operatoren",
    'aide_utilisateurs.case3_p' => "Gegroepeerd per dienst, geïdentificeerd door een pincode in plaats van een wachtwoord — dit zijn de \"aanvragers\" van het werkaanvraagportaal.",
    'aide_utilisateurs.roles_tbl_role' => "Rol",
    'aide_utilisateurs.roles_tbl_donne' => "Wat ze geeft",
    'aide_utilisateurs.role1_nom' => "Onderhoudsbeheerder",
    'aide_utilisateurs.role1_desc' => "Volledige toegang tot de GMAO, inclusief deze pagina.",
    'aide_utilisateurs.role2_nom' => "Onderhoudstechnicus",
    'aide_utilisateurs.role2_desc' => "Toegang tot de GMAO, zonder gebruikersbeheer of bepaalde adminpagina's.",
    'aide_utilisateurs.role3_nom' => "Een dienst (bv. Productie, Kwaliteit...)",
    'aide_utilisateurs.role3_desc' => "Toegang tot het vereenvoudigde aanvragersportaal — niet tot de GMAO.",
    'aide_utilisateurs.roles_tip' => "De lijst met <b>diensten</b> in de keuzelijst \"Dienst / Toewijzing\" ligt niet vast — ze komt uit <b>Instellingen &gt; Diensten</b>. Een dienst daar toevoegen of hernoemen werkt de hier beschikbare keuzes onmiddellijk bij.",
    'aide_utilisateurs.creer_lede' => "Knop <b>\"NIEUWE GEBRUIKER / AANVRAGER\"</b> bovenaan de pagina. Het venster biedt twee modi.",
    'aide_utilisateurs.mode1_tag' => "Modus 1",
    'aide_utilisateurs.mode1_h3' => "Portaal-/Onderhoudstoegang",
    'aide_utilisateurs.mode1_p' => "Voor een account beveiligd met <b>wachtwoord</b>: onderhoudsteam, of een dienst die specifieke portaaltoegang nodig heeft. Het veld <b>\"Wachtwoord\"</b> is verplicht in deze modus.",
    'aide_utilisateurs.mode2_tag' => "Modus 2",
    'aide_utilisateurs.mode2_h3' => "Werknemer/Operator",
    'aide_utilisateurs.mode2_p' => "Voor een eenvoudige aanvrager geïdentificeerd door <b>pincode</b>: het voornaamveld verschijnt, en de persoonlijke code wordt optioneel (\"Leeg laten = automatisch onthouden\", zie verder).",
    'aide_utilisateurs.creer_tbl_champ' => "Veld",
    'aide_utilisateurs.creer_tbl_detail' => "Detail",
    'aide_utilisateurs.champ1_nom' => "Gebruikersnaam (of achternaam)",
    'aide_utilisateurs.champ1_d' => "Verplicht, moet uniek zijn.",
    'aide_utilisateurs.champ2_nom' => "Dienst / Toewijzing",
    'aide_utilisateurs.champ2_d' => "Verplicht — een dienst, of \"Onderhoudstechnicus\" / \"Onderhoudsbeheerder\".",
    'aide_utilisateurs.champ3_nom' => "Functie",
    'aide_utilisateurs.champ3_d' => "Vrije tekst, optioneel.",
    'aide_utilisateurs.champ4_nom' => "E-mail / Telefoon",
    'aide_utilisateurs.champ4_d' => "Optioneel.",
    'aide_utilisateurs.champ5_nom' => "Wachtwoord (Portaalmodus)",
    'aide_utilisateurs.champ5_d' => "Verplicht in deze modus.",
    'aide_utilisateurs.champ6_nom' => "Voornaam (Werknemermodus)",
    'aide_utilisateurs.champ6_d' => "Optioneel.",
    'aide_utilisateurs.champ7_nom' => "Pincode (Werknemermodus)",
    'aide_utilisateurs.champ7_d' => "Optioneel — zie de specifieke sectie.",
    'aide_utilisateurs.creer_footer' => "Het aangemaakte account is <b>altijd actief</b> vanaf het begin. Als de gebruikersnaam al bestaat: \"Fout: Deze gebruikersnaam bestaat al.\"",
    'aide_utilisateurs.modifier_lede' => "Klik op om het even welke gebruikerskaart om zijn volledige fiche te openen. De getoonde velden passen zich aan naargelang het een \"portaal\"-account (wachtwoord) of \"werknemer\"-account (pincode) betreft: Dienst/Rol, Functie, E-mail, Telefoon, en naargelang het geval, wachtwoord of Voornaam + Pincode, plus de accountstatus (actief/gedeactiveerd).",
    'aide_utilisateurs.modifier_p2' => "Knop <b>\"BIJWERKEN\"</b> om te bevestigen, <b>vuilbak</b>-icoon om te verwijderen, <b>\"SLUITEN\"</b> om af te sluiten zonder iets te wijzigen.",
    'aide_utilisateurs.mdp_lede' => "Er is geen aparte \"Reset\"-knop: open de fiche van het account, voer de nieuwe waarde in bij <b>\"Nieuw wachtwoord (Portaal)\"</b>, en dan \"BIJWERKEN\".",
    'aide_utilisateurs.mdp_tip' => "Het veld is <b>optioneel</b> bij wijziging: als u het leeg laat (\"Leeg laten indien ongewijzigd\"), wordt het bestaande wachtwoord niet aangeraakt.",
    'aide_utilisateurs.pin_lede' => "Dit is de code die werknemers/operatoren invoeren om herkend te worden in het werkaanvraagportaal.",
    'aide_utilisateurs.pin_tip' => "<b>Automatisch onthouden:</b> als u een werknemeraccount aanmaakt zonder pincode, is dat geen probleem. De eerste keer dat die persoon een code invoert in het aanvraagportaal, <b>registreert de applicatie deze automatisch</b> als zijn definitieve persoonlijke code. U kunt deze daarna op elk moment hier raadplegen of wijzigen.",
    'aide_utilisateurs.pin_warn' => "In tegenstelling tot het wachtwoord (altijd verborgen en versleuteld), is de <b>pincode in leesbare tekst zichtbaar</b> — in de bewerkingsfiche en als rode badge rechtstreeks op de minikaart van de werknemer. Dit is een bewust lichter beveiligingsniveau, geschikt voor een eenvoudige identificatiecode, geen echt wachtwoord.",
    'aide_utilisateurs.activer_lede' => "In de bewerkingsfiche biedt het veld <b>\"Accountstatus\"</b> twee waarden: <b>\"[ V ] ACCOUNT ACTIEF (Toegang toegestaan)\"</b> of <b>\"[ X ] ACCOUNT GEDEACTIVEERD (Toegang geblokkeerd)\"</b>.",
    'aide_utilisateurs.activer_warn' => "Een gedeactiveerd account kan helemaal niet meer inloggen (bericht \"Toegang geweigerd: Dit account is gedeactiveerd.\"), maar blijft hier zichtbaar om later opnieuw geactiveerd te worden. <b>Geen enkele visuele badge</b> geeft een gedeactiveerd account rechtstreeks aan op de kaarten van de lijst — u moet elke fiche openen om de status te controleren.",
    'aide_utilisateurs.supprimer_lede' => "Vuilbak-icoon in de bewerkingsfiche, met een eenvoudige bevestiging.",
    'aide_utilisateurs.supprimer_warn' => "<b>Definitieve verwijdering</b>, zonder controle van gekoppelde gegevens. De historiek (interventiebonnen, logboek, vroegere planningen) blijft weergegeven met de oude naam, maar het account bestaat niet meer — het kan niet meer inloggen, en het wordt onmogelijk om er nog iets aan toe te wijzen. Niets weerhoudt een beheerder er ook van om <b>zichzelf</b> te degraderen of te verwijderen: er is geen \"laatste admin\"-bescherming.",
    'aide_utilisateurs.securite_li1' => "<b>Het wachtwoord wordt altijd versleuteld</b> voor het wordt opgeslagen — nooit leesbaar, niet door u, niet door iemand anders.",
    'aide_utilisateurs.securite_li2' => "<b>De pincode daarentegen wordt in leesbare tekst opgeslagen en getoond</b> — gebruik ze nooit als een echt gevoelig wachtwoord.",
    'aide_utilisateurs.securite_li3' => "<b>Geen enkele actie op deze pagina wordt gelogd</b>: een account aanmaken, wijzigen, deactiveren of verwijderen laat geen enkel spoor na in het <a href=\"aide_logs.php\">Activiteitenlogboek</a>.",
    'aide_utilisateurs.securite_li4' => "Het <b>jaarlijkse urendoel</b> van een technicus (gebruikt in de Planning) wordt hier niet ingesteld — het wordt rechtstreeks gewijzigd vanuit de <a href=\"aide_planning.php\">Jaarplanning</a> van de betrokken persoon.",
    'aide_utilisateurs.droits_action' => "Actie",
    'aide_utilisateurs.droits_tech' => "Technicus",
    'aide_utilisateurs.droits_admin' => "Admin",
    'aide_utilisateurs.droits1' => "Toegang tot de pagina",
    'aide_utilisateurs.droits2' => "Een account aanmaken/wijzigen/verwijderen",
    'aide_utilisateurs.droits3' => "Een wachtwoord of pincode wijzigen",
    'aide_utilisateurs.astuces_li1' => "<b>Denk eraan de actief/inactief-status te controleren</b> voordat u aanneemt dat een geblokkeerd account in één oogopslag zichtbaar is — dat is niet zo.",
    'aide_utilisateurs.astuces_li2' => "<b>Laat de pincode leeg bij het aanmaken</b> van een nieuwe werknemer als u ze niet kent: ze wordt vanzelf onthouden bij de eerste aanvraag.",
    'aide_utilisateurs.astuces_li3' => "<b>Zoek het jaarlijkse urendoel hier niet</b> — dat zit in de Planning.",
    'aide_utilisateurs.astuces_li4' => "<b>Denk na voor u een account verwijdert</b> met een belangrijke historiek: deactiveer het liever, dat is omkeerbaar.",
    'aide_utilisateurs.gloss1_dt' => "Portaalaccount",
    'aide_utilisateurs.gloss1_dd' => "Account beveiligd met een wachtwoord (onderhoudsteam of dienst).",
    'aide_utilisateurs.gloss2_dt' => "Werknemer-/operatoraccount",
    'aide_utilisateurs.gloss2_dd' => "Account geïdentificeerd door een pincode, gebruikt aan de kant van het aanvraagportaal.",
    'aide_utilisateurs.gloss3_dt' => "Pincode",
    'aide_utilisateurs.gloss3_dd' => "Persoonlijke numerieke code, opgeslagen in leesbare tekst, die een aanvrager identificeert.",
    'aide_utilisateurs.gloss4_dt' => "Automatisch onthouden",
    'aide_utilisateurs.gloss4_dd' => "De pincode stelt zichzelf in bij de eerste invoer van de werknemer, als ze nog niet was ingesteld.",
    'aide_utilisateurs.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan de beheerderskant:",
    'aide_utilisateurs.devnote_li1' => "Het wachtwoordveld is een <code>&lt;input type=\"text\"&gt;</code> in beide modals (niet <code>type=\"password\"</code>) — de invoer wordt dus niet verborgen op het scherm.",
    'aide_utilisateurs.devnote_li2' => "Geen enkele aanroep van <code>ajouterLog()</code> in dit bestand: in tegenstelling tot <code>login.php</code> of <code>parametres.php</code> wordt geen enkele accountbeheeractie bijgehouden in <code>logs.php</code>.",
    'aide_utilisateurs.devnote_li3' => "Het verwijderen (<code>DELETE FROM utilisateurs</code>) controleert geen enkele afhankelijkheid — tickets/logs verwijzen naar de gebruiker via zijn <code>username</code> als vrije tekst, niet via een vreemde sleutel, dus niets blokkeert technisch de verwijdering.",
    'aide_utilisateurs.devnote_li4' => "Geen \"laatste admin\"-bescherming, noch \"kan uzelf niet wijzigen\".",

