    'aide_logs.quoi_warn' => "Reken niet op dit logboek om de geschiedenis van een interventiebon of tijdregistratie te achterhalen — gebruik in plaats daarvan de detailfiche van de betrokken BI (zie <a href=\"aide_ot.php\">de BI-gids</a>), die zijn eigen geschiedenis van statussen en rapporten bijhoudt.",
    'aide_logs.filtrer_lede' => "Drie combineerbare filters laten u snel een specifieke vermelding terugvinden. Ze werken onmiddellijk, zonder de pagina te herladen.",
