    'aide_logs.vider_step1_desc' => "Een bevestigingsvenster opent: \"Logboek wissen? — Weet u zeker dat u het VOLLEDIGE logboek wilt wissen? Deze actie is definitief en onomkeerbaar.\"",
    'aide_logs.vider_step2_title' => "Bevestig met \"ALLES WISSEN\"",
    'aide_logs.vider_step2_desc' => "Alle vermeldingen worden onmiddellijk verwijderd. De knop \"ANNULEREN\" sluit het venster zonder iets te doen.",
    'aide_logs.vider_warn' => "<b>Definitieve actie:</b> eenmaal bevestigd, is er geen enkele manier om de gewiste geschiedenis terug te krijgen — geen automatische back-up, geen prullenbak. En ironisch genoeg wordt deze totale verwijdering zelf niet gelogd: na een wissing is er geen enkel spoor meer van wie het logboek wiste of wanneer.",
    'aide_logs.droits_action' => "Actie",
    'aide_logs.droits_tech' => "Technicus",
    'aide_logs.droits_admin' => "Admin",
    'aide_logs.droits1' => "Toegang tot de pagina",
    'aide_logs.droits2' => "Filteren / zoeken",
    'aide_logs.droits3' => "Het logboek wissen",
    'aide_logs.astuces_li1' => "<b>Zoek niet naar afmeldingen</b>: ze worden nooit geregistreerd, enkel de aanmelding wel.",
    'aide_logs.astuces_li2' => "<b>Zoek hier niet naar de geschiedenis van een BI of tijdregistratie</b> — dat is niet wat dit logboek bijhoudt. Raadpleeg in plaats daarvan de fiche van de betrokken BI.",
    'aide_logs.astuces_li3' => "<b>Denk na voor u het logboek wist</b>: het is onomkeerbaar, en de wisactie zelf laat geen spoor achter.",
    'aide_logs.astuces_li4' => "<b>Combineer filters</b> om snel een specifieke vermelding terug te vinden, bijvoorbeeld \"Gebruiker = Dupont\" + \"Actie = Wijzigingen\" om alles te zien wat hij recent heeft gewijzigd.",
    'aide_logs.gloss1_dt' => "Activiteitenlogboek",
    'aide_logs.gloss1_dd' => "De tabel met belangrijke acties uitgevoerd in de GMAO, met datum, auteur en details.",
    'aide_logs.gloss2_dt' => "Actie",
    'aide_logs.gloss2_dd' => "Het type geregistreerde gebeurtenis (toevoeging, wijziging, verwijdering, login...).",
    'aide_logs.gloss3_dt' => "Details",
    'aide_logs.gloss3_dd' => "De vrije-tekstbeschrijving die elke logboekvermelding begeleidt.",
    'aide_logs.gloss4_dt' => "Opschoning / wissing",
    'aide_logs.gloss4_dd' => "De totale, onomkeerbare verwijdering van de volledige logboekgeschiedenis.",
    'aide_logs.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan de beheerderskant:",
    'aide_logs.devnote_li1' => "Logging (<code>ajouterLog()</code> in <code>db.php</code>) slikt stilzwijgend elke SQL-fout in (lege try/catch) \"om de applicatie niet te blokkeren\" — een logschrijving kan dus mislukken zonder dat enige waarschuwing dit meldt.",
    'aide_logs.devnote_li2' => "Het aanmaken/afsluiten van BI's en Planninginvoer roepen <code>ajouterLog()</code> niet aan: enkel Machinepark, Ideeën, Planningimport, Instellingen en login doen dit wel.",
    'aide_logs.devnote_li3' => "Het wissen van het logboek (<code>logs.php?action=clear</code>) wordt getriggerd door een eenvoudige GET-link die enkel beschermd wordt door de sessierolcontrole — geen CSRF-token. Te verharden als deze pagina ooit breder wordt blootgesteld.",

    // --- aide_parametres.php ---
