    'aide_parametres.toc_statuts' => "Statussen & prioriteiten",
    'aide_parametres.toc_planning' => "Planning",
    'aide_parametres.toc_todo' => "TODO-lijst",
    'aide_parametres.todo_h2' => "TODO-lijst",
    'aide_parametres.todo_lede' => "De taakcategorieën en geschatte duren die in de TODO-lijst van de planning worden voorgesteld.",
    'aide_parametres.todo_p' => "Het tabblad bevat twee lijsten. De <b>taakcategorieën</b> (standaard Herstelling, Preventief, Controle...) werken zoals de andere lijsten: toevoegen, wijzigen (naam, icoon, kleur), herordenen met de pijlen, verwijderen. De <b>geschatte duren</b> zijn de waarden, in minuten, die in de lijst \"Geschatte duur\" van een taak worden voorgesteld: voeg er een toe met het veld \"Minuten\" en verwijder ze met het kruisje op elk label.",
    'aide_parametres.todo_warn' => "Een categorie die nog door minstens één taak wordt gebruikt, kan niet worden verwijderd. Een duur verwijderen wijzigt reeds aangemaakte taken niet: ze behouden de hunne.",
    'aide_parametres.toc_tuiles' => "Starttegels",
    'aide_parametres.toc_droits' => "Wie mag wat",
    'aide_parametres.toc_astuces' => "Tips & valkuilen",
    'aide_parametres.toc_glossaire' => "Woordenlijst",
    'aide_parametres.vue_ensemble_lede' => "<b>Instellingen</b> centraliseert alle configuraties van de GMAO, verdeeld over 7 tabbladen. Hier voedt u de lijsten die overal elders worden gebruikt — uitrustingstypes, diensten, statussen, planningkleuren, starttegels.",
    'aide_parametres.vue_ensemble_tip' => "De meeste lijsten op deze pagina worden herordend met <b>Omhoog/Omlaag-pijltjes</b> op elke regel (geen slepen hier), en bieden <b>geen zoekfunctie</b> — u doorloopt de volledige lijst visueel.",
    'aide_parametres.general_h2' => "Tabblad Algemeen",
    'aide_parametres.general_lede' => "De bedrijfsnaam en het logo getoond in de volledige koptekst van de applicatie.",
    'aide_parametres.shot_general_alt' => "Tabblad Algemeen van Instellingen met alle 7 tabbladen zichtbaar",
    'aide_parametres.shot_general_cap' => "De 7 tabbladen van Instellingen, hier op \"Algemeen\": weergegeven naam en logo van de applicatie.",
    'aide_parametres.tbl_champ' => "Veld",
    'aide_parametres.tbl_detail' => "Detail",
    'aide_parametres.general_champ1_nom' => "Weergegeven naam van bedrijf/GMAO",
    'aide_parametres.general_champ1_d' => "Vrije tekst, verplicht.",
    'aide_parametres.general_champ2_nom' => "Logo",
    'aide_parametres.general_champ2_d' => "Enkel PNG, JPG, SVG of WEBP. Vervangt het logo van de koptekst en het menu.",
    'aide_parametres.types_h2' => "Tabblad Uitrustingstypes",
    'aide_parametres.types_lede' => "De lijst gebruikt om de machines van het <a href=\"aide_parc_machine.php\">Machinepark</a> te classificeren (Mechanisch, Elektrisch, Koeling...).",
    'aide_parametres.types_step1_title' => "Toevoegen",
    'aide_parametres.types_step1_desc' => "Naam + een icoon te kiezen uit een raster van 20.",
    'aide_parametres.types_step2_title' => "Wijzigen",
    'aide_parametres.types_step2_desc' => "Een type hernoemen <b>herklasseert automatisch</b> alle machines die het al gebruikten — niets breekt.",
    'aide_parametres.types_step3_title' => "Verwijderen",
    'aide_parametres.types_step3_desc' => "<b>Geblokkeerd</b> als minstens één machine dit type nog gebruikt: \"Kan niet verwijderen: dit type wordt nog gebruikt door minstens één machine.\"",
    'aide_parametres.services_h2' => "Tabblad Diensten",
    'aide_parametres.services_lede' => "De lijst met bedrijfsdiensten (Productie, HR, Kwaliteit...), gebruikt voor de rol van \"aanvrager\"-accounts in <a href=\"aide_utilisateurs.php\">Gebruikersbeheer</a>.",
    'aide_parametres.tbl_action' => "Actie",
    'aide_parametres.tbl_regle' => "Regel",
    'aide_parametres.services_row1_action' => "Toevoegen",
    'aide_parametres.services_row1_regle' => "Eén enkel veld: de naam. Een interne technische sleutel wordt automatisch gegenereerd en verandert daarna nooit meer.",
    'aide_parametres.services_row2_action' => "Wijzigen",
    'aide_parametres.services_row2_regle' => "Enkel het weergegeven label kan veranderen, niet de technische sleutel.",
    'aide_parametres.services_row3_action' => "Verwijderen",
    'aide_parametres.services_row3_regle' => "<b>Geblokkeerd</b> als minstens één gebruikersaccount deze dienst als rol heeft.",
    'aide_parametres.categories_h2' => "Tabblad Preventieve categorieën",
    'aide_parametres.categories_lede' => "De categorieën die de preventieve onderhoudsschema's classificeren (Proces, Kwaliteit, Reglementair, Dagelijks standaard).",
    'aide_parametres.categories_p' => "Toevoeg-/wijzigingsformulier: Naam, Beschrijving (getoond op de starttegel van de Preventief-module), Icoon (raster van 20) en Kleur (30 vooraf ingestelde kleuren + een kleurkiezer voor elke gewenste tint).",
    'aide_parametres.categories_warn' => "Dubbele bescherming bij verwijdering: <b>onmogelijk om onder 1 resterende categorie te zakken</b>, en <b>geblokkeerd</b> als de categorie nog gebruikt wordt door minstens één preventieve regel.",
    'aide_parametres.statuts_h2' => "Tabblad Statussen & prioriteiten",
    'aide_parametres.statuts_lede' => "Hernoemt en herkleurt de weergave van statussen (In afwachting, Te doen, Bezig, Voltooid, Geweigerd) en prioriteiten (Normaal, Urgent) <b>in de hele applicatie</b>.",
    'aide_parametres.statuts_lock' => "Dit is een <b>gesloten</b> set: er is geen \"Toevoegen\"- of \"Verwijderen\"-knop op dit tabblad. Enkel het <b>label</b> en de <b>kleur</b> van elke bestaande status/prioriteit zijn wijzigbaar — de waarde die daadwerkelijk op elke interventie wordt opgeslagen, verandert nooit. Het is puur visuele opmaak.",
    'aide_parametres.statuts_tip' => "Zolang u enkel de <b>kleur</b> wijzigt (het labelveld blijft zoals het vooraf was ingevuld), blijft de weergave automatisch de door elke gebruiker gekozen taal volgen (FR/EN/NL). Zodra u <b>nieuwe tekst</b> in het label typt, vervangt die tekst de automatische vertaling en wordt ze identiek getoond in alle talen.",
    'aide_parametres.planning_h2' => "Tabblad Planning",
    'aide_parametres.planning_lede' => "Het rijkste van de 7 tabbladen: de opmaak van de <a href=\"aide_planning.php\">Planning</a>, de jaarlijkse urendoelen, en de import-/resettools.",
    'aide_parametres.shot_planning_alt' => "Tabblad Planning van Instellingen: kleurbolletjes van diensten en gebeurtenissen",
    'aide_parametres.shot_planning_cap' => "Het tabblad Planning: elke dienst/gebeurtenis heeft zijn kleurbolletje en Wijzig-knop — de lijst zelf is gesloten.",
    'aide_parametres.planning_h3_listes' => "Diensten, Gebeurtenissen, Wachtdiensten",
    'aide_parametres.planning_listes_p' => "Drie gesloten lijsten (dezelfde regels als Statussen & prioriteiten: enkel label en kleur zijn wijzigbaar, geen toevoegen/verwijderen):",
    'aide_parametres.planning_li_postes' => "<b>Diensten</b>: Ochtend, Namiddag, Nacht, Volledige dag, Feestdag.",
    'aide_parametres.planning_li_evenements' => "<b>Gebeurtenissen</b>: Halve dag betaald verlof, Betaald verlof, Ziekte, ADV, Rustdag.",
    'aide_parametres.planning_li_astreintes' => "<b>Wachtdiensten</b>: Wachtdienst, Wachtdienst koeling.",
    'aide_parametres.planning_h3_objectifs' => "Jaarlijkse urendoelen",
    'aide_parametres.planning_objectifs_p' => "Een lijst van alle technici met hun huidige urendoel (standaard 1607u). Individueel aanpasbaar — nuttig voor deeltijds werk. Dit is dezelfde instelling die ook rechtstreeks bereikbaar is vanuit de <a href=\"aide_planning.php\">Jaarplanning</a> van een technicus.",
    'aide_parametres.planning_h3_import' => "Planningimport en -reset",
    'aide_parametres.reset_planning_tag' => "Destructief",
    'aide_parametres.reset_planning_h3' => "De planning resetten",
    'aide_parametres.reset_planning_p' => "Verwijdert <b>alles</b> wat werd geïmporteerd (diensten, wachtdiensten, uren, notities), over alle periodes heen. Onomkeerbaar.",
    'aide_parametres.reset_heures_tag' => "Destructief, gerichter",
    'aide_parametres.reset_heures_h3' => "De uren resetten",
    'aide_parametres.reset_heures_p' => "Zet enkel de <b>uren</b> op nul, met behoud van reeds getoonde diensten, wachtdiensten en notities. Ook onomkeerbaar, maar veel minder radicaal.",
    'aide_parametres.planning_warn' => "Verwar de twee knoppen niet: \"De planning resetten\" wist alles, \"De uren resetten\" raakt enkel de uren. Beide zijn <b>definitief</b>, zonder automatische back-up.",
    'aide_parametres.tuiles_h2' => "Tabblad Starttegels",
    'aide_parametres.tuiles_lede' => "Past de titel, beschrijving en kleur van elke tegel op het startscherm aan.",
    'aide_parametres.tuiles_fixes_h4' => "De 13 vaste tegels",
    'aide_parametres.tuiles_fixes_p' => "Invoer & Historiek, Planning, Onderaannemers, Preventief, Technicusstatistieken, KPI, Machinepark, Gebruikersbeheer, Ontvangen ideeën, Instellingen, Activiteitenlogboek, Dienstenportaal, Help. Elk heeft een standaardtitel en -kleur, hier vervangbaar.",
    'aide_parametres.dossiers_h4' => "Mijn mappen",
    'aide_parametres.dossiers_p' => "De persoonlijke mappen die <b>u</b> op uw eigen startscherm hebt aangemaakt (knop \"+ Toevoegen\" vanaf het startscherm, niet vanuit Instellingen). Dit tabblad laat u enkel een bestaande map <b>wijzigen</b> — titel, beschrijving, icoon, kleur — en het is specifiek voor uw account, onzichtbaar voor andere beheerders.",
    'aide_parametres.tuiles_tip' => "Elke hier opgeslagen aanpassing <b>vervangt</b> de standaardtitel/-beschrijving/-kleur van een tegel, voor alle gebruikers van de applicatie.",
    'aide_parametres.droits_action' => "Actie",
    'aide_parametres.droits_tech' => "Technicus",
    'aide_parametres.droits_admin' => "Admin",
    'aide_parametres.droits1' => "Toegang tot de pagina",
    'aide_parametres.droits2' => "Om het even welk tabblad wijzigen",
    'aide_parametres.astuces_li1' => "<b>Statussen, prioriteiten, diensten, gebeurtenissen en wachtdiensten vormen gesloten lijsten</b>: u kunt ze enkel hernoemen/herkleuren, nooit toevoegen of verwijderen.",
    'aide_parametres.astuces_li2' => "<b>Een uitrustingstype of status hernoemen breekt niets</b> — reeds geclassificeerde machines en interventies volgen automatisch.",
    'aide_parametres.astuces_li3' => "<b>Controleer goed welke van de twee planningknoppen u aanklikt</b>: \"uren\" (gericht) of \"planning\" (alles wissen) — beide zijn onomkeerbaar.",
    'aide_parametres.astuces_li4' => "<b>Er bestaat geen zoekfunctie</b> op deze pagina: voor een lange lijst (veel types of categorieën) moet u ze handmatig doorlopen.",
    'aide_parametres.astuces_li5' => "<b>Een preventieve categorie kan nooit tot nul zakken</b> — er blijft er altijd minstens één over, zelfs als ze ongebruikt is.",
    'aide_parametres.gloss1_dt' => "Opmaak",
    'aide_parametres.gloss1_dd' => "Het label en de kleur getoond voor een status, een prioriteit of een planningvakje — puur visueel, zonder de werkelijk opgeslagen gegevens te wijzigen.",
    'aide_parametres.gloss2_dt' => "Gesloten set",
    'aide_parametres.gloss2_dd' => "Een lijst waarvan de elementen vast liggen (geen toevoegen/verwijderen mogelijk), enkel hun naam en kleur zijn instelbaar.",
    'aide_parametres.gloss3_dt' => "Tegel",
    'aide_parametres.gloss3_dd' => "Een van de klikbare blokken op het startscherm, elk leidend naar een GMAO-functie.",
    'aide_parametres.gloss4_dt' => "Jaardoel",
    'aide_parametres.gloss4_dd' => "Het aantal uren dat een technicus moet bereiken over de jaarurenperiode, hier of vanuit de Planning instelbaar.",
    'aide_parametres.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan de beheerderskant:",
    'aide_parametres.devnote_li1' => "Het account <code>Directeur</code> is expliciet uitgesloten van de lijst met wijzigbare jaarlijkse urendoelen (harde uitsluiting in de code).",
    'aide_parametres.devnote_li2' => "De tekst van het tabblad Tegels vermeldt \"het icoon is hier niet wijzigbaar\" voor vaste tegels, maar de modal en de server-side <code>edit_tuile</code>-verwerking accepteren en bewaren wel degelijk een iconwijziging — tekst/gedrag-inconsistentie om te corrigeren of te aanvaarden.",
    'aide_parametres.devnote_li3' => "Het vorige logobestand wordt nooit van de schijf verwijderd bij vervanging (opstapeling van <code>logo_&lt;timestamp&gt;.&lt;ext&gt;</code>-bestanden in <code>img/</code>).",
    'aide_parametres.devnote_li4' => "Elke geslaagde wijziging op deze pagina wordt gelogd (<code>ajouterLog</code>, actie \"Instellingen\"), zichtbaar in het <a href=\"aide_logs.php\">Activiteitenlogboek</a>.",

    // --- aide_preventif.php ---
    'aide_preventif.page_title_tag' => "Preventief & Planning - GMAO Help",
    'aide_preventif.hero_tagline' => "Een controleschema plannen, de automatische omzetting naar interventiebonnen begrijpen, en het weekrooster lezen.",
