    'aide_preventif.toc_planning' => "De Planning lezen & gebruiken",
    'aide_preventif.toc_astuces' => "Tips & valkuilen",
    'aide_preventif.toc_glossaire' => "Woordenlijst",
    'aide_preventif.vue_ensemble_lede' => "Twee complementaire schermen: <b>Preventief</b> om terugkerende controles te plannen (smering, reglementaire inspecties, controles…), en <b>Planning</b> om te zien wie wat doet, dag per dag.",
    'aide_preventif.tbl_ecran' => "Scherm",
    'aide_preventif.tbl_qui' => "Wie heeft toegang",
    'aide_preventif.tbl_pourquoi' => "Waarvoor",
    'aide_preventif.row_preventif_ecran' => "Preventief",
    'aide_preventif.row_preventif_pourquoi' => "Een preventieve onderhoudsregel aanmaken, wijzigen, pauzeren of verwijderen.",
    'aide_preventif.row_planning_ecran' => "Planning",
    'aide_preventif.row_planning_pourquoi' => "De taken van de week per technicus raadplegen en herordenen.",
    'aide_preventif.vue_ensemble_lock' => "Als u technicus bent, verschijnt het tabblad \"Preventief\" niet eens in uw menu — dat is normaal, enkel onderhoud/administratie plant de schema's. U ziet en gebruikt de Planning wel normaal.",
    'aide_preventif.liste_lede' => "Het scherm Preventief toont alle bestaande schema's, met hun frequentie en vervaldatum.",
    'aide_preventif.shot_liste_alt' => "Lijst met preventieve onderhoudsregels met tellers en filters",
    'aide_preventif.shot_liste_cap' => "Bovenaan: tellers (actieve regels, achterstallig, binnenkort verval). Filterchips: Alle / Achterstallig / Binnenkort / Actueel / Gepauzeerd.",
    'aide_preventif.liste_li1' => "Een klik op een rij opent de detailfiche van de regel (alleen-lezen, met een \"Wijzigen\"-knop).",
    'aide_preventif.liste_li2' => "De knop <b>\"Afdrukbaar register\"</b> genereert een afdrukbare weergave van het hele preventieve programma.",
    'aide_preventif.liste_li3' => "De knop <b>\"Historiek\"</b> van een regel toont alle interventiebonnen die er al mee gegenereerd zijn.",
    'aide_preventif.creer_lede' => "De knop <b>\"NIEUWE REGEL\"</b> opent een wizard in 4 stappen.",
    'aide_preventif.creer_tip' => "Voor een eenmalige aanvraag (slechts één keer, geen herhaling), gebruik deze wizard niet: de knop <b>\"Naar preventief\"</b> van de <a href=\"aide_ot.php#portes\">validatiesluis</a> voegt ze rechtstreeks toe aan het tabblad <a href=\"#travaux-divers\">\"Winterwerken\"</a> hieronder, zonder een regel aan te maken.",
    'aide_preventif.step1_title' => "Wat & Wanneer",
    'aide_preventif.step1_desc' => "Type ingreep, prioriteit, dan de <b>planningsmodus</b>: hetzij een <b>frequentie in dagen</b> (dagelijks, wekelijks, 15 dagen, maandelijks, driemaandelijks, halfjaarlijks, jaarlijks), hetzij vaste <b>weekdagen</b> (maandag tot vrijdag). Voeg de geschatte duur toe en, indien nodig, een uiterste vervaldatum en een vroege waarschuwing.",
    'aide_preventif.step2_title' => "Locatie",
    'aide_preventif.step2_desc' => "Dezelfde cascade als voor een klassieke interventiebon: Fabriek → Sector → Lijn → Zone → Uitrusting. De machine moet bestaan in het Machinepark.",
    'aide_preventif.step3_title' => "Impact & Team",
    'aide_preventif.step3_desc' => "Impact op de productie (geen, volledige stop, verminderd tempo, kwaliteitsimpact, veiligheidsrisico), stopduur, melder, en vooral de <b>uitvoerende technicus</b> — die zal automatisch de gegenereerde interventiebonnen op zijn planning ontvangen. Alternatief: het vakje <b>\"Automatisch toewijzen aan de technicus van de ochtenddienst\"</b> negeert de vaste uitvoerder en kiest, bij elke generatie, de persoon op de \"Ochtend\"-dienst die dag in de <a href=\"planning.php\">Planning</a> — handig voor een taak die altijd moet terugkomen bij wie er 's ochtends aanwezig is, wie dat ook is.",
    'aide_preventif.step4_title' => "Details",
    'aide_preventif.step4_desc' => "Nauwkeurige beschrijving van de ingreep (verplicht), geïdentificeerde oorzaak, gebruikte onderdelen, opmerkingen, dan een samenvatting voor bevestiging.",
    'aide_preventif.shot_e1_alt' => "Wizard nieuwe preventieve regel, stap 1 Wat en Wanneer",
    'aide_preventif.shot_e1_cap' => "Stap 1 — Wat & Wanneer",
    'aide_preventif.shot_e2_alt' => "Wizard nieuwe preventieve regel, stap 2 Locatie",
    'aide_preventif.shot_e2_cap' => "Stap 2 — Locatie",
    'aide_preventif.shot_e3_alt' => "Wizard nieuwe preventieve regel, stap 3 Impact en Team",
    'aide_preventif.shot_e3_cap' => "Stap 3 — Impact & Team",
    'aide_preventif.shot_e4_alt' => "Wizard nieuwe preventieve regel, stap 4 Details en samenvatting",
    'aide_preventif.shot_e4_cap' => "Stap 4 — Details & samenvatting",
    'aide_preventif.creer_warn' => "Zonder <b>uitvoerende technicus</b> ingevuld bij stap 3 — of als \"Auto ochtend\" is aangevinkt maar niemand op de Ochtenddienst staat die dag —, zullen door deze regel gegenereerde interventiebonnen <b>niet op de Planning verschijnen</b> (ze blijven enkel zichtbaar in de klassieke ticketlijsten). Denk er altijd aan een uitvoerder toe te wijzen als u wilt dat de taak wordt ingepland.",
    'aide_preventif.travaux_lede' => "Op de pagina van een categorie, een tweede tabblad naast \"Automatische regels\": een lijst met <b>eenmalige</b> af te vinken taken, zonder frequentie of automatische BI-generatie — voor alles wat niet elk jaar hoeft terug te komen.",
    'aide_preventif.travaux_tip' => "Een taak komt hier op twee manieren terecht: handmatig toegevoegd via <b>\"+ Taak toevoegen\"</b>, of overgedragen vanuit een wachtende aanvraag in de <a href=\"aide_ot.php#portes\">validatiesluis</a> (knop \"Naar preventief\").",
    'aide_preventif.travaux_champs_title' => "De velden van een taak",
    'aide_preventif.travaux_champs_desc' => "Uitrusting, beschrijving, <b>gemeld door</b> (onderhoudsteam of dienst), <b>uitvoerder(s)</b> — aanvinkbare vakjes van het team, meerdere personen mogelijk, plus een vrije tekstregel voor seizoensversterking van productie zonder GMAO-account —, geplande datum en prioriteit (1 tot 4, 1 zijnde de meest urgente).",
    'aide_preventif.travaux_statut_title' => "De status",
    'aide_preventif.travaux_statut_desc' => "Een klikbare badge per taak: elke klik laat vorderen <b>Te doen → Bezig → Voltooid</b> (dan terug naar Te doen). Voltooide taken worden groen en de meest recent aangevinkte komen bovenaan hun groep.",
    'aide_preventif.travaux_recherche_title' => "Zoeken & filters",
    'aide_preventif.travaux_recherche_desc' => "Zoekbalk (uitrusting, taak, uitvoerder), filters Uitvoerder en Prioriteit, en de tabbladen Alle / Te doen / Bezig / Voltooid. De kolommen Uitrusting, Uitvoerder, Datum en Prioriteit sorteren bij een klik op hun koptekst.",
    'aide_preventif.travaux_warn' => "<b>Seizoenen:</b> taken worden gegroepeerd per seizoen (bv. \"2026-2027\"), automatisch berekend maar aanpasbaar. Aan het einde van een seizoen vinkt u de onafgewerkte taken aan (linkerkolom van de tabel) en klikt dan op <b>\"Selectie overdragen\"</b>: ze worden gekopieerd naar het gekozen seizoen (bestaand of nieuw), status teruggezet naar \"Te doen\". Niets wordt automatisch overgedragen — zonder deze actie blijft een onafgewerkte taak op het oude seizoen staan.",
    'aide_preventif.generation_lede' => "Een preventieve regel doet op zichzelf niets: het is een generatiemechanisme dat, met regelmatige tussenpozen, vervallen regels omzet in echte interventiebonnen.",
    'aide_preventif.generation_li1' => "De gegenereerde interventiebon draagt automatisch het voorvoegsel <code>[PREVENTIEF]</code> in zijn beschrijving, een status <span class=\"pill pill-all\"><span class=\"pill-dot\"></span>Te doen</span>, en het type <b>\"Preventief\"</b> (blauwe badge, anders dan het rode curatief).",
    'aide_preventif.generation_li2' => "Ze volgt vervolgens <b>exact dezelfde levenscyclus</b> als een klassieke curatieve interventiebon: Te doen → Bezig → Voltooid, met hetzelfde verplichte afsluitrapport (zie <a href=\"aide_ot.php\">het artikel \"Een interventiebon aanmaken & afsluiten\"</a>).",
    'aide_preventif.generation_li3' => "Ze blijft traceerbaar: vanuit de oorspronkelijke regel vindt de knop \"Historiek\" alle interventiebonnen die ze heeft gegenereerd.",
    'aide_preventif.generation_lock' => "Op de geplande dag en tijd start deze generatie automatisch via een geplande taak aan serverzijde, onafhankelijk van uw klikken in de interface. Als een normale vervaldatum niet is omgezet in een interventiebon zonder dat iemand eraan raakte, neem contact op met de systeembeheerder in plaats van te zoeken waarom op het scherm Preventief.",
    'aide_preventif.generation_tip1' => "De knop <b>⚡ \"Een aanvraag genereren\"</b> (op elke regelrij, en in de detailfiche) start dezelfde generatie onmiddellijk, op aanvraag — zonder op de normale vervaldatum te wachten. Nuttig om een per ongeluk gewiste aanvraag opnieuw aan te maken, of een net aangemaakte regel te testen. Net als de automatische generatie, maakt ze een <b>aanvraag in de validatiesluis</b> aan (zie <a href=\"aide_ot.php#portes\">het artikel \"Een interventiebon aanmaken & afsluiten\"</a>) — nooit rechtstreeks een interventiebon: die moet nog normaal gevalideerd worden.",
    'aide_preventif.generation_tip2' => "Er bestaat geen aanvinklijst op een preventieve interventiebon: de bij stap 4 ingevoerde instructies (beschrijving, oorzaak, onderdelen) worden gewoon als vrije tekst in de beschrijving van de interventiebon ingevoegd, te lezen als elk ander ticket.",
    'aide_preventif.gestion_lede' => "Op elke rij van de regellijst:",
    'aide_preventif.gestion_modifier_h4' => "Wijzigen",
    'aide_preventif.gestion_modifier_p' => "Klik op de rij om de detailfiche te openen, dan \"Wijzigen\" om de vooraf ingevulde wizard opnieuw te openen en om het even welk veld te wijzigen.",
    'aide_preventif.gestion_pause_h4' => "Pauzeren (Winter)",
    'aide_preventif.gestion_pause_p' => "Schorst de regel zonder ze te verwijderen: ze wordt grijs in de lijst en genereert geen interventiebonnen meer tot ze opnieuw wordt geactiveerd.",
    'aide_preventif.gestion_supprimer_h4' => "Verwijderen",
    'aide_preventif.gestion_supprimer_p' => "<b>Definitieve</b> verwijdering van de regel, met bevestiging. Reeds gegenereerde interventiebonnen blijven in de historiek — enkel de toekomstige planning stopt.",
    'aide_preventif.gestion_historique_h4' => "Historiek",
    'aide_preventif.gestion_historique_p' => "Vindt alle reeds gegenereerde voorvallen voor deze regel, met hun verwerkingsstatus.",
    'aide_preventif.planning_lede' => "Een wekelijks rooster: één rij per technicus, één kolom per dag (maandag tot zondag).",
    'aide_preventif.shot_grille_alt' => "Wekelijks planningrooster per technicus",
    'aide_preventif.shot_grille_cap' => "Elke gekleurde kaart stelt een interventiebon voor waarop de technicus die dag een tijdregistratie heeft, met zijn BI-nummer en de geplande tijd.",
    'aide_preventif.planning_li1' => "De pijltjes ◀ ▶ (in de balk boven het rooster) wisselen van week.",
    'aide_preventif.planning_li2' => "<b>Slepen en neerzetten</b> van een kaart naar een ander vakje om een technicus te herverdelen en/of de datum te verplaatsen.",
    'aide_preventif.planning_li3' => "Klikken op een kaart opent het volledige detail van de interventiebon, zoals op het scherm Invoer & Historiek.",
    'aide_preventif.planning_li4' => "Klikken op een leeg vakje (admin) opent het aanmaken van een nieuwe interventiebon, met technicus en dag al vooraf ingevuld, type vooraf ingesteld op \"Preventief\".",
    'aide_preventif.planning_warn' => "<b>Goed om te weten:</b> het slepen van een kaart werkt momenteel voor iedereen, technicus zowel als admin — een technicus kan dus een taak aan een collega herverdelen door ze te slepen, terwijl aanmaken vanuit een leeg vakje en verwijderen wel voorbehouden blijven aan admins. Goed om te weten om onbedoelde herverdelingen te vermijden.",
    'aide_preventif.planning_tip' => "Dit scherm dient ook om uw <b>betaald verlof, ADV, feestdagen en ziekteverlof</b> in te geven, en uw jaarurenregeling (doel 1607u) op te volgen. Om in detail te begrijpen hoe elk type dag wordt geteld — met de wettelijke formule en uitgewerkte voorbeelden — zie <a href=\"aide_annualisation.php\">het artikel \"Verlof, ADV & Jaarurenregeling\"</a>.",
    'aide_preventif.astuces_li1' => "<b>Wijs altijd een uitvoerder toe</b> aan een regel als u wilt dat ze op de Planning verschijnt.",
    'aide_preventif.astuces_li2' => "<b>Gebruik \"Pauzeren\"</b> in plaats van \"Verwijderen\" voor seizoensgebonden controles (bv. winterklaar maken) — u behoudt de historiek en kunt ze later opnieuw activeren.",
    'aide_preventif.astuces_li3' => "<b>Controleer regelmatig de filterchips</b> (\"Achterstallig\", \"Binnenkort\"): het is de snelste manier om afglijdende vervaldatums op te sporen.",
    'aide_preventif.astuces_li4' => "<b>Een preventieve interventiebon wordt precies zoals een curatieve behandeld</b>: dezelfde afsluiting, hetzelfde verplichte rapport — geen specifieke snelkoppeling om te zoeken.",
    'aide_preventif.astuces_li5' => "<b>Preventieve interventiebon per ongeluk gewist?</b> Vind de oorspronkelijke regel terug op het scherm Preventief en klik op ⚡ \"Een aanvraag genereren\" om ze opnieuw aan te maken in de validatiesluis, zonder op de volgende automatische vervaldatum te wachten.",
    'aide_preventif.gloss1_dt' => "Regel / Preventief schema",
    'aide_preventif.gloss1_dd' => "De definitie van een terugkerende controle: wat, waar, hoe vaak, voor wie.",
    'aide_preventif.gloss2_dt' => "Planningsmodus",
    'aide_preventif.gloss2_dd' => "Frequentie in dagen (bv. elke 30 dagen) of vaste weekdagen (bv. elke maandag).",
    'aide_preventif.gloss3_dt' => "Vervaldatum",
    'aide_preventif.gloss3_dd' => "De datum waarop de volgende controle verwacht wordt.",
    'aide_preventif.gloss4_dt' => "Tijdregistratie",
    'aide_preventif.gloss4_dd' => "Een geregistreerde tijdlijn voor een technicus op een interventiebon — dit is wat een kaart op de Planning doet verschijnen.",
    'aide_preventif.devnote_li1' => "De automatische generatie (<code>cron_preventif.php</code>) hangt af van een externe geplande taak (systeem-cron) die serverzijde te controleren is als normale vervaldatums niet omgezet worden in interventiebonnen. De knop ⚡ \"Een aanvraag genereren\" (actie <code>generer_demande</code> in <code>preventif_liste.php</code>) herhaalt dezelfde INSERT op aanvraag, buiten de cron-cyclus, zonder ooit <code>num_bi</code> in te vullen.",
    'aide_preventif.devnote_li2' => "Het vakje \"Auto ochtend\" (kolom <code>preventif_regles.auto_matin</code>) laat, bij generatie (cron of handmatige knop), de eerste technicus in alfabetische volgorde op de \"Ochtend\"-dienst van de dag in <code>planning_shifts</code> kiezen — leeg als niemand of meerdere, zonder terugval op de vaste uitvoerder van de regel.",
    'aide_preventif.devnote_li3' => "Op de Planning is het slepen en neerzetten (<code>action=update_pointage_planif</code>) serverzijde niet beperkt tot admins — enkel het aanmaken vanuit een leeg vakje en het verwijderen zijn dat clientzijde.",

    'aide_ot.page_title_tag' => "Een interventiebon aanmaken & afsluiten - Hulp GMAO",
    'aide_ot.hero_tagline' => "De volledige gids voor de interventiebon, van de gemelde storing tot het afgesloten rapport.",
    'aide_ot.pill_version' => "Versie <b>1.4</b>",
    'aide_ot.pill_updated' => "Bijgewerkt op <b>11/09/2026</b>",
    'aide_ot.pill_ecrans' => "Betreft scherm <b>Invoer &amp; Geschiedenis</b>",
    'aide_ot.toc_vue_ensemble' => "Overzicht",
    'aide_ot.toc_portes' => "De 2 manieren om een BI aan te maken",
    'aide_ot.toc_formulaire' => "De aanmaakwizard gebruiken",
    'aide_ot.toc_assistant_intelligent' => "De slimme gids (duplicaten)",
    'aide_ot.toc_cycle' => "De levenscyclus van een BI",
    'aide_ot.toc_prise_en_charge' => "In behandeling nemen",
    'aide_ot.toc_cloture' => "Een BI afsluiten",
    'aide_ot.toc_cas_particuliers' => "Bijzondere gevallen",
    'aide_ot.toc_droits' => "Wie mag wat doen",
    'aide_ot.toc_astuces' => "Tips & valkuilen",
    'aide_ot.toc_glossaire' => "Woordenlijst",
    'aide_ot.vue_ensemble_lede' => "Een <b>BI</b> (werkorder) — is de fiche die een onderhoudsinterventie volgt van het allereerste begin (een gemelde storing) tot het einde (het geschreven rapport). Deze gids toont u, scherm per scherm, hoe u ze aanmaakt, in behandeling neemt en correct afsluit.",
    'aide_ot.journey_creer' => "Aanmaken",
    'aide_ot.journey_prendre' => "In behandeling nemen",
    'aide_ot.journey_intervenir' => "Uitvoeren",
    'aide_ot.journey_cloturer' => "Afsluiten",
    'aide_ot.shot_cartes_alt' => "Overzichtskaarten per technicus op het scherm Invoer & Geschiedenis",
    'aide_ot.shot_cartes_cap' => "Bovenaan het scherm \"Invoer & Geschiedenis\" vat een kaart per technicus hun werklast samen: urgenties, te doen, in uitvoering, afgerond, en de reeds geregistreerde tijd.",
    'aide_ot.callout_numero_bi' => "<b>Het BI-nummer</b> wordt automatisch gegenereerd bij het aanmaken, in het formaat <code>BI</code> + jaar + nummer, bijvoorbeeld <code>BI26-014</code>. U hoeft het nooit zelf te verzinnen: noteer het gewoon wanneer u er met iemand over moet spreken (telefoon, werkplaats, vergadering).",
    'aide_ot.portes_lede' => "Een BI kan op twee verschillende manieren in uw tabel terechtkomen. Het is belangrijk ze uit elkaar te kunnen houden.",
    'aide_ot.route1_tag' => "Scherm Invoer & Geschiedenis",
    'aide_ot.route1_titre' => "Rechtstreeks aanmaken",
    'aide_ot.route1_p1' => "U (technicus of admin) maakt de interventiebon zelf aan door op de tegel <b>\"Een interventiebon aanmaken\"</b> te klikken, die een geleide wizard in 4 stappen opent. Dit is de methode om te gebruiken wanneer <b>u</b> zelf een storing of een uit te voeren taak vaststelt.",
    'aide_ot.route1_p2' => "Het ticket verschijnt onmiddellijk in de tabel met de status <span class=\"pill pill-afaire\"><span class=\"pill-dot\"></span>Te doen</span> — klaar om behandeld te worden.",
    'aide_ot.route2_tag' => "Portaal \"Werkaanvraag\"",
    'aide_ot.route2_titre' => "Aanvraag van een andere dienst",
    'aide_ot.route2_p1' => "Een operator, Productie, Kwaliteit of een andere dienst dient een aanvraag in met naam en persoonlijke pincode (zie <a href=\"aide_service.php#demande\">het bijbehorende artikel</a>). Het ticket komt binnen met de status <span class=\"pill pill-attente\"><span class=\"pill-dot\"></span>In afwachting</span>, <b>zonder BI-nummer</b>.",
    'aide_ot.route2_p2' => "Het verschijnt in de rode balk \"aanvra(a)g(en) in afwachting van validatie\". Het is aan u om ze te openen en te valideren zodat ze een echte BI wordt.",
    'aide_ot.shot_bandeau_alt' => "Rode waarschuwingsbalk die aanvragen in afwachting van validatie aangeeft",
    'aide_ot.shot_bandeau_cap' => "Deze balk verschijnt bovenaan het scherm zodra een externe aanvraag wacht om in een BI te worden omgezet.",
    'aide_ot.shot_sas_alt' => "Validatievenster met de lijst van aanvragen in afwachting",
    'aide_ot.shot_sas_cap' => "Het \"validatiesas\": elk dossier toont de beschrijving, de bijgevoegde foto's en een Urgent-badge indien als zodanig gemeld, en biedt vervolgens Weigeren, Berichten, BI aanmaken (met technicus en datum vooraf ingevuld) — en voor een admin, Naar preventief.",
    'aide_ot.callout_photos' => "De fiche van een dossier toont voortaan alles wat de aanvrager heeft aangeleverd: de <b>bijgevoegde foto's</b> (met zoom bij klik), een duidelijk zichtbare <b>\"Urgent\"</b>-badge als de aanvraag als zodanig werd gemeld, en het aantal reeds uitgewisselde berichten rechtstreeks op de knop <b>Berichten</b> — genoeg om de situatie te beoordelen zonder elk tabblad te moeten openen.",
    'aide_ot.callout_mobile' => "Op telefoon en tablet opent het sas eerst op een lijst met compacte <b>badges</b> (dossiernummer, aanvrager, uitrusting, storingsbeschrijving, datum/uur, rode stip indien urgent) in plaats van de volledige fiche. Een tik op een badge toont de fiche in volledig scherm, met een knop \"Terug naar lijst\" bovenaan om terug te gaan zonder de andere dossiers te verliezen.",
    'aide_ot.callout_refuser' => "<b>Weigeren</b> wist niets: het dossier krijgt een echt BI-nummer (status <span class=\"pill pill-refuse\"><span class=\"pill-dot\"></span>Geweigerd</span>) en blijft zichtbaar in de Globale Geschiedenis, met de naam van wie geweigerd heeft en een verplichte reden van minstens 20 tekens — een echt verslag (\"fabriek volledig aan het ontdooien, geen productie die dag\"), geen \"nvt\" of \"ok\". Dit garandeert dat een audit voor <b>elke</b> gegenereerde preventieve taak een spoor terugvindt, ook die welke niet tot een interventie hebben geleid.",
    'aide_ot.callout_vers_preventif' => "<b>Naar preventief</b> (enkel admins): voor een eenmalige aanvraag die niet meteen een BI moet worden (bv. \"het paneel 2 meter laten zakken\"), voegt deze knop ze rechtstreeks toe aan het tabblad <b>\"Winterwerk\"</b> van de categorie \"Winteronderhoud\" van het <a href=\"preventif.php\">Preventief Plan</a> — een af te vinken takenlijst, zonder frequentie of automatische BI-generatie (zie <a href=\"aide_preventif.php#travaux-divers\">het detail in de hulp Preventief</a>). De oorspronkelijke aanvraag wordt verwijderd zodra ze aan deze lijst is toegevoegd. Voor een echt terugkerende behoefte (zeldzaam vanuit een aanvraag), maak dan liever een klassieke regel aan via \"Nieuwe regel\" op de pagina Preventief.",
    'aide_ot.callout_warn_etiquette' => "Op het portaal \"Werkaanvraag\" ziet u soms het label <b>\"In afwachting van validatie\"</b>. Dat is een duidelijkere weergavetekst voor de aanvrager — in de database blijft de werkelijke status <code>En attente</code>, dezelfde die u via de rode balk behandelt.",
    'aide_ot.formulaire_lede' => "Een klik op de tegel <b>\"Een interventiebon aanmaken\"</b> opent een venster in 4 stappen. Elke stap kan op elk moment via de zijbalk worden herzien, en elk veld heeft een kleine hulpbubbel <i class=\"fa-solid fa-circle-question\" style=\"color:var(--accent);\"></i> om bij twijfel op te klikken.",
    'aide_ot.callout_lock_assistant' => "Zolang het venster open staat, annuleert een klik ernaast het <b>nooit</b> — enkel de knop <b>\"Annuleren\"</b> of het kruisje rechtsboven sluiten de wizard (en verliezen de lopende invoer). Dit is bewust zo, om te voorkomen dat een half ingevulde bon verloren gaat door een ongelukkige klik.",
    'aide_ot.step1_titre' => "Wie",
    'aide_ot.step1_desc' => "De aanvrager, en indien nodig, het externe bedrijf dat de interventie uitvoert.",
    'aide_ot.step2_titre' => "Locatie",
    'aide_ot.step2_desc' => "De cascade Fabriek → Sector → Lijn → Zone → Machine.",
    'aide_ot.step3_titre' => "Details",
    'aide_ot.step3_desc' => "Datum, type, prioriteit, breuk, schroefverbindingscontrole en beschrijving.",
    'aide_ot.step4_titre' => "Samenvatting",
    'aide_ot.step4_desc' => "Herlezing van alle velden, gevolgd door een klik op \"Interventieticket aanmaken\".",
    'aide_ot.shot_etape1_alt' => "Stap 1 van de wizard: de aanvrager",
    'aide_ot.shot_etape1_cap' => "Stap 1 — Wie meldt de interventie.",
    'aide_ot.shot_etape2_alt' => "Stap 2 van de wizard: de locatie",
    'aide_ot.shot_etape2_cap' => "Stap 2 — De locatiecascade.",
    'aide_ot.shot_etape3_alt' => "Stap 3 van de wizard: de interventiedetails",
    'aide_ot.shot_etape3_cap' => "Stap 3 — Type, prioriteit en beschrijving.",
    'aide_ot.shot_etape4_alt' => "Stap 4 van de wizard: de samenvatting",
    'aide_ot.shot_etape4_cap' => "Stap 4 — De samenvatting vóór bevestiging.",
    'aide_ot.tbl_th_champ' => "Veld",
    'aide_ot.tbl_th_etape' => "Stap",
    'aide_ot.tbl_th_description' => "Beschrijving",
    'aide_ot.tbl_th_obligatoire' => "Verplicht?",
    'aide_ot.req_auto' => "Auto",
    'aide_ot.req_si_besoin' => "Indien nodig",
    'aide_ot.req_conseille' => "Aanbevolen*",
    'aide_ot.row1_champ' => "Aanvrager",
    'aide_ot.row1_desc' => "Uw naam. Vooraf ingevuld en vergrendeld voor een technicus; een admin kan om het even wie kiezen.",
    'aide_ot.row2_champ' => "Geplande technicus",
    'aide_ot.row2_desc' => "Enkel admins: iemand vooraf toewijzen bij het aanmaken.",
    'aide_ot.row3_champ' => "Extern bedrijf",
    'aide_ot.row3_desc' => "Vink \"onderaannemer-interventie\" aan en kies vervolgens het bedrijf als de taak aan een externe dienstverlener wordt toevertrouwd.",
    'aide_ot.row4_champ' => "Locatie → Sector → Lijn → Zone → Machine",
    'aide_ot.row4_desc' => "Cascaderende locatie: elk menu wordt vrijgegeven zodra het vorige is ingevuld. Als de machine nog niet in de database bestaat, wordt het veld een vrij invoerveld.",
    'aide_ot.row5_champ' => "Datum",
    'aide_ot.row5_desc' => "Datum van de interventie, standaard vandaag.",
    'aide_ot.row6_champ' => "Type",
    'aide_ot.row6_desc' => "Curatief / Preventief / Werf.",
    'aide_ot.row7_champ' => "Prioriteit",
    'aide_ot.row7_desc' => "Normaal of Urgent — Urgent doet het ticket in de tabel knipperen.",
    'aide_ot.row8_champ' => "Breuk",
    'aide_ot.row8_desc' => "Aanvinken als de interventie materiaalbreuk betreft.",
    'aide_ot.row9_champ' => "Schroefverbindingscontrole",
    'aide_ot.row9_desc' => "Aanvinken als de interventie een aanhaal-/schroefcontrole omvat.",
    'aide_ot.row10_champ' => "Beschrijving",
    'aide_ot.row10_desc' => "De tekst die de storing of de uit te voeren taak uitlegt.",
    'aide_ot.callout_warn_champs' => "<b>* Geen enkel veld is technisch verplicht</b> — de wizard laat u stap voor stap verdergaan, zelfs als machine of beschrijving leeg blijven. Omdat het kan, wil dat niet zeggen dat het een goed idee is: een BI zonder machine of beschrijving is onleesbaar voor de collega die ze overneemt. Vul altijd minstens <b>Machine</b>, <b>Type</b> en <b>Beschrijving</b> in.",
    'aide_ot.callout_tip_bulle' => "Twijfel over een veld? Klik op het bijhorende icoon <i class=\"fa-solid fa-circle-question\"></i> — een geïllustreerde hulpbubbel opent met concrete voorbeelden, zonder de wizard te verlaten.",
    'aide_ot.assistant_intelligent_lede' => "Terwijl u de wizard invult, verschijnen automatisch twee contextuele kaders om u te helpen geen bon opnieuw aan te maken die al op dezelfde machine bestaat.",
    'aide_ot.step_historique_titre' => "Stap 2 — Geschiedenis van de machine",
    'aide_ot.step_historique_desc' => "Zodra een machine geselecteerd is, toont een blauw kader alle reeds op haar geregistreerde bonnen (hoeveel in totaal, hoeveel nog open), met de status en datum van elk. De lijst scrollt als ze lang is.",
    'aide_ot.step_similaires_titre' => "Stap 3 — Vergelijkbare bonnen",
    'aide_ot.step_similaires_desc' => "Tijdens het invullen van de beschrijving verschijnt een oranje kader als een of meer bestaande bonnen een vergelijkbare beschrijving hebben (overlap van trefwoorden, met prioriteit voor dezelfde machine) — tot 3 suggesties, de meest gelijkende eerst.",
    'aide_ot.callout_tip_clic_suggestion' => "Klikken op een voorgestelde bon vraagt om bevestiging, en <b>sluit vervolgens de lopende wizard</b> en opent de bestaande bon: de bewerkingswizard als die nog actief is, of rechtstreeks <b>het rapport-/afsluitvenster</b> als hij al afgerond is — om te zien wat al gedaan is voordat u beslist of u erop verdergaat in plaats van een nieuwe aan te maken.",
    'aide_ot.callout_warn_aide_pas_ia' => "Dit is <b>een hulpmiddel, geen AI</b>: de overlap gebeurt enkel op basis van gedeelde trefwoorden in de beschrijving, zonder verzending naar een externe dienst. Niets is ooit blokkerend — deze kaders verhinderen niet dat u een nieuwe bon aanmaakt, ze helpen enkel een duplicaat op te sporen vóór bevestiging.",
    'aide_ot.cycle_lede' => "Een BI doorloopt een reeks statussen, weergegeven als gekleurde badges in de tabel. Hier is het volledige traject, en wie elke stap in gang zet.",
    'aide_ot.pill_en_attente' => "In afwachting",
    'aide_ot.pill_a_faire' => "Te doen",
    'aide_ot.pill_en_cours' => "In uitvoering",
    'aide_ot.pill_terminee' => "Afgerond",
    'aide_ot.pill_urgent' => "Urgent",
    'aide_ot.pill_refusee' => "Geweigerd",
    'aide_ot.cy_attente_trig' => "Aanvraag aangemaakt door een andere dienst",
    'aide_ot.cy_attente_who' => "Via het portaal",
    'aide_ot.cy_afaire_trig' => "Validatie in de rode balk → BI-nummer toegekend",
    'aide_ot.cy_afaire_who' => "Onderhoud",
    'aide_ot.cy_cours_trig' => "Klik op de statusbadge in de tabel",
    'aide_ot.cy_cours_who' => "Technicus",
    'aide_ot.cy_termine_trig' => "Nieuwe klik + interventierapport ingevuld",
    'aide_ot.cy_termine_who' => "Technicus",
    'aide_ot.shot_tableau_alt' => "Interventietabel met gekleurde statusbadges",
    'aide_ot.shot_tableau_cap' => "De interventietabel: elke statusbadge is klikbaar om de BI naar de volgende stap te laten overgaan. Merk het hangslot \"Invoer gesloten\" op zodra het ticket afgerond is.",
    'aide_ot.callout_lock_reouverture' => "<b>Heropenen:</b> een \"Afgerond\" BI kan met een eenvoudige klik op zijn statusbadge, na bevestiging, terug op \"Te doen\" worden gezet — maar enkel door een <b>administrator</b>. Bent u technicus en moet u een per ongeluk afgesloten dossier heropenen, vraag het dan aan een admin. Deze regel geldt ook wanneer u een reeds afgesloten bon opent via de <a href=\"#assistant-intelligent\">slimme gids</a> van de wizard: een technicus ziet het rapport daar in <b>alleen-lezen</b> (rapport en knoppen \"+ TIJD\" / \"Opslaan, laten openstaan\" uitgeschakeld), enkel een admin kan het vanuit dat venster wijzigen of heropenen.",
    'aide_ot.callout_tip_urgent' => "<b>\"Urgent\" is geen aparte status</b>: het is een prioriteit ingesteld bij het aanmaken, die de badge <span class=\"pill pill-urgent pulse-badge\"><span class=\"pill-dot\"></span>Urgent</span> rood laat knipperen zolang het ticket \"Te doen\" is. Eenmaal in behandeling genomen, wordt het opnieuw een gewone \"In uitvoering\"-badge.",
    'aide_ot.prise_en_charge_lede' => "Niets eenvoudiger: zoek in de interventietabel de statusbadge van de betreffende rij op.",
    'aide_ot.pec_step1_titre' => "Zoek een \"Te doen\"-ticket op",
    'aide_ot.pec_step1_desc' => "Gebruik de tellers bovenaan de tabel (Urgent / Te doen / In uitvoering / Afgerond) om snel te filteren, of blader door de lijst.",
    'aide_ot.pec_step2_titre' => "Klik rechtstreeks op de statusbadge",
    'aide_ot.pec_step2_desc' => "Een enkele klik op de badge zet het ticket op \"In uitvoering\". Geen bevestigingsvenster.",
    'aide_ot.pec_step3_titre' => "Automatisch wordt een tijdregistratie van 0u voor u aangemaakt",
    'aide_ot.pec_step3_desc' => "Als er nog geen tijd op dit ticket geregistreerd was, maakt de app een tijdregistratie op uw naam aan (0u, ticketdatum). Deze registratie is wat u als technicus op de fiche doet verschijnen — denk er daarna aan uw werkelijke tijd bij te werken via de knop <b>\"+ TIJD\"</b>.",
    'aide_ot.callout_warn_pec' => "Een ticket op \"In uitvoering\" zetten <b>wijst het niet formeel aan u toe</b> — het oorspronkelijke veld \"aanvrager\" verandert niet, en er wordt geen tijdstip van inbehandelingneming vastgelegd. Uw tijdregistratie geldt als bewijs als meerdere personen op dezelfde BI werken.",
    'aide_ot.cloture_lede' => "Dit is de belangrijkste stap: hier wordt uw werk een echte, bruikbare onderhoudsgeschiedenis.",
    'aide_ot.clo_step1_titre' => "Klik opnieuw op de statusbadge",
    'aide_ot.clo_step1_desc' => "Op een \"In uitvoering\"-ticket opent deze tweede klik het afsluitvenster in plaats van de status rechtstreeks te wijzigen.",
    'aide_ot.clo_step2_titre' => "Controleer de weergegeven samenvatting",
    'aide_ot.clo_step2_desc' => "BI-nummer, locatie/machine, totale reeds geregistreerde tijd, aanvrager, technicus(en) en storingsbeschrijving worden alleen-lezen bovenaan het venster getoond.",
    'aide_ot.clo_step3_titre' => "Schrijf het \"Technisch Interventierapport\"",
    'aide_ot.clo_step3_desc' => "Dit is <b>het enige verplichte veld in het hele BI-traject.</b> Beschrijf de uitgevoerde corrigerende acties: diagnose, vervangen onderdelen, afstellingen, uitgevoerde tests. Wees concreet — dit is de tekst die een collega herleest bij een terugkerende storing.",
    'aide_ot.clo_step4_titre' => "Klik op \"Afsluiting Bevestigen\"",
    'aide_ot.clo_step4_desc' => "De status gaat naar \"Afgerond\", een bevestigingsbericht verschijnt, en de tijdregistratie wordt in de tabel vergrendeld (badge <b>\"🔒 Invoer gesloten\"</b> in plaats van de knop \"+ TIJD\").",
    'aide_ot.shot_modale_alt' => "Afsluitvenster van de interventie met het verplichte rapportveld",
    'aide_ot.shot_modale_cap' => "Het afsluitvenster: locatie, opgetelde tijd, aanvrager en technici worden alleen-lezen herinnerd boven het veld \"Technisch Interventierapport\".",
    'aide_ot.callout_warn_rapport_vide' => "Als u het rapport leeg laat, weigert de app de afsluiting met het bericht <b>\"Gelieve een technisch verslag in te vullen vóór het afsluiten\"</b>. Dat is normaal: zonder deze tekst zou de BI geen enkele historische waarde hebben.",
    'aide_ot.callout_tip_enregistrer_ouvert' => "<b>Nog niet klaar? Een knop \"Opslaan, laten openstaan\"</b> is beschikbaar net naast \"Afsluiting Bevestigen\". Ze slaat het reeds geschreven rapport op en zet de bon terug op \"In uitvoering\", zonder een afgewerkte tekst te vereisen — handig om te noteren waar u staat zonder een voortijdige afsluiting te forceren. Een knop <b>\"+ TIJD\"</b> is ook rechtstreeks in dit venster aanwezig om een registratie toe te voegen zonder het te sluiten.",
    'aide_ot.callout_tip_carnet' => "<b>Het logboek:</b> zolang de BI niet afgerond is, biedt de detailfiche een zone <b>\"tussentijdse nota\"</b> (bv.: \"onderdeel deze ochtend besteld, in afwachting van levering\"). Gebruik ze om voortgangssporen bij te houden — eenmaal de BI afgesloten is, worden deze nota's een alleen-lezen geschiedenis, los van het eindrapport.",
    'aide_ot.callout_tip_demandeur_voit' => "<b>De aanvrager ziet meer details zodra de BI afgerond is:</b> voor een ticket aangemaakt vanuit het portaal \"Werkaanvraag\" vindt de dienst die de aanvraag deed, in zijn eigen opvolging, de opgetelde <b>interventie-uren</b> (het totaal van de registraties), de <b>uitvoeringsdatum</b> (datum van de laatste registratie), en elke aan de BI gekoppelde <b>foto</b> terug — houd hiermee rekening, deze informatie blijft niet beperkt tot uw interne tools.",
    'aide_ot.callout_lock_pdf' => "Vanuit de detailfiche genereert de knop <b>\"EXPORTEREN ALS PDF\"</b> op elk moment een afdrukbaar rapport met de naam <code>RI_&lt;BI-nummer&gt;.pdf</code>.",
    'aide_ot.cas_particuliers_lede' => "Enkele situaties die buiten het standaardtraject vallen.",
    'aide_ot.case_soustraitance_titre' => "Onderaannemer-interventie",
    'aide_ot.case_soustraitance_desc' => "Vink \"onderaannemer-interventie\" aan bij het aanmaken en kies het externe bedrijf. De fiche toont dan \"Onderaannemer: …\" en een knop <b>\"PDP GENEREREN\"</b> (preventieplan) verschijnt.",
    'aide_ot.case_urgent_titre' => "Prioriteit Urgent",
    'aide_ot.case_urgent_desc' => "Een \"Te doen\"-ticket met label Urgent toont een knipperende rode bel in de tabel. Behandel het bij voorrang — het knipperen stopt zodra het naar \"In uitvoering\" overgaat.",
    'aide_ot.case_messagerie_titre' => "Berichten op een ticket",
    'aide_ot.case_messagerie_desc' => "Voor tickets afkomstig van een externe aanvraag laat een knop \"BERICHTEN\" toe rechtstreeks op het ticket met de aanvrager te communiceren. Ongelezen berichten tonen een rode stip en een specifiek filter in de tabel.",
    'aide_ot.case_suppression_titre' => "Een BI verwijderen",
    'aide_ot.case_suppression_desc' => "Mogelijk individueel (vuilbakicoon) of in bulk (meervoudige selectie). <b>Enkel voor administrators</b> — een technicus die het probeert ziet een weigeringsbericht.",
    'aide_ot.case_impression_titre' => "Een fiche afdrukken voor het bord",
    'aide_ot.case_impression_desc' => "Het printericoon op een BI genereert een compacte fiche — machine, locatie, beschrijving, toegewezen technicus(i), logboek — om op te hangen op het bord in de werkplaats. Om er meerdere tegelijk af te drukken, vink de BI's aan en klik op <b>\"Selectie afdrukken\"</b>: elke fiche wordt op dezelfde grootte afgedrukt, 2 per lijn. <b>Meervoudige selectie is enkel voor administrators</b>, net als voor verwijderen.",
    'aide_ot.droits_lede' => "Het scherm past zich aan uw rol aan. Hier de samenvatting.",
    'aide_ot.tbl_th_action' => "Actie",
    'aide_ot.tbl_th_technicien' => "Technicus",
    'aide_ot.tbl_th_admin' => "Admin",
    'aide_ot.droit1_action' => "Een BI aanmaken",
    'aide_ot.droit2_action' => "Vrij de aanvrager kiezen",
    'aide_ot.droit2_tech' => "Vergrendeld op zichzelf",
    'aide_ot.droit3_action' => "Een technicus vooraf toewijzen bij het aanmaken",
    'aide_ot.droit4_action' => "Een BI in behandeling nemen / afsluiten",
    'aide_ot.droit5_action' => "De tijdregistratie van een collega wijzigen",
    'aide_ot.droit5_tech' => "Enkel eigen registraties",
    'aide_ot.droit6_action' => "Een BI verwijderen",
    'aide_ot.droit7_action' => "Een afgesloten BI heropenen",
    'aide_ot.droit8_action' => "Tijd toevoegen / het rapport van een reeds afgesloten BI wijzigen",
    'aide_ot.droit8_tech' => "Alleen-lezen",
    'aide_ot.droit9_action' => "Toegang tot Preventief, KPI, Stats, Machinepark, Gebruikers",
    'aide_ot.droit9_tech' => "Menu's verborgen",
    'aide_ot.astuces_li1' => "<b>Vul altijd de beschrijving in</b>, ook al is het kort — het is het veld dat uw collega's, en uzelf, drie maanden later het meest lezen.",
    'aide_ot.astuces_li2' => "<b>Registreer uw tijd gaandeweg</b> in plaats van op het laatste moment: eenmaal de BI afgesloten is, wordt de tijdregistratie vergrendeld.",
    'aide_ot.astuces_li3' => "<b>Laat een BI niet onbeperkt \"In uitvoering\" staan</b> — gebruik het logboek (tussentijdse nota) om aan te geven waar u staat als de interventie zich over meerdere dagen uitspreidt.",
    'aide_ot.astuces_li4' => "<b>Een BI zonder geselecteerde machine</b> blijft bruikbaar maar bemoeilijkt de statistieken per uitrusting — geef altijd de voorkeur aan de cascade Fabriek → Sector → Lijn → Zone → Machine.",
    'aide_ot.astuces_li5' => "<b>Een onbehandelde externe aanvraag</b> blijft onzichtbaar voor de aanvrager zolang ze geen BI-nummer heeft: denk eraan regelmatig de rode validatiebalk te controleren.",
    'aide_ot.astuces_li6' => "<b>Vóór het bevestigen van een nieuwe bon</b>, werp een blik op de kaders van de <a href=\"#assistant-intelligent\">slimme gids</a> (stappen 2 en 3): als een zeer gelijkende bon al bestaat en niet afgerond is, kunt u er beter op verdergaan dan een duplicaat te openen.",
    'aide_ot.gloss1_dt' => "BI",
    'aide_ot.gloss1_dd' => "\"Bon d'Intervention\" — de algemene naam voor elke interventie die in de GMAO wordt opgevolgd, zodra ze een nummer heeft (bv. BI26-014).",
    'aide_ot.gloss2_dt' => "Aanvrager",
    'aide_ot.gloss2_dd' => "De persoon die het ticket aanmaakte of de storing meldde.",
    'aide_ot.gloss3_dt' => "Tijdregistratie",
    'aide_ot.gloss3_dd' => "Een geregistreerde tijdlijn, gekoppeld aan een technicus en een ticket.",
    'aide_ot.gloss4_dt' => "Validatiesas",
    'aide_ot.gloss4_dd' => "De rode balk met de lijst van externe aanvragen \"In afwachting\" die naar BI omgezet moeten worden.",
    'aide_ot.gloss5_dt' => "PDP",
    'aide_ot.gloss5_dd' => "Preventieplan — document gegenereerd voor een interventie toevertrouwd aan een extern bedrijf.",
    'aide_ot.gloss6_dt' => "Logboek",
    'aide_ot.gloss6_dd' => "De tussentijdse nota van een lopende BI, zichtbaar zolang ze niet afgesloten is.",
    'aide_ot.gloss7_dt' => "Interventierapport",
    'aide_ot.gloss7_dd' => "Het eindverslag, het enige verplichte veld om een BI af te sluiten.",
    'aide_ot.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan administratiezijde:",
    'aide_ot.devnote_li1' => "Geen enkel veld van de aanmaakwizard is applicatiezijde geblokkeerd (geen <code>required</code>-attribuut, navigeren tussen stappen legt geen enkele validatie op) — de invoerdiscipline rust volledig op het team.",
    'aide_ot.devnote_li2' => "De rechtencontrole (verwijderen, heropenen, bewerken van registraties van anderen) gebeurt <b>enkel clientzijde</b>: <code>api.php</code> controleert de rol niet opnieuw voor deze acties. De alleen-lezenvergrendeling van het afsluitvenster voor een reeds afgeronde BI (nieuw met de slimme gids) volgt dezelfde logica — het is een interfacebeveiliging, geen serverbeveiliging.",
    'aide_ot.devnote_li3' => "De op het aanvragersportaal getoonde status \"In afwachting van validatie\" komt in de database overeen met de status <code>En attente</code> — geen aparte waarde opgeslagen.",
    'aide_ot.devnote_li4' => "De duplicaatdetectie van de wizard (<code>#assistant-intelligent</code>) draait volledig clientzijde op reeds geladen gegevens (<code>tasks</code>): overlap van trefwoorden (Jaccard-score, drempel 0.25), geen netwerkoproep of externe dienst.",

    'aide_planning.page_title_tag' => "De planning begrijpen & invullen - Hulp GMAO",
    'aide_planning.hero_tagline' => "Het weekrooster, de aan te vinken vakjes, en hoe ze uw urensaldo doen bewegen.",
    'aide_planning.pill_version' => "Versie <b>1.1</b>",
    'aide_planning.pill_updated' => "Bijgewerkt op <b>18/09/2026</b>",
    'aide_planning.pill_ecrans' => "Betreft scherm <b>Planning</b>",
    'aide_planning.toc_vue_ensemble' => "Overzicht",
    'aide_planning.toc_naviguer' => "Navigeren tussen weken",
    'aide_planning.toc_remplir_case' => "Een vakje invullen",
    'aide_planning.toc_cases_evenements' => "Elk vakje in detail",
    'aide_planning.toc_avance_retard' => "Het urensaldo uitgelegd",
    'aide_planning.toc_exemple' => "Uitgewerkt voorbeeld, week per week",
    'aide_planning.toc_remplissage_rapide' => "Meerdere dagen tegelijk invullen",
    'aide_planning.toc_bons_intervention' => "De interventiebonnen op de planning",
    'aide_planning.toc_todo_list' => "De TODO-lijst van de dag",
    'aide_planning.toc_planning_annuel' => "De Jaarplanning",
    'aide_planning.toc_droits' => "Wie mag wat doen",
    'aide_planning.toc_astuces' => "Tips & valkuilen",
    'aide_planning.toc_glossaire' => "Woordenlijst",
    'aide_planning.vue_ensemble_lede' => "De <b>Planning</b> is een rooster: één rij per technicus, één kolom per dag van de week. Elk vakje kan een <b>gewerkte dienst</b> krijgen (ochtend, middag, nacht...), een <b>gebeurtenis</b> (verlof, ADV, ziekte...), een <b>wachtdienst</b>, en het aantal <b>gewerkte uren</b>. Diezelfde invoer voedt automatisch uw teller van jaarlijkse uren en de indicator \"voorsprong / achterstand\" die u op uw fiche ziet.",
    'aide_planning.shot_grille_alt' => "Wekelijks planningsrooster met één rij per technicus",
    'aide_planning.shot_grille_cap' => "Het weekrooster: links, elke technicus met zijn weekurentotaal en zijn jaartotaal; in het midden, één vakje per dag.",
    'aide_planning.vue_ensemble_p2' => "In elk vakje kunt u tot drie dingen zien:",
    'aide_planning.vue_li1' => "<b>Een dienst-/gebeurtenisbadge</b> — kleur + label (bv. \"Ochtend · 7u\", \"Verlof\", \"ADV\").",
    'aide_planning.vue_li2' => "<b>Een of meer interventiebonnen (BI)</b> — de kleine genummerde etiketten, als de technicus die dag tijd op een interventie heeft geregistreerd.",
    'aide_planning.vue_li3' => "<b>Een notitie-icoon</b> <i class=\"fa-solid fa-note-sticky\" style=\"color:var(--brand-orange);\"></i> — als er een opmerking is achtergelaten (bv. \"om 9u aangekomen, om 15u30 vertrokken\").",
    'aide_planning.callout_annuel' => "Klikken op de naam, avatar of het totaal van een technicus (het blok links) opent rechtstreeks zijn <a href=\"#planning-annuel\"><b>Jaarplanning</b></a> — de volledige kalender van het jaar, niet enkel de getoonde week.",
    'aide_planning.toc_vues_affichage' => "Dag- / Week- / Maandweergave",
    'aide_planning.vues_affichage_lede' => "Een keuzeknop bovenaan de pagina laat je de hele weergave wijzigen, zonder de pagina te verlaten:",
    'aide_planning.vue_jour_titre' => "Dagweergave",
    'aide_planning.vue_jour_desc' => "Alle technici op één dag, onder elkaar — handig om in één oogopslag te zien wie vandaag beschikbaar is.",
    'aide_planning.vue_semaine_titre' => "Weekweergave",
    'aide_planning.vue_semaine_desc' => "De gebruikelijke weergave, ongewijzigd: het weekrooster, technicus per technicus.",
    'aide_planning.vue_mois_titre' => "Maandweergave",
    'aide_planning.vue_mois_desc' => "Een kalender per technicus voor de hele maand. Je kunt er een werkbon verslepen zoals in de Weekweergave (dezelfde rechten), erop klikken om het rapport te openen, over het etiket zweven voor een snelle preview (uitrusting, beschrijving, tijd, status), en van maand wisselen met de pijlen aan de randen van het scherm.",
    'aide_planning.callout_vues_affichage' => "Van weergave wisselen verandert geen enkele gegeven: het is gewoon een andere manier om dezelfde planning weer te geven.",
    'aide_planning.naviguer_lede' => "Drie manieren om van week te veranderen, allemaal gelijkwaardig:",
    'aide_planning.case_fleches_titre' => "De pijlen aan de randen",
    'aide_planning.case_fleches_desc' => "Twee halfdoorzichtige pijlen kleven aan de linker- en rechterrand van het scherm, zowel in de Week- als de Maandweergave. Een klik gaat een week terug of vooruit (een maand in de Maandweergave).",
    'aide_planning.case_glisser_titre' => "Een interventiebon naar de rand slepen",
    'aide_planning.case_glisser_desc' => "Terwijl u een BI versleept, brengt u hem dicht bij de linker- of rechterrand van het scherm: de week scrollt automatisch (met een markering \"Week XX\" op het scherm) om de BI op een andere week neer te zetten zonder de muis los te laten.",
    'aide_planning.case_repere_titre' => "De markering \"Week XX\"",
    'aide_planning.case_repere_desc' => "Bovenaan het scherm bevestigen het weeknummer en de exacte data (\"van ... tot ...\") altijd de bekeken periode.",
    'aide_planning.remplir_case_lede' => "Klik ergens in een vakje (leeg of met een bestaande badge): een keuzevenster opent en vraagt wat je wilt doen.",
    'aide_planning.choix_heures_titre' => "Uren plannen",
    'aide_planning.choix_heures_desc' => "Opent het gebruikelijke planningsvenster (Dienst, Gebeurtenis, Wachtdienst, Uren, Notitie) hieronder beschreven.",
    'aide_planning.choix_bi_titre' => "Een werkorder aanmaken",
    'aide_planning.choix_bi_desc' => "Verwijst naar <b>Invoer & Historiek</b>, waar de aanmaakassistent opent met de technicus en datum al vooraf ingevuld.",
    'aide_planning.choix_todo_titre' => "TODO-lijst",
    'aide_planning.choix_todo_desc' => "Opent de persoonlijke takenlijst van de technicus voor die dag — zie de sectie \"De TODO-lijst van de dag\" hieronder.",
    'aide_planning.remplir_case_suite' => "De rest van deze sectie beschrijft wat er gebeurt zodra \"Uren plannen\" is gekozen.",
    'aide_planning.shot_modal_alt' => "Planningsvenster van een vakje: Dienst, Gebeurtenis, Wachtdienst, Uren, Notitie",
    'aide_planning.shot_modal_cap' => "Het venster dat opent bij een klik op een vakje: drie groepen aan te klikken \"chips\" (Dienst, Gebeurtenis, Wachtdienst), gevolgd door de gewerkte uren en een vrije notitie.",
    'aide_planning.rc_step1_titre' => "Kies een Dienst (als de technicus gewerkt heeft)",
    'aide_planning.rc_step1_desc' => "Ochtend, Middag, Nacht of Volledige dag — slechts één chip tegelijk kan actief zijn. Klikken op een reeds actieve chip deselecteert ze.",
    'aide_planning.rc_step2_titre' => "Of kies een Gebeurtenis (als de technicus afwezig is)",
    'aide_planning.rc_step2_desc' => "Betaald verlof, ADV, Ziekte, Rustdag — slechts één actief tegelijk, en het wist automatisch de gekozen Dienst (u kunt niet \"met verlof\" en \"aan het werk\" zijn op dezelfde dag). Halve dag verlof en Feestdag werken anders: zie de volgende sectie.",
    'aide_planning.rc_step3_titre' => "Voeg indien nodig een Wachtdienst toe",
    'aide_planning.rc_step3_desc' => "Klassieke wachtdienst of Koude wachtdienst — puur informatief, heeft geen enkel effect op de verschuldigde uren of het urensaldo, enkel de badge wordt op de planning getoond.",
    'aide_planning.rc_step4_titre' => "Voer de gewerkte uren in",
    'aide_planning.rc_step4_desc' => "Met de knoppen <b>−</b> / <b>+</b> (stappen van 0,5u) of door het getal rechtstreeks in te typen. Dit cijfer is wat doorwerkt in het echte week- en jaartotaal.",
    'aide_planning.rc_step5_titre' => "Voeg indien nodig een notitie toe",
    'aide_planning.rc_step5_desc' => "Een vertraging, een vroeg vertrek, een bijzondere gebeurtenis... Deze notitie is enkel zichtbaar voor de betrokken technicus en voor de administrators — nooit voor de andere collega's.",
    'aide_planning.rc_step6_titre' => "Sla op",
    'aide_planning.rc_step6_desc' => "De knop <b>\"Opslaan\"</b> bevestigt het vakje. De knop <b>\"Wissen\"</b> leegt het vakje volledig (dienst, gebeurtenis, wachtdienst, uren en notitie).",
    'aide_planning.callout_objectif_direct' => "Terwijl u het venster invult, wordt de balk <b>\"Geannualiseerd doel\"</b> rechtsonder <b>live</b> bijgewerkt — u ziet onmiddellijk het effect van uw invoer op uw urenteller, nog vóór het opslaan.",
    'aide_planning.cases_evenements_lede' => "Niet alle vakjes zijn gelijk: sommige sluiten elkaar uit, andere stapelen zich op. Hier het volledige detail, dienst per dienst en gebeurtenis per gebeurtenis.",
    'aide_planning.tbl2_th_case' => "Vakje",
    'aide_planning.tbl2_th_groupe' => "Groep",
    'aide_planning.tbl2_th_heures_dues' => "Uren \"verschuldigd\" die dag",
    'aide_planning.tbl2_th_cumule' => "Stapelt met",
    'aide_planning.row1_case' => "Ochtend / Middag / Nacht / Volledige dag",
    'aide_planning.row1_groupe' => "Dienst",
    'aide_planning.row1_heures' => "7u (normale dag)",
    'aide_planning.row1_cumule' => "Halve dag verlof, Feestdag",
    'aide_planning.row2_case' => "Halve dag verlof (½ verlof)",
    'aide_planning.row2_groupe' => "Aan te vinken gebeurtenis",
    'aide_planning.row2_heures' => "3,5u in plaats van 7u",
    'aide_planning.row2_cumule' => "Enkel een gewerkte dienst",
    'aide_planning.row3_case' => "Betaald verlof",
    'aide_planning.row3_groupe' => "Gebeurtenis",
    'aide_planning.row3_heures' => "0u",
    'aide_planning.row3_cumule' => "Niets (exclusief)",
    'aide_planning.row4_case' => "Feestdag",
    'aide_planning.row4_groupe' => "Aan te vinken gebeurtenis",
    'aide_planning.row4_heures' => "0u indien niet gewerkt · normaal 7u indien gewerkt",
    'aide_planning.row4_cumule' => "Een gewerkte dienst",
    'aide_planning.row5_case' => "ADV",
    'aide_planning.row5_groupe' => "Gebeurtenis",
    'aide_planning.row5_heures' => "7u (maar 0u gedaan)",
    'aide_planning.row5_cumule' => "Niets (exclusief)",
    'aide_planning.row6_case' => "Ziekte",
    'aide_planning.row6_groupe' => "Gebeurtenis",
    'aide_planning.row6_heures' => "7u, automatisch gecrediteerd",
    'aide_planning.row6_cumule' => "Niets (exclusief)",
    'aide_planning.row7_case' => "Rustdag",
    'aide_planning.row7_groupe' => "Gebeurtenis",
    'aide_planning.row7_heures' => "0u",
    'aide_planning.row7_cumule' => "Niets (exclusief)",
    'aide_planning.row8_case' => "Leeg vakje (weekdag)",
    'aide_planning.row8_heures' => "toch 7u",
    'aide_planning.row9_case' => "Leeg vakje (zaterdag/zondag)",
    'aide_planning.row9_heures' => "0u",
    'aide_planning.card_poste_titre' => "Dienst (Ochtend / Middag / Nacht / Volledige dag)",
    'aide_planning.card_poste_desc' => "Het werkelijke werkritme van die dag. Geteld als een normale dag: <b>7u verschuldigd</b>, vergeleken met de uren die u net eronder invoert.",
    'aide_planning.card_cp_titre' => "Betaald verlof",
    'aide_planning.card_cp_desc' => "0u verschuldigd: een dag betaald verlof wordt nooit geteld als \"in te halen\". Het verbruikt een dag van het jaarquotum — <b>25 dagen</b> doordeweeks, <b>5</b> extra dagen voorbehouden voor zaterdag (30 in totaal, twee gescheiden tellers). Op een zondag opgenomen, verbruikt het niets aangezien zondag hoe dan ook nooit gewerkt wordt.",
    'aide_planning.card_demiconge_titre' => "Halve dag verlof (½ verlof)",
    'aide_planning.card_demiconge_desc' => "Een <b>apart</b> aan te vinken vakje, geen dienst: het verlaagt de verschuldigde uren tot 3,5u in plaats van 7u. Het kan enkel aangevinkt worden als aanvulling op een echte gewerkte dienst (ochtend, middag...) — een volledige-dag-gebeurtenis aanvinken (verlof, ADV, ziekte, rustdag) vinkt het automatisch uit, en omgekeerd.",
    'aide_planning.card_ferie_titre' => "Feestdag",
    'aide_planning.card_ferie_desc' => "Wordt aangevinkt zoals halve dag verlof, naast een dienst. <b>Niet gewerkt</b>: 0u verschuldigd. <b>Gewerkt</b> (een dienst is ook aangevinkt): geteld als een normale dag, 7u verschuldigd — een feestdag werken creëert geen verborgen bonus in deze teller (de loontoeslag is een apart loonadministratie-onderwerp). Erkende Franse feestdagen worden <b>automatisch vooraf aangevinkt</b> zolang niemand die dag iets voor u heeft ingevoerd.",
    'aide_planning.card_rtt_titre' => "ADV",
    'aide_planning.card_rtt_desc' => "Let op, klassieke valkuil: in tegenstelling tot betaald verlof telt een ADV-dag nog steeds als <b>7u verschuldigd</b>, met 0u gedaan. Concreet: een ADV-dag opnemen <b>debiteert 7u van uw voorsprong</b> — dat is normaal, een ADV-dag \"verbruikt\" uren die u al heeft opgebouwd door sommige weken meer dan 35u te werken.",
    'aide_planning.card_maladie_titre' => "Ziekte",
    'aide_planning.card_maladie_desc' => "7u verschuldigd, maar de app <b>crediteert ze automatisch</b> alsof ze gewerkt waren (zelfs als u geen enkel uur invoert). Resultaat: een ziekteperiode is volledig <b>neutraal</b> voor uw teller — het benadeelt u niet, maar doet u ook niet vooruitgaan.",
    'aide_planning.card_repos_titre' => "Rustdag",
    'aide_planning.card_repos_desc' => "De wettelijke wekelijkse rustdag, op een rotatie die op om het even welke dag van de week kan vallen (niet noodzakelijk zaterdag/zondag). 0u verschuldigd: deze dag was nooit \"te werken\", dus kost het niets om ze op te nemen.",
    'aide_planning.card_astreinte_titre' => "Wachtdienst (klassiek / koud)",
    'aide_planning.card_astreinte_desc' => "Puur informatief: beïnvloedt <b>noch</b> de verschuldigde uren, <b>noch</b> de gewerkte uren, <b>noch</b> het urensaldo. Gewoon een visuele badge op de planning om te weten wie wachtdienst heeft.",
    'aide_planning.callout_warn_case_vide' => "<b>De belangrijkste oorzaak van \"valse achterstand\": een weekvakje volledig leeg gelaten.</b> Zelfs als de technicus werkelijk gewerkt heeft, kan de app enkel tellen wat is ingevoerd. Een weekdag zonder enig aangevinkt vakje blijft standaard 7u verschuldigd (tenzij het een automatisch erkende feestdag betreft) — zonder invoer ertegenover vertaalt zich dat in <b>-7u</b> op de voorsprongteller, alsof de technicus niets gedaan heeft.",
    'aide_planning.avance_retard_lede' => "U heeft ongetwijfeld al de zin <b>\"+12u voorsprong op 35u/week\"</b> of <b>\"8u achterstand op 35u/week\"</b> onder een voortgangsbalk gezien. Hier is hoe dit cijfer berekend wordt, zonder jargon.",
    'aide_planning.journey2_dues' => "Verschuldigde uren",
    'aide_planning.journey2_faites' => "Gedane uren",
    'aide_planning.journey2_ecart' => "Verschil (voorsprong of achterstand)",
    'aide_planning.ar_p1' => "<b>De \"verschuldigde\" uren</b> zijn wat u vandaag zou moeten hebben opgebouwd als u precies 35u per week werkte (dus 7u per werkdag) sinds het begin van de periode — 1 april. Elke weekdag telt 7u \"verschuldigd\", behalve die gedekt door de tabel in de vorige sectie (verlof = 0u, rustdag = 0u, niet-gewerkte feestdag = 0u, halve dag verlof = 3,5u). Het weekend is standaard niets verschuldigd, tenzij het werkelijk gewerkt is.",
    'aide_planning.ar_p2' => "<b>De \"gedane\" uren</b> zijn de som van alle uren die u in uw vakjes heeft ingevoerd, plus de \"alsof\"-7u die automatisch gecrediteerd worden voor elke ziektedag.",
    'aide_planning.ar_p3' => "<b>Het verschil</b> = gedane uren − verschuldigde uren. Positief, u bent <span class=\"chip-key\"><span class=\"chip-dot\" style=\"background:var(--success);\"></span>in voorsprong</span>. Negatief, u bent <span class=\"chip-key\"><span class=\"chip-dot\" style=\"background:var(--danger);\"></span>in achterstand</span>.",
    'aide_planning.shot_ecart_alt' => "Venster \"Mijn urensaldo begrijpen\" met het detail maand per maand",
    'aide_planning.shot_ecart_cap' => "De \"i\"-hulpbubbel naast de markering 35u/week opent dit detail: verschuldigde uren, gedane uren, totaal verschil, verschil maand per maand, en vooral de lijst van weekdagen zonder enige invoer.",
    'aide_planning.callout_tip_jours_sans_saisie' => "Deze hulpbubbel somt expliciet de <b>weekdagen zonder enige invoer</b> op (geen dienst, geen verlof, geen ADV, geen feestdag). Dit is bijna altijd de echte verklaring voor een achterstand die onterecht lijkt: vul deze dagen in (gewerkte dienst of opgenomen verlof) en de teller herstelt onmiddellijk.",
    'aide_planning.ar_p4' => "Twee bijkomende aanpassingen verminderen het aantal verschuldigde uren over het hele jaar (en verhogen dus de voorsprong):",
    'aide_planning.card_fractionnement_titre' => "Gesplitst verlof (Art. 6)",
    'aide_planning.card_fractionnement_desc' => "Dagen geval per geval toegekend door HR volgens de voorwaarden waarin het hoofdverlof werd opgenomen — <b>1 dag = -7u</b>, <b>2 dagen = -14u</b> op het jaardoel. Wordt ingesteld in de <a href=\"#planning-annuel\">Jaarplanning</a>, keuzelijst \"Gesplitst verlof\".",
    'aide_planning.card_semaine48_titre' => "Weken van 48u (Art. 3)",
    'aide_planning.card_semaine48_desc' => "Elke week waarin het totaal ingevoerde uren 48u of meer bereikt, geeft recht op <b>-4u</b> op het jaardoel — automatisch gedetecteerd, geen bijzondere invoer nodig.",
    'aide_planning.exemple_lede' => "Een fictief voorbeeld om het concrete effect van elk vakje goed te zien. Stel de week van een technicus als volgt ingevuld voor:",
    'aide_planning.tbl3_th_jour' => "Dag",
    'aide_planning.tbl3_th_case' => "Aangevinkt vakje",
    'aide_planning.tbl3_th_heures_dues' => "Verschuldigde uren",
    'aide_planning.tbl3_th_heures_faites' => "Gedane uren",
    'aide_planning.tbl3_th_ecart' => "Verschil van de dag",
    'aide_planning.ex_lundi' => "Maandag",
    'aide_planning.ex_lundi_case' => "Ochtend, 7u ingevoerd",
    'aide_planning.ex_mardi' => "Dinsdag",
    'aide_planning.ex_mardi_case' => "<i>Niets ingevoerd, vergeten</i>",
    'aide_planning.ex_mercredi' => "Woensdag",
    'aide_planning.ex_mercredi_case' => "ADV",
    'aide_planning.ex_jeudi' => "Donderdag",
    'aide_planning.ex_jeudi_case' => "Betaald verlof",
    'aide_planning.ex_vendredi' => "Vrijdag",
    'aide_planning.ex_vendredi_case' => "Ochtend + gewerkte feestdag, 7u ingevoerd",
    'aide_planning.ex_samedi' => "Zaterdag",
    'aide_planning.ex_dimanche' => "Zondag",
    'aide_planning.ex_rien_non_travaille' => "<i>Niets (niet gewerkt)</i>",
    'aide_planning.ex_total_label' => "Totaal van de week",
    'aide_planning.exemple_conclusion' => "Resultaat: <b>-7u voor de week</b>, ondanks twee dagen werkelijk gewerkt aan 7u en een correct opgenomen dag betaald verlof. De oorzaak is <b>niet</b> het betaald verlof (0u verschuldigd, neutraal): het is de combinatie van de <b>vergeten dinsdag</b> (-7u, een pure invoerleemte) en de <b>ADV van woensdag</b>, die normaal 7u van de reeds opgebouwde voorsprong debiteert. Door gewoon dinsdag in te vullen, zou het verschil van de week onmiddellijk terug naar 0u gaan.",
    'aide_planning.remplissage_rapide_lede' => "Om een week betaald verlof of een reeks identieke diensten op te geven zonder elke dag één voor één te openen, gebruikt u de knop <b>\"Meerdere dagen invullen\"</b> onderaan het planningsvenster.",
    'aide_planning.shot_bulk_alt' => "Venster voor snel invullen over een periode van data",
    'aide_planning.shot_bulk_cap' => "Kies een periode van data, vink eventueel \"Weekends uitsluiten\" aan, stel hetzelfde vakje samen (Dienst/Gebeurtenis/Wachtdienst/Uren) als bij individuele invoer, en klik dan op \"Toepassen\".",
    'aide_planning.rr_step1_titre' => "Kies de periode",
    'aide_planning.rr_step1_desc' => "Een begindatum en een einddatum. Het vakje \"Weekends uitsluiten\" is standaard aangevinkt — vink het uit als u ook zaterdagen/zondagen moet dekken.",
    'aide_planning.rr_step2_titre' => "Stel het toe te passen vakje samen",
    'aide_planning.rr_step2_desc' => "Precies dezelfde chips Dienst / Gebeurtenis / Wachtdienst en hetzelfde Uren-veld als voor een individueel vakje, met dezelfde stapelregels.",
    'aide_planning.rr_step3_titre' => "Controleer de voorvertoning, en klik dan op Toepassen",
    'aide_planning.rr_step3_desc' => "Een voorvertoning vat samen wat er geschreven gaat worden vóór bevestiging.",
    'aide_planning.callout_warn_ecrase' => "Snel invullen <b>overschrijft</b> alles wat al bestond op de betrokken dagen (dienst, gebeurtenis, wachtdienst, uren) — controleer altijd de periode vóór u op \"Toepassen\" klikt.",
    'aide_planning.bons_intervention_lede' => "De planning toont ook, naast de dienst van de dag, een klein etiket per interventiebon (BI) waarop de technicus die dag een tijdregistratie heeft (zie <a href=\"aide_ot.php\">de BI-gids</a> voor het aanmaken en registreren).",
    'aide_planning.bi_li1' => "<b>Klikken op een BI-etiket</b> opent rechtstreeks zijn detailfiche.",
    'aide_planning.bi_li2' => "<b>Een etiket verslepen</b> naar een ander vakje verplaatst de BI (en zijn registratie) naar een andere dag of een andere technicus — enkel voor administrators. Een technicus ziet zijn eigen BI's maar kan ze niet naar een collega verslepen.",
    'aide_planning.bi_li3' => "In het planningsvenster zelf toont de sectie <b>\"Interventiebonnen van de dag\"</b> bovenaan alle BI's van de technicus voor die specifieke datum, met gekleurde status en een klik om het detail te openen.",
    'aide_planning.bi_li4' => "Een werkorder kan ook rechtstreeks worden aangemaakt vanuit een vakje van de planning (zie \"Een vakje invullen\" hierboven): de technicus en datum worden dan vooraf ingevuld in de aanmaakassistent.",
    'aide_planning.todo_lede' => "Een persoonlijke takenlijst per technicus en per dag, bereikbaar vanuit het keuzevenster van een vakje (zie \"Een vakje invullen\" hierboven).",
    'aide_planning.todo_li1' => "<b>Elke technicus</b> ziet en bewerkt enkel zijn eigen lijst. <b>Een admin</b> kan die van iedereen zien en bewerken.",
    'aide_planning.todo_li2' => "Een taak aanvinken markeert ze als gedaan (doorgestreepte tekst); een kruisje verwijdert ze definitief (met bevestiging).",
    'aide_planning.todo_li3' => "<b>Een niet-aangevinkte taak schuift automatisch door naar de volgende dag</b> zodra de pagina wordt herladen: ze blijft nooit hangen op een dag die al voorbij is.",
    'aide_planning.todo_li4' => "Een klein paars pastille verschijnt rechtstreeks op het vakje van de planning (Week- en Maandweergave) zodra er die dag taken zijn: het aantal resterende, of een vinkje als alles klaar is. Erop klikken opent de lijst rechtstreeks.",
    'aide_planning.todo_li5' => "<b>Volledig formulier</b>: rechts van de lijst (op kleine schermen eronder) vul je de titel in, de <b>prioriteit</b> (laag, normaal, hoog), een <b>categorie</b> (lijst aanpasbaar in Instellingen &gt; TODO-lijst), een <b>geschatte duur</b>, een <b>geplande tijd</b>, een <b>machine of plaats</b> en een vrij <b>detail</b>. Ze verschijnen onder de taak als labels, en de gekleurde balk links van de taak toont de prioriteit.",
    'aide_planning.todo_li6' => "<b>Een taak wijzigen</b>: het potlood rechts van de taak laadt de gegevens in het formulier, dat oranje wordt en \"Taak wijzigen\" heet (de betreffende taak krijgt een oranje rand in de lijst); \"Opslaan\" past de wijzigingen toe, \"Annuleren\" laat ze vallen.",
    'aide_planning.todo_li7' => "Een <b>samenvatting</b> bovenaan het venster toont de voortgang (afgeronde taken, hoge prioriteiten, geschatte resterende tijd, doorgeschoven taken), en <b>filters</b> Alle / Te doen / Klaar beperken de weergave. Taken die nog te doen zijn komen vóór afgeronde, met de hoogste prioriteit eerst. Elke taak toont ook haar aanmaakdatum, een eventuele doorschuiving en haar einddatum.",
    'aide_planning.todo_callout' => "Met de muis over het paarse label op een vak tonen we één infobel per taak (status, prioriteit, tijd, machine, detail), zonder de lijst te openen.",
    'aide_planning.planning_annuel_lede' => "Toegankelijk door op de naam van een technicus in het rooster te klikken, of op de knop <b>\"Volledige jaarplanning bekijken\"</b> in het planningsvenster. Het is de volledige kalender van de lopende periode (van 1 april tot 31 maart daaropvolgend), maand per maand.",
    'aide_planning.shot_annuel_alt' => "Jaarplanning: volledige kalender met quotasamenvatting",
    'aide_planning.shot_annuel_cap' => "Bovenaan: de voortgangsbalk van het jaardoel en de markering 35u/week. Eronder: de quotasamenvatting (verlof, zaterdagverlof, ADV, ziekte, diensten, wachtdiensten). Lager: de kalender maand per maand.",
    'aide_planning.card_objectif_titre' => "Jaardoel",
    'aide_planning.card_objectif_desc' => "Standaard 1607u (de Franse wettelijke drempel), maar aanpasbaar per technicus. <b>Iedereen kan zijn eigen doel wijzigen</b> (of een admin, dat van eender wie) via het kleine numerieke veld en de knop <i class=\"fa-solid fa-check\"></i>.",
    'aide_planning.card_fractionnement2_titre' => "Gesplitst verlof",
    'aide_planning.card_fractionnement2_desc' => "Keuzelijst 0d / 1d (-7u) / 2d (-14u) — dezelfde rechten als het doel: de betrokken technicus of een admin.",
    'aide_planning.card_recap_titre' => "Quotasamenvatting",
    'aide_planning.card_recap_desc' => "Eén tegel per categorie: verlof (25d), zaterdagverlof (5d), ADV en ziekte (geen vast quotum, gewoon een teller), en de diensten/wachtdiensten al gepland op het jaar.",
    'aide_planning.card_alerte_cp_titre' => "Zomerverlof-alarm",
    'aide_planning.card_alerte_cp_desc' => "Als meer dan <b>12 opeenvolgende werkdagen betaald verlof</b> de periode van 15 juli tot 30 september overlappen, verschijnt een alarmbadge op de verloftegel (conventioneel plafond, Art. 6 van het jaarurenakkoord).",
    'aide_planning.pa_p_calendrier' => "In de kalender zelf toont elke dag een mini-badge van dienst/gebeurtenis en, voor reeds verstreken dagen, een klein groen (voorsprong) of rood (achterstand) badge dat het verschil van die specifieke dag aangeeft. Elke maand telt zijn uren en zijn eigen verschil op.",
    'aide_planning.callout_tip_bulle_ecart' => "De knop <i class=\"fa-solid fa-circle-info\"></i> naast de markering 35u/week opent de bubbel <b>\"Mijn urensaldo begrijpen\"</b> die in de <a href=\"#avance-retard\">vorige sectie</a> in detail wordt uitgelegd.",
    'aide_planning.callout_lock_annualisation' => "Voor de volledige wettelijke 1607u-formule (gedetailleerde berekening, verlof, feestdagen) en de regels van het jaarurenakkoord, zie het specifieke artikel <a href=\"aide_annualisation.php\">Verlof, ADV &amp; Jaarurenregeling</a>.",
    'aide_planning.droits_lede' => "De planning past zich aan uw rol aan. Hier de samenvatting.",
    'aide_planning.tbl4_th_action' => "Actie",
    'aide_planning.tbl4_th_technicien' => "Technicus",
    'aide_planning.tbl4_th_admin' => "Admin",
    'aide_planning.droit1_action' => "Het weekrooster bekijken",
    'aide_planning.txt_toute_equipe' => "Het hele team",
    'aide_planning.droit2_action' => "Een vakje invullen/wijzigen",
    'aide_planning.txt_ses_cases' => "Enkel eigen vakjes",
    'aide_planning.txt_nimporte_qui' => "Om het even wie",
    'aide_planning.droit3_action' => "De jaarplanning bekijken",
    'aide_planning.txt_le_sien' => "Enkel de eigen",
    'aide_planning.droit4_action' => "Het jaardoel / het gesplitst verlof wijzigen",
    'aide_planning.txt_les_siens' => "Enkel de eigen",
    'aide_planning.droit5_action' => "De notitie van een vakje lezen",
    'aide_planning.txt_ses_notes' => "Enkel eigen notities",
    'aide_planning.txt_toutes_notes' => "Alle notities",
    'aide_planning.droit6_action' => "Een BI van de ene technicus naar de andere verplaatsen",
    'aide_planning.astuces_li1' => "<b>Laat nooit een weekdag leeg</b> — zelfs een kleine normale dag heeft een dienst en uren nodig, anders beschouwt de voorsprongteller 7u \"verschuldigd\" en 0u \"gedaan\", oftewel -7u die onterecht lijken.",
    'aide_planning.astuces_li2' => "<b>ADV ≠ Rustdag ≠ Verlof</b>: verlof en rustdag zijn neutraal (0u verschuldigd), maar ADV blijft 7u verschuldigd — een ADV-dag opnemen debiteert echt uw voorsprong. Verwar de drie niet als u een juiste teller wilt.",
    'aide_planning.astuces_li3' => "<b>Een gewerkte feestdag moet aangevinkt zijn ÉN een dienst hebben</b>: enkel \"Feestdag\" aanvinken zonder dienst laat geloven dat u die dag niet gewerkt heeft.",
    'aide_planning.astuces_li4' => "<b>Ziekte heeft geen ingevoerde uren nodig</b>: vink gewoon het vakje aan, de 7u worden automatisch gecrediteerd.",
    'aide_planning.astuces_li5' => "<b>Raadpleeg regelmatig de bubbel \"Mijn urensaldo begrijpen\"</b> — ze somt heel precies de dagen op die u nog moet invullen, in plaats van te gokken.",
    'aide_planning.astuces_li6' => "<b>Snel invullen overschrijft bestaande vakjes</b> over de gekozen periode: controleer altijd de data vóór u op \"Toepassen\" klikt.",
    'aide_planning.gloss1_dt' => "Dienst",
    'aide_planning.gloss1_dd' => "Het werkelijke werkritme van een dag: Ochtend, Middag, Nacht of Volledige dag.",
    'aide_planning.gloss2_dt' => "Gebeurtenis",
    'aide_planning.gloss2_dd' => "Een afwezigheid of een aangepaste dag: verlof, ADV, ziekte, rustdag, halve dag verlof, feestdag.",
    'aide_planning.gloss3_dt' => "Wachtdienst",
    'aide_planning.gloss3_dd' => "Informatie getoond als badge, zonder effect op de verschuldigde/gedane uren.",
    'aide_planning.gloss4_dt' => "Verschuldigde uren",
    'aide_planning.gloss4_dd' => "Wat de technicus die dag zou moeten gewerkt hebben (7u, 3,5u of 0u naargelang het aangevinkte vakje).",
    'aide_planning.gloss5_dt' => "Gedane uren",
    'aide_planning.gloss5_dd' => "De werkelijk ingevoerde uren, plus de automatische krediet van 7u voor een ziektedag.",
    'aide_planning.gloss6_dt' => "Markering 35u/week",
    'aide_planning.gloss6_dd' => "De opgetelde verschuldigde uren sinds 1 april tot vandaag — de referentie om het urensaldo mee te vergelijken.",
    'aide_planning.gloss7_dt' => "Geannualiseerd doel",
    'aide_planning.gloss7_dd' => "Het totaal aantal uren te bereiken over het jaar (standaard 1607u), getoond als voortgangsbalk.",
    'aide_planning.gloss8_dt' => "Gesplitst verlof",
    'aide_planning.gloss8_dd' => "Dagen toegekend door HR die het jaardoel met 7u of 14u verminderen (Art. 6 van het jaarurenakkoord).",
    'aide_planning.gloss9_dt' => "Week van 48u",
    'aide_planning.gloss9_dd' => "Een week waarin het totaal ingevoerde uren 48u of meer bereikt, wat het doel automatisch met 4u vermindert (Art. 3).",
    'aide_planning.gloss10_dt' => "Zaterdagverlof",
    'aide_planning.gloss10_dd' => "Apart quotum van 5 dagen betaald verlof voorbehouden voor zaterdag, los van de 25 weekdagen verlof.",
    'aide_planning.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan administratiezijde:",
    'aide_planning.devnote_li1' => "De logica van voorsprong/achterstand (<code>referenceDuJour</code>, <code>calculerReferenceHeures35h</code>) wordt <b>clientzijde</b> berekend op basis van <code>planning_shifts</code> — geen serverzijdse herberekening, dus elke wijziging aan deze regel moet doorgevoerd worden in de JS van <code>planning.php</code>.",
    'aide_planning.devnote_li2' => "Het jaardoel en het gesplitst verlof zijn wijzigbaar door de betrokken technicus zelf (niet enkel door een admin) — een bewuste keuze in de code (\"iedereen beheert zijn eigen uren\"), te herbevestigen als het HR-beleid verandert.",
    'aide_planning.devnote_li3' => "De rechtencontrole (bewerken van vakjes van anderen, BI verplaatsen) gebeurt enkel clientzijde: de acties <code>save_shift</code>, <code>save_objectif</code> en <code>save_fractionnement</code> van <code>maintenance.php</code> controleren de rol niet opnieuw.",

    'aide_service.page_title_tag' => "Hulp - Portaal Diensten",
    'aide_service.crumb_portail_services' => "Portaal Diensten",
    'aide_service.crumb_aide' => "Hulp",
    'aide_service.badge_non_connecte' => "Niet aangemeld",
