    'aide_service.accueil_title' => "Start",
    'aide_service.hero_eyebrow' => "Gids Portaal Diensten",
    'aide_service.hero_h1' => "Het dienstenportaal gebruiken",
    'aide_service.hero_tagline' => "Alles wat u moet weten om een storing te melden, uw aanvragen op te volgen en uw ideeën door te geven.",
    'aide_service.pill_updated' => "Bijgewerkt op <b>04/09/2026</b>",
    'aide_service.pill_public' => "Voor <b>Productie, Kwaliteit, Veiligheid, HR, Logistiek, Agronomie...</b>",
    'aide_service.toc_connexion' => "Aanmelden",
    'aide_service.toc_accueil' => "Uw startpagina",
    'aide_service.toc_demande' => "Een aanvraag indienen",
    'aide_service.toc_suivi' => "Mijn aanvragen opvolgen",
    'aide_service.toc_idees' => "Een idee voorstellen",
    'aide_service.toc_annualisation' => "Verlof, ADV & Jaarurenregeling",
    'aide_service.toc_planning' => "Planning (binnenkort)",
    'aide_service.toc_astuces' => "Tips & valkuilen",
    'aide_service.toc_glossaire' => "Woordenlijst",
    'aide_service.toc_faq' => "Veelgestelde vragen",
    'aide_service.connexion_lede' => "Geen e-mailadres of klassiek wachtwoord: u selecteert de naam van uw dienst uit een lijst, en voert dan de bijhorende code in.",
    'aide_service.shot_login_alt' => "Aanmeldpagina van de GMAO",
    'aide_service.shot_login_cap' => "Het aanmeldscherm: een naam, een code, een knop.",
    'aide_service.co_step1_titre' => "Selecteer de naam van uw dienst",
    'aide_service.co_step1_desc' => "Kies in de keuzelijst \"Wie bent u?\" uw dienst (bv. \"D. Productie\"), geen persoonlijke naam.",
    'aide_service.co_step2_titre' => "Voer de algemene code van de dienst in",
    'aide_service.co_step2_desc' => "Dit is dezelfde code voor uw hele team — anders dan de persoonlijke code die u later bij elke aanvraag invoert.",
    'aide_service.co_step3_titre' => "Klik op \"AANMELDEN\"",
    'aide_service.co_step3_desc' => "U komt rechtstreeks op uw startpagina terecht, met de tegels van het portaal.",
    'aide_service.callout_warn_code_perso' => "De code van de dienst opent enkel het portaal. Voor <b>elke aanvraag</b> die u indient, zal een extra stap uw <b>naam</b> en een eigen <b>persoonlijke code</b> vragen — anders dan de aanmeldcode van de dienst. Deze persoonlijke code dient als elektronische handtekening en opent ook de berichten op uw tickets.",
    'aide_service.shot_erreur_alt' => "Foutmelding: onjuiste naam of code",
    'aide_service.shot_erreur_cap' => "Bij een foutmelding, controleer de geselecteerde naam, de code (zonder spatie) en Caps Lock.",
    'aide_service.accueil_lede' => "Eenmaal aangemeld komt u op een pagina met 4 tegels: het vertrekpunt naar alle functies van het portaal.",
    'aide_service.tile1_titre' => "Nieuwe werkaanvraag",
    'aide_service.tile1_desc' => "Een storing melden of een interventie aanvragen bij het onderhoudsteam.",
    'aide_service.tile2_titre' => "Opvolging van mijn aanvragen",
    'aide_service.tile2_desc' => "De status van uw tickets bekijken, de reacties (of weigeringen) van het onderhoud.",
    'aide_service.tile3_titre' => "Ideeën om de GMAO te verbeteren",
    'aide_service.tile3_desc' => "Een suggestie, een bug of een ontbrekende functie voorstellen.",
    'aide_service.tile4_titre' => "Hulp & veelgestelde vragen",
    'aide_service.tile4_desc' => "Deze gids die u nu leest.",
    'aide_service.callout_tip_badge_rouge' => "Een rode badge kan op <b>twee</b> tegels verschijnen: op <b>Opvolging van mijn aanvragen</b> toont het een aantal nieuwe berichten of reacties van het onderhoud; op <b>Ideeën om de GMAO te verbeteren</b> toont het een of meer nog niet gelezen reacties van de administrator op uw verzonden ideeën.",
    'aide_service.demande_lede' => "Het formulier is een kleine geleide wizard, in 4 stappen weergegeven in de linkerkolom. Elke stap biedt een geïllustreerde hulpbubbel, en iconen <i class=\"fa-solid fa-circle-question\" style=\"color:var(--accent);\"></i> naast de belangrijkste velden openen een gedetailleerde uitleg.",
    'aide_service.shot_etape1_alt' => "Stap 1 van het aanvraagformulier: identiteit en persoonlijke code",
    'aide_service.shot_etape1_cap' => "Stap 1 — Identiteit: functie, naam, en persoonlijke code.",
    'aide_service.d_step1_titre' => "Identiteit",
    'aide_service.d_step1_desc' => "Kies uw functie, dan uw naam, en voer dan uw persoonlijke code in (minstens 4 tekens).",
    'aide_service.d_step2_titre' => "Locatie",
    'aide_service.d_step2_desc' => "Dit is geen eenvoudige keuzelijst: het is een echte visuele kiezer. Een balk <b>\"Snel zoeken\"</b> (\"Machinenaam, zone, sector, fabriek...\") laat toe rechtstreeks een machinenaam te typen; anders navigeert u via aanklikbare tegels (Fabriek → Sector → Lijn → Zone → Machine) met een kruimelpad om terug te gaan. Zodra de machine gekozen is, verschijnt een bevestigingskaart met een knop <b>\"Machine wijzigen\"</b> indien nodig. Bestaat ze niet in de lijst, kies dan <b>\"Andere / Niet vermeld\"</b> (enkel voorgesteld op het niveau Machine) en beschrijf ze in de volgende stap.",
    'aide_service.d_step3_titre' => "Probleem",
    'aide_service.d_step3_desc' => "Beschrijf de storing (wat, sinds wanneer, ernst) en geef aan of het urgent is — voorbehouden voor lijnstilstanden of reële gevaren. De beschrijving moet <b>minstens 10 tekens</b> tellen: een teller onder het veld begeleidt u live (\"nog wat meer detail...\" dan \"✓ dat is duidelijk!\" zodra de drempel bereikt is).",
    'aide_service.d_step4_titre' => "Verzending",
    'aide_service.d_step4_desc' => "Een volledige samenvatting verschijnt vóór de definitieve verzending naar het onderhoud. U kunt nog alles wijzigen via \"Wijzigen\". Eenmaal verzonden, bevestigt een venster <b>\"Ticket verzonden!\"</b> de verzending, met twee knoppen: <b>\"Nieuwe aanvraag\"</b> of <b>\"Opvolging bekijken\"</b>.",
    'aide_service.shot_etape2_alt' => "Stap 2: cascaderende locatie",
    'aide_service.shot_etape2_cap' => "Stap 2 — Locatie",
    'aide_service.shot_etape3_alt' => "Stap 3: probleembeschrijving en urgentie",
    'aide_service.shot_etape3_cap' => "Stap 3 — Probleem",
    'aide_service.callout_tip_envoyee' => "Eenmaal verzonden, vertrekt uw aanvraag onmiddellijk naar het onderhoud met de status <span class=\"pill pill-attente\"><span class=\"pill-dot\"></span>In afwachting</span>. Vind ze op elk moment terug via de tegel <b>\"Opvolging van mijn aanvragen\"</b> op de startpagina.",
    'aide_service.suivi_lede' => "Geen nood om het onderhoud te bellen om te weten waar uw aanvraag staat: alles is zichtbaar op de pagina \"Opvolging van mijn aanvragen\", toegankelijk vanaf de startpagina.",
    'aide_service.shot_suivi_alt' => "Opvolgingspaneel van verzonden aanvragen",
    'aide_service.shot_suivi_cap' => "Statistiektegels, filters en de ticketlijst — klik op een rij om het detail te zien.",
    'aide_service.h3_5_statuts' => "De 5 statussen",
    'aide_service.pill_attente_label' => "In afwachting",
    'aide_service.pill_attente_desc' => "uw aanvraag is nog niet gevalideerd door het onderhoud.",
    'aide_service.pill_afaire_label' => "Te doen",
    'aide_service.pill_afaire_desc' => "gevalideerd, er is een BI-nummer toegekend, ze wacht op behandeling.",
    'aide_service.pill_cours_label' => "In uitvoering",
    'aide_service.pill_cours_desc' => "een technicus werkt eraan.",
    'aide_service.pill_termine_label' => "Afgerond",
    'aide_service.pill_termine_desc' => "de interventie is afgesloten, een verslag is opgesteld.",
    'aide_service.pill_refuse_label' => "Geweigerd",
    'aide_service.pill_refuse_desc' => "het onderhoud heeft er geen gevolg aan gegeven; de weigeringsreden staat in het ticketdetail.",
    'aide_service.callout_lock_renommage' => "Deze 5 standaardnamen kunnen door een administrator <b>hernoemd</b> worden vanuit Instellingen. Ziet u licht afwijkende labels, dan is dat normaal — de volgorde en betekenis blijven dezelfde.",
    'aide_service.h3_vignettes' => "Tegels, zoeken en filters",
    'aide_service.vignettes_p1' => "Bovenaan de pagina geven <b>5 aanklikbare tegels</b> de 5 statussen weer met een teller — erop klikken filtert de lijst onmiddellijk. Eronder combineert een filterbalk:",
    'aide_service.vf_li1' => "een <b>vrije zoekopdracht</b> (\"Zoeken (beschrijving, machine, BI-nr.)...\") die zoekt in de beschrijving, de machine, het BI-nummer en de locatie;",
    'aide_service.vf_li2' => "een filter op <b>aanvrager</b> en een filter op <b>status</b>;",
    'aide_service.vf_li3' => "een specifieke filter <b>\"Ongelezen berichten\"</b>, om met één klik alle tickets terug te vinden die op uw lezing wachten;",
    'aide_service.vf_li4' => "een knop <b>\"Reset\"</b> die alle actieve filters wist.",
    'aide_service.vignettes_p2' => "De lijst wordt gepagineerd in blokken van <b>8 tickets</b>, met knoppen \"Vorige\" / \"Volgende\".",
    'aide_service.h3_carte' => "Wat een kaart of het detail van een ticket toont",
    'aide_service.carte_lede' => "Naast de status kunnen meerdere indicatoren op een ticket verschijnen:",
    'aide_service.tile_urgent_titre' => "Urgent",
    'aide_service.tile_urgent_desc' => "De prioriteit gekozen bij het aanmaken van de aanvraag.",
    'aide_service.tile_soustraite_titre' => "Uitbesteed",
    'aide_service.tile_soustraite_desc' => "De interventie wordt toevertrouwd aan een extern bedrijf; de naam ervan staat vermeld.",
    'aide_service.tile_bris_titre' => "Materiaalbreuk",
    'aide_service.tile_bris_desc' => "De aanvraag betreft een accidentele breuk.",
    'aide_service.tile_visserie_titre' => "Schroefverbindingscontrole",
    'aide_service.tile_visserie_desc' => "Er is een aanhaalcontrole aangevraagd of uitgevoerd.",
    'aide_service.frise_p' => "Het detail van een ticket toont ook een <b>voortgangsbalk</b> in 4 stappen — <i>Verzonden → Gevalideerd → In behandeling → Afgerond</i> — een vereenvoudigd en aanvullend beeld bij de 5 hierboven beschreven statussen: elke reeds bereikte stap wordt groen weergegeven, en enkel de volgende verwachte stap blijft blauw. Het veld <b>\"Uitvoerende technicus\"</b> is gebaseerd op de werkelijke tijdregistraties (niet enkel op de bij aanmaak toegewezen technicus): het toont \"Geen registratie geregistreerd\" zolang niemand er tijd op geregistreerd heeft.",
    'aide_service.heures_p' => "Zodra minstens één uur op het ticket geregistreerd is, verschijnen twee bijkomende gegevens: de <b>interventie-uren</b> (het totaal van de door het onderhoud geregistreerde tijd) en de <b>uitvoeringsdatum</b> (de dag van de laatste registratie). Heeft het onderhoud foto's aan het ticket toegevoegd, dan verschijnen ze ook in een galerij <b>\"Bijgevoegde foto's\"</b> — klik op een foto om ze te vergroten.",
    'aide_service.callout_tip_carnet' => "Zolang de interventie loopt, kan een <b>Logboek</b> tussentijdse notities tonen die de technicus achterliet (bv. \"onderdeel besteld, in afwachting van levering\") — te onderscheiden van het <b>eindrapport</b> van afsluiting, dat pas verschijnt zodra het ticket Afgerond is.",
    'aide_service.h3_messagerie' => "Berichten",
    'aide_service.callout_tip_messagerie' => "Een knop <b>Berichten</b> laat toe rechtstreeks met de technicus over uw aanvraag te communiceren. Het venster <b>\"Beveiliging Berichten\"</b> vraagt u zich te identificeren vóór het schrijven: <b>selecteer opnieuw uw naam</b> in de lijst \"Wie bent u?\" <b>en</b> voer opnieuw uw persoonlijke code in — niet enkel de code alleen. Dit kanaal wordt ook gebruikt om u te verwittigen bij een weigering.",
    'aide_service.callout_warn_badge_rouge' => "Een rode badge op een ticket of op de starttegel duidt op een <b>ongelezen bericht</b>: een reactie van het onderhoud, of de melding van een weigering met haar reden.",
    'aide_service.idees_lede' => "Een ontbrekende functie, een vervelende bug, een praktische verbetering? De tegel <b>\"Ideeën om de GMAO te verbeteren\"</b> is daarvoor gemaakt.",
    'aide_service.i_step1_titre' => "Vul het formulier in",
    'aide_service.i_step1_desc' => "Uw naam, een categorie (functie, ergonomie, bug, andere), een korte titel en een beschrijving.",
    'aide_service.i_step2_titre' => "Volg de status op",
    'aide_service.i_step2_desc' => "Onder het formulier vindt u alle ideeën die uw dienst al indiende terug, met hun status: Nieuw, In onderzoek, Aanvaard, Gerealiseerd, of Afgewezen.",
    'aide_service.i_step3_titre' => "Praat met de administrator",
    'aide_service.i_step3_desc' => "Elk opengeklapt idee opent een echte <b>discussiedraad</b>: de administrator kan u antwoorden, en u kunt op uw beurt antwoorden vanuit een veld \"Een antwoord aan de administrator schrijven...\". Zolang er geen antwoord gegeven is, ziet u \"Nog geen antwoord van de administrator.\"",
    'aide_service.callout_tip_nouveau' => "Een nog niet gelezen antwoord van de administrator doet een badge <b>\"NIEUW\"</b> verschijnen op het betrokken idee, en voedt de rode badge van de tegel <b>\"Ideeën om de GMAO te verbeteren\"</b> op uw startpagina.",
    'aide_service.annualisation_lede' => "Uw betaald verlof, ADV, feestdagen en ziekteverlof worden over een volledig jaar verrekend, niet week per week — een principe dat voor alle werknemers geldt, niet enkel het onderhoudsteam. Hier het essentiële om te weten.",
    'aide_service.h3_1607h' => "De wettelijke referentie: 1607u per jaar",
    'aide_service.p_1607h' => "De wettelijke arbeidsduur over een jaar bedraagt <b>1607u</b> (gemiddeld 35u/week, solidariteitsdag inbegrepen). Dit cijfer wordt berekend door van de 365 dagen van het jaar al de weekends, de <b>25 wettelijke dagen betaald verlof</b> en de <b>feestdagen</b> af te trekken — deze dagen worden dus nooit een tweede keer meegeteld in het totaal gewerkte uren.",
    'aide_service.tbl_th_type_jour' => "Type dag",
    'aide_service.tbl_th_heures_dues' => "Verschuldigde uren die dag",
    'aide_service.tbl_th_debite' => "Debiteert uw voorsprong?",
    'aide_service.tbl_th_pourquoi' => "Waarom",
    'aide_service.row_cp_type' => "Betaald verlof",
    'aide_service.row_cp_heures' => "0u",
    'aide_service.row_cp_debite' => "Nee",
    'aide_service.row_cp_pourquoi' => "Al afgetrokken van de 1607u-berekening: het is niet verschuldigd, dus nooit een tweede keer meegeteld.",
    'aide_service.row_demicp_type' => "Halve dag betaald verlof",
    'aide_service.row_demicp_heures' => "3,5u",
    'aide_service.row_demicp_debite' => "Nee (halve dag)",
    'aide_service.row_demicp_pourquoi' => "Zelfde principe als betaald verlof, toegepast op een halve dag.",
    'aide_service.row_rtt_type' => "ADV",
    'aide_service.row_rtt_heures' => "<b>7u</b>",
    'aide_service.row_rtt_debite' => "<b>Ja</b>",
    'aide_service.row_rtt_pourquoi' => "In tegenstelling tot betaald verlof \"verbruikt\" een ADV-dag een reeds opgebouwd urenkrediet (u werkte sommige weken gemiddeld meer dan 35u): de dag blijft normaal verschuldigd, wat wel degelijk 7u van uw voorsprong debiteert — dat is het principe zelf van ADV.",
    'aide_service.row_repos_type' => "Rustdag",
    'aide_service.row_repos_heures' => "0u",
    'aide_service.row_repos_debite' => "Nee",
    'aide_service.row_repos_pourquoi' => "De wettelijke tegenprestatie van een wekelijkse rustdag op een variabele rotatie — deze dag werd nooit \"verdiend\" door een overschot aan uren, dus is niets verschuldigd, en in tegenstelling tot ADV verbruikt ze geen enkel krediet.",
    'aide_service.row_ferienontrav_type' => "Feestdag <i>(niet gewerkt)</i>",
    'aide_service.row_ferienontrav_heures' => "0u",
    'aide_service.row_ferienontrav_debite' => "Nee",
    'aide_service.row_ferienontrav_pourquoi' => "Zoals betaald verlof, al afgetrokken van de 1607u-berekening.",
    'aide_service.row_ferietrav_type' => "Feestdag <i>(gewerkt)</i>",
    'aide_service.row_ferietrav_heures' => "7u",
    'aide_service.row_ferietrav_debite' => "Nee (normale dag)",
    'aide_service.row_ferietrav_pourquoi' => "Telt als een gewone werkdag, vergeleken met 7u — geen volledige \"bonus\" op de gedane uren. De looncompensatie voor een gewerkte feestdag is een loonadministratie-kwestie, los van deze teller.",
    'aide_service.row_maladie_type' => "Ziekteverlof",
    'aide_service.row_maladie_heures' => "7u",
    'aide_service.row_maladie_debite' => "Nee (neutraal)",
    'aide_service.row_maladie_pourquoi' => "\"Neutraliserings\"-principe: de verschuldigde 7u worden automatisch gecrediteerd alsof de gewone dag gewerkt was, om een werknemer die een ondergane afwezigheid niet kan inhalen niet te benadelen.",
    'aide_service.callout_warn_piege_rtt' => "<b>Veelvoorkomende valkuil:</b> ADV is niet neutraal zoals betaald verlof of een rustdag — een ADV-dag opnemen debiteert echt 7u van uw voorsprongteller. Verwar het niet met een rustdag, die op 0u blijft en nooit iets debiteert.",
    'aide_service.callout_tip_suivi_detaille' => "Vandaag gebeurt de gedetailleerde opvolging (teamplanning, jaardoel, gewerkte uren) op de schermen van het onderhoudsteam, waartoe het dienstenportaal nog geen rechtstreekse toegang heeft. Voor uw eigen situatie (opgenomen dagen, urenteller), neem contact op met uw verantwoordelijke of de HR-dienst.",
    'aide_service.callout_lock_pedagogique' => "Dit artikel is een algemene pedagogische uitleg, geen contractueel document — bij twijfel over uw persoonlijke situatie blijft uw verantwoordelijke of HR de referentie.",
    'aide_service.planning_lede' => "Deze functie bestaat nog niet voor het dienstenportaal — deze sectie beschrijft wat overwogen wordt, als voorbeeld.",
    'aide_service.callout_lock_pas_dispo' => "<b>Nog niet beschikbaar.</b> Het onderhoudsteam beschikt al over een planning; het doel is om, na verloop van tijd, een gelijkaardig hulpmiddel te openen om het rooster van uw teams rechtstreeks vanuit het dienstenportaal aan te maken en op te volgen.",
    'aide_service.planning_p2' => "Het overwogen principe is hetzelfde als reeds gebruikt aan onderhoudszijde: een manuele planning, weergegeven als een dagelijks rooster — één vakje per dag en per persoon. Een klik op een vakje zou toelaten om in te stellen:",
    'aide_service.planning_li1' => "een <b>gewerkte dienst</b> (ochtend, middag, nacht of volledige dag), of",
    'aide_service.planning_li2' => "een <b>afwezigheid</b> (betaald verlof, ADV, ziekte, feestdag).",
    'aide_service.shot_planning_alt' => "Wekelijks planningsrooster gebruikt door het onderhoudsteam",
    'aide_service.shot_planning_cap' => "Voorbeeld van het rooster dat vandaag door het onderhoudsteam gebruikt wordt — hetzelfde principe wordt overwogen voor het dienstenportaal.",
    'aide_service.callout_tip_bientot' => "Deze sectie zal aangevuld worden met een echte handleiding zodra de functie in gebruik genomen wordt voor het dienstenportaal.",
    'aide_service.astuces_li1' => "<b>Onthoud uw persoonlijke code goed</b>: hij bewijst dat u het bent bij elke nieuwe aanvraag, en opent de berichten.",
    'aide_service.astuces_li2' => "<b>Wees precies in de beschrijving</b>: hoe duidelijker ze is, hoe sneller het onderhoud kan prioriteren en ingrijpen.",
    'aide_service.astuces_li3' => "<b>Een aanvraag \"In afwachting\" is niet vergeten</b>: ze wacht gewoon tot het onderhoud ze valideert — deze termijn hangt af van de werklast van het team.",
    'aide_service.astuces_li4' => "<b>Gebruik \"Urgent\" enkel voor een echte stilstand of gevaar</b>, zodat de prioriteiten leesbaar blijven voor iedereen.",
    'aide_service.astuces_li5' => "<b>Een geweigerde aanvraag is geen fout van uw kant</b>: de opgegeven reden legt altijd uit waarom, en u kunt indien nodig een nieuwe aanvraag aanmaken.",
    'aide_service.gloss1_dt' => "Persoonlijke code",
    'aide_service.gloss1_dd' => "Reeks van minstens 4 tekens die u bij elke aanvraag identificeert, zoals een elektronische handtekening.",
    'aide_service.gloss2_dt' => "Code van de dienst",
    'aide_service.gloss2_dd' => "De algemene code die uw hele team gebruikt om zich aan te melden bij het portaal — anders dan de persoonlijke code.",
    'aide_service.gloss3_dt' => "BI",
    'aide_service.gloss3_dd' => "\"Bon d'Intervention\" (interventiebon) — het nummer dat aan uw aanvraag wordt toegekend zodra ze gevalideerd is door het onderhoud.",
    'aide_service.gloss4_dt' => "Weigeringsreden",
    'aide_service.gloss4_dd' => "De tekst die een administrator invoert wanneer een aanvraag geen gevolg krijgt, zichtbaar in het detail van het geweigerde ticket.",
    'aide_service.gloss5_dt' => "Logboek",
    'aide_service.gloss5_dd' => "De tussentijdse notities die de technicus achterlaat terwijl een ticket nog loopt — te onderscheiden van het eindrapport van afsluiting.",
    'aide_service.gloss6_dt' => "Uitbesteed",
    'aide_service.gloss6_dd' => "Een interventie toevertrouwd aan een extern bedrijf in plaats van een interne technicus; de naam ervan staat op het ticket vermeld.",
    'aide_service.faq_lede' => "Korte antwoorden, om snel vooruit te gaan.",
    'aide_service.faq1_q' => "Waarvoor dient de persoonlijke code?",
    'aide_service.faq1_li1' => "<b>1e aanvraag:</b> verzin een code (minstens 4 tekens) — ze wordt automatisch onthouden, zoals een handtekening.",
    'aide_service.faq1_li2' => "<b>Volgende aanvragen:</b> voer altijd dezelfde code opnieuw in om te bevestigen dat u het echt bent.",
    'aide_service.faq1_li3' => "Ze dient ook om u te identificeren om met het onderhoud over uw tickets te communiceren (berichten).",
    'aide_service.faq2_q' => "Ik vind de machine niet in de lijst",
    'aide_service.faq2_a' => "Kies <b>\"Andere / Niet vermeld\"</b> bij de laatste locatiestap, en beschrijf dan de machine en haar plaats nauwkeurig in het beschrijvingsveld.",
    'aide_service.faq3_q' => "Hoe beschrijf ik mijn probleem goed?",
    'aide_service.faq3_li1' => "<b>Wat:</b> wat gebeurt er? (lawaai, lek, breuk, elektrische storing...)",
    'aide_service.faq3_li2' => "<b>Sinds wanneer:</b> net nu, sinds deze ochtend...",
    'aide_service.faq3_li3' => "<b>Ernst:</b> ligt de productie stil? Is er gevaar?",
    'aide_service.faq4_q' => "Wat is het verschil tussen \"Normaal\" en \"Urgent\"?",
    'aide_service.faq4_a' => "Kies <b>Urgent</b> enkel bij een lijnstilstand of onmiddellijk gevaar. Voor elke gewone interventie, laat op <b>Normaal</b> staan — het onderhoud prioriteert zijn interventies op die basis.",
    'aide_service.faq5_q' => "Wat betekenen de statussen van mijn tickets?",
    'aide_service.faq5_a' => "<span class=\"pill pill-attente\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>In afwachting</span> uw aanvraag is net verzonden.<br>\n<span class=\"pill pill-afaire\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Te doen</span> gevalideerd en gepland.<br>\n<span class=\"pill pill-cours\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>In uitvoering</span> een technicus grijpt in.<br>\n<span class=\"pill pill-termine\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Afgerond</span> interventie afgesloten, verslag beschikbaar.<br>\n<span class=\"pill pill-refuse\" style=\"margin:2px 4px 2px 0;\"><span class=\"pill-dot\"></span>Geweigerd</span> niet weerhouden, reden zichtbaar in het detail.",
    'aide_service.faq6_q' => "Hoe communiceer ik met de technicus over een ticket?",
    'aide_service.faq6_a' => "Open het ticket vanaf de pagina <b>Opvolging van mijn aanvragen</b>, en klik dan op <b>Berichten</b>. U moet uw naam en persoonlijke code opgeven om een bericht te versturen.",
    'aide_service.faq7_q' => "Waarom werd mijn aanvraag geweigerd?",
    'aide_service.faq7_a' => "Een administrator heeft ervoor gekozen er geen gevolg aan te geven (duplicaat, buiten het onderhoudsbereik...). De exacte reden staat altijd vermeld: open het ticket in <b>Opvolging van mijn aanvragen</b> om ze te lezen in het rode kader \"Weigeringsreden\".",
    'aide_service.faq8_q' => "Hoe stel ik een idee voor de GMAO voor?",
    'aide_service.faq8_a' => "Klik vanaf de startpagina op de tegel <b>Ideeën om de GMAO te verbeteren</b>. Vul het korte formulier in (titel, categorie, beschrijving): uw idee wordt naar het GMAO-team gestuurd, en u kunt de status ervan opvolgen — en met de administrator praten — rechtstreeks op dezelfde pagina.",
    'aide_service.faq9_q' => "Hoe vind ik snel mijn tickets met een ongelezen bericht terug?",
    'aide_service.faq9_a' => "Open op <b>Opvolging van mijn aanvragen</b> het statusfilter en kies <b>\"Ongelezen berichten\"</b> — de lijst behoudt dan enkel de tickets die op uw lezing wachten.",
    'aide_service.callout_contact' => "Een vraag die hier geen antwoord vindt, of een technisch probleem met het portaal zelf? Neem rechtstreeks contact op met het onderhouds-/GMAO-team.",

    'aide_annualisation.page_title_tag' => "Verlof, ADV & Jaarurenregeling - Hulp GMAO",
    'aide_annualisation.hero_h1' => "Verlof, ADV, ziekte & Jaarurenregeling",
    'aide_annualisation.hero_tagline' => "Begrijpen hoe uw uren over het jaar geteld worden — en waarom, volgens de wet.",
    'aide_annualisation.pill_version' => "Versie <b>1.0</b>",
    'aide_annualisation.pill_updated' => "Bijgewerkt op <b>18/08/2026</b>",
    'aide_annualisation.pill_ecrans' => "Betreft scherm <b>Planning</b>",
    'aide_annualisation.pill_sourced' => "Gebaseerd op arbeidsrecht",
    'aide_annualisation.toc_vue_ensemble' => "Overzicht",
    'aide_annualisation.toc_saisir' => "Verlof, ADV, feestdag… opnemen",
    'aide_annualisation.toc_formule' => "Waar komt 1607u vandaan?",
    'aide_annualisation.toc_traitement' => "Hoe elke afwezigheid geteld wordt",
    'aide_annualisation.toc_ajustements' => "Aanpassingen van het doel (gesplitst verlof, 48u)",
    'aide_annualisation.toc_exemples' => "Concrete uitgewerkte voorbeelden",
    'aide_annualisation.toc_repere' => "De markering \"35u/week\"",
    'aide_annualisation.toc_faq' => "Veelgestelde vragen",
    'aide_annualisation.toc_glossaire' => "Woordenlijst",
    'aide_annualisation.toc_sources' => "Juridische bronnen",
    'aide_annualisation.vue_lede' => "De <b>jaarurenregeling</b> van de arbeidstijd houdt in dat uw uren niet week per week, maar over een volledig jaar geteld worden — hier, van <b>1 april tot 31 maart</b>. Het te bereiken doel over deze periode is <b>1607u</b> (tenzij een andere individuele overeenkomst geldt, instelbaar in Instellingen). Dit artikel legt uit hoe dit totaal berekend wordt, en vooral hoe elk type niet-gewerkte dag (verlof, ADV, feestdag, ziekte) daarin verwerkt wordt.",
    'aide_annualisation.tbl1_th_ou' => "Waar het gebeurt",
    'aide_annualisation.tbl1_th_usage' => "Waarvoor het dient",
    'aide_annualisation.row_planning_label' => "Planning",
    'aide_annualisation.row_planning_desc' => "Voor elke dag opent een klik een venster om een gewerkte <b>dienst</b> in te stellen (ochtend / middag / nacht / volledige dag) en/of een <b>gebeurtenis</b> (betaald verlof, halve dag verlof, ADV, ziekte, feestdag), met de gewerkte uren indien nodig.",
    'aide_annualisation.row_planning_annuel_label' => "Jaarplanning",
    'aide_annualisation.row_planning_annuel_desc' => "Vanuit de Planning, een volledige kalender maand per maand met het detail van elke ingestelde dag, het opgeteld totaal, het doel (aanpasbaar), het gesplitst verlof, en de hulpbubbel die uw urensaldo in detail uitlegt.",
    'aide_annualisation.callout_tip_pas_calculer' => "U hoeft zelf niets te berekenen: vul uw dagen gewoon normaal in, het hulpmiddel past automatisch de juiste, hieronder beschreven regels toe.",
    'aide_annualisation.saisir_lede' => "Klik op het scherm Planning op het vakje van de betreffende dag op uw naam.",
    'aide_annualisation.s_step1_titre' => "Kies een dienst (als u die dag werkt)",
    'aide_annualisation.s_step1_desc' => "Ochtend, middag, nacht of volledige dag. Geef de gewerkte uren op als ze afwijken van het gebruikelijke rooster.",
    'aide_annualisation.s_step2_titre' => "Of kies een gebeurtenis (als u afwezig bent)",
    'aide_annualisation.s_step2_desc' => "Betaald verlof, ADV, Rustdag of Ziekte — deze vier vakjes sluiten elkaar uit met een gewerkte dienst: u kunt niet \"met verlof\" en \"op ochtenddienst\" zijn op dezelfde dag. ADV en Rustdag lijken op elkaar maar zijn niet inwisselbaar: zie de volgende sectie voor het verschil.",
    'aide_annualisation.s_step3_titre' => "Bijzondere gevallen: halve dag verlof en feestdag",
    'aide_annualisation.s_step3_desc' => "In tegenstelling tot de andere gebeurtenissen zijn <b>halve dag betaald verlof</b> en <b>feestdag</b> onafhankelijke aan te vinken vakjes die gecombineerd kunnen worden met een werkelijk gewerkte dienst: bijvoorbeeld een dag waarop u 's ochtends werkt en 's middags een halve dag verlof opneemt, of een feestdag waarop u toch de dienst \"Nacht\" aanvinkt omdat u die nacht gewerkt heeft.",
    'aide_annualisation.callout_warn_ferie_travaille' => "<b>Gewerkte feestdag:</b> als u uitzonderlijk een feestdag moet werken (gebruikelijk in industrieel onderhoud), vink dan de werkelijk gewerkte dienst aan (ochtend/middag/nacht/volledige dag) <b>en</b> vink bovendien het vakje <b>\"Feestdag\"</b> aan, en geef dan de werkelijk gewerkte uren op (bv. 8u) — het hulpmiddel telt ze normaal mee in uw totaal, bovenop het feit dat deze dag sowieso niet verschuldigd was (zie hieronder). \"Feestdag\" aanvinken vinkt de gekozen dienst niet langer uit.",
    'aide_annualisation.formule_lede' => "1607u is geen willekeurig gekozen getal: het is het resultaat van een precieze wettelijke berekening, die vertrekt van een volledig jaar en alles aftrekt wat geen verschuldigde werkdag is.",
    'aide_annualisation.donut_num' => "228",
    'aide_annualisation.donut_label' => "gewerkte dagen<br>op 365",
    'aide_annualisation.leg_weekends_label' => "Weekends",
    'aide_annualisation.leg_weekends_jours' => "104 dagen",
    'aide_annualisation.leg_cp_label' => "Betaald verlof",
    'aide_annualisation.leg_cp_jours' => "25 dagen",
    'aide_annualisation.leg_feries_label' => "Feestdagen",
    'aide_annualisation.leg_feries_jours' => "8 dagen",
    'aide_annualisation.leg_travailles_label' => "Gewerkte dagen",
    'aide_annualisation.leg_travailles_jours' => "228 dagen",
    'aide_annualisation.donut_note' => "228 gewerkte dagen × 7u = 1596u, + 7u solidariteitsdag = <b>1607u</b> — het detail van de berekening net hieronder.",
    'aide_annualisation.formula_box' => "365 kalenderdagen<br>\n<span class=\"op\">−</span> 104 dagen wekelijkse rust (52 zaterdagen + 52 zondagen)<br>\n<span class=\"op\">−</span> 25 dagen wettelijk betaald verlof<br>\n<span class=\"op\">−</span> 8 feestdagen gemiddeld die op een werkdag vallen<br>\n<span class=\"res\">= 228 werkelijk gewerkte dagen</span><br>\n<br>\n228 dagen <span class=\"op\">×</span> 7u (35u/week ÷ 5 dagen) <span class=\"res\">= 1596u</span><br>\n<span class=\"op\">+</span> 7u solidariteitsdag<br>\n<span class=\"res\">= 1607u</span>",
    'aide_annualisation.formule_p2' => "Het belangrijke punt: <b>het betaald verlof en de feestdagen zijn al vooraf afgetrokken</b> in deze berekening. Uw doel van 1607u is dus niet \"1607u werk plus uw verlof erbovenop\" — het verlof zit er al in. Daarom zou het een tweede keer meetellen (als extra gewerkte tijd) het doel kunstmatig doen overschrijden.",
    'aide_annualisation.callout_law_samedi_p1' => "Een teamregel kan zich bij de algemene wet voegen: bovenop de <b>25 wettelijke verlofdagen</b> kennen sommige teams <b>5 extra dagen toe die enkel op een zaterdag opgenomen mogen worden</b> — dit zijn geen 5 van de 25 normale dagen, maar 5 bijkomende dagen, oftewel <b>30 verlofdagen in totaal over het jaar</b>. In het hulpmiddel worden deze twee quota apart bijgehouden in de samenvatting van de Jaarplanning: \"Betaald verlof\" (/25) en \"Zaterdagverlof\" (/5).",
    'aide_annualisation.callout_law_samedi_p2' => "Dit type regel bestaat doorgaans in bedrijven waarvan de activiteit een <b>piekperiode</b> kent (bv. de zomer), waar op zaterdag werken mogelijk of zelfs nodig wordt: deze 5 extra dagen compenseren die beschikbaarheid door rustdagen op die specifieke dag te garanderen. Dit is geen regel uit het Arbeidswetboek — de exacte reden kan variëren per organisatie, te bevestigen bij uw leidinggevende bij twijfel. Past uw bedrijf deze 30 dagen toe, denk er dan aan uw jaardoel dienovereenkomstig aan te passen vanuit de Jaarplanning of Instellingen, aangezien de standaarddrempel van 1607u de wettelijke basis van 25 dagen veronderstelt.",
    'aide_annualisation.traitement_lede' => "Dit is de kern van de zaak: elk type niet-gewerkte dag volgt een andere regel, en dat is niet willekeurig — elke regel komt van een precies wettelijk principe.",
    'aide_annualisation.tbl2_th_type' => "Type dag",
    'aide_annualisation.tbl2_th_total' => "Telt in mijn werkelijk totaal",
    'aide_annualisation.tbl2_th_du' => "Is \"verschuldigd\" (markering 35u/week)",
    'aide_annualisation.tbl2_th_pourquoi' => "Waarom",
    'aide_annualisation.row2_cp_type' => "Betaald verlof",
    'aide_annualisation.row2_cp_total' => "<b>0u</b>",
    'aide_annualisation.row2_cp_du' => "Nee",
    'aide_annualisation.row2_cp_pourquoi' => "Al afgetrokken in de 1607u-berekening (zie formule hierboven) — een verlofdag is gewoon niet verschuldigd.",
    'aide_annualisation.row2_demicp_type' => "Halve dag betaald verlof",
    'aide_annualisation.row2_demicp_total' => "<b>0u</b>",
    'aide_annualisation.row2_demicp_du' => "Nee (halve dag)",
    'aide_annualisation.row2_demicp_pourquoi' => "Zelfde principe als betaald verlof, toegepast op een halve dag.",
    'aide_annualisation.row2_rtt_type' => "ADV",
    'aide_annualisation.row2_rtt_total' => "<b>0u</b>",
    'aide_annualisation.row2_rtt_du' => "<b>Ja (7u)</b>",
    'aide_annualisation.row2_rtt_pourquoi' => "Een ADV-dag \"verbruikt\" een reeds opgebouwd urenkrediet (u werkte gemiddeld meer dan 35u, de wet is u deze dag in ruil verschuldigd): de dag blijft normaal verschuldigd, wat wel degelijk 7u van uw voorsprong debiteert — dat is het principe zelf van ADV.",
    'aide_annualisation.row2_repos_type' => "Rustdag",
    'aide_annualisation.row2_repos_total' => "<b>0u</b>",
    'aide_annualisation.row2_repos_du' => "Nee",
    'aide_annualisation.row2_repos_pourquoi' => "Wettelijke tegenprestatie van de wekelijkse rust voor een variabele rotatie (zaterdag/zondag/om het even welke weekdag naargelang de planning): deze dag werd nooit \"verdiend\" door een overschot aan uren, dus is niet verschuldigd — in tegenstelling tot ADV verbruikt ze geen enkel krediet.",
    'aide_annualisation.row2_ferienontrav_type' => "Feestdag <i>(niet gewerkt)</i>",
    'aide_annualisation.row2_ferienontrav_total' => "0u",
    'aide_annualisation.row2_ferienontrav_du' => "Nee",
    'aide_annualisation.row2_ferienontrav_pourquoi' => "Zoals betaald verlof zijn de gemiddelde feestdagen al afgetrokken in de 1607u-berekening.",
    'aide_annualisation.row2_ferietrav_type' => "Feestdag <i>(gewerkt)</i>",
    'aide_annualisation.row2_ferietrav_total' => "<b>Werkelijk ingevoerde uren</b>",
    'aide_annualisation.row2_ferietrav_du' => "<b>Ja (7u)</b>",
    'aide_annualisation.row2_ferietrav_pourquoi' => "Een gewerkte feestdag telt als een normale dag in de jaarurenregeling: 8u gewerkt blijft 8u, vergeleken met 7u verschuldigd zoals elke andere dag. De looncompensatie voor een gewerkte feestdag is een loonadministratie-kwestie, los van deze teller.",
    'aide_annualisation.row2_maladie_type' => "Ziekte",
    'aide_annualisation.row2_maladie_total' => "<b>7u (automatisch krediet)</b>",
    'aide_annualisation.row2_maladie_du' => "Ja (7u, zoals een normale dag)",
    'aide_annualisation.row2_maladie_pourquoi' => "\"Neutraliserings\"-principe gehanteerd door het Franse Hof van Cassatie inzake jaarurenregeling: een ziekteafwezigheid wordt geteld alsof de werknemer zijn gebruikelijke dag gewerkt had, om hem niet te benadelen voor een tijd die hij niet kan inhalen.",
    'aide_annualisation.callout_law_rtt_repos' => "<b>ADV en Rustdag zijn niet hetzelfde</b>, ondanks gelijkende namen. ADV compenseert een wekelijkse arbeidstijd boven 35u: ze opnemen komt neer op het verbruiken van een reeds opgebouwd urenkrediet, dus de dag blijft \"verschuldigd\" en debiteert 7u van uw voorsprong. Een Rustdag is gewoon de wekelijkse rust waar elke werknemer recht op heeft — bij teams op variabele rotatie (ochtend/middag/nacht, met rustdagen die op om het even welke dag van de week vallen naargelang de cyclus), werd ze nooit \"gekocht\" met extra uren, dus is ze nooit verschuldigd.",
    'aide_annualisation.callout_tip_logique' => "Onthoud de logica in één zin: <b>betaald verlof, halve dag verlof, Rustdag en niet-gewerkte feestdagen zijn \"niet-verschuldigde\" dagen</b> (ze verschijnen noch als schuld, noch als krediet) — een werkelijk gewerkte feestdag wordt daarentegen opnieuw een normale dag vergeleken met 7u, en een <b>ADV-dag blijft verschuldigd (ze debiteert uw voorsprong)</b> aangezien ze een reeds verworven krediet verbruikt — terwijl <b>ziekte \"alsof\" geneutraliseerd wordt</b> — ze wordt gecrediteerd om geen schuld te creëren die u niet zou kunnen inhalen.",
    'aide_annualisation.ajustements_lede' => "Bovenop de basis 1607u verminderen twee situaties voorzien door het jaarurenakkoord het aantal werkelijk verschuldigde uren over het jaar. Ze worden ingesteld vanuit het venster <b>Jaarplanning</b> (klik op \"Volledige jaarplanning bekijken\" vanuit het planningsvenster).",
    'aide_annualisation.tbl3_th_ajustement' => "Aanpassing",
    'aide_annualisation.tbl3_th_effet' => "Effect op het doel",
    'aide_annualisation.tbl3_th_qui' => "Wie stelt het in",
    'aide_annualisation.row3_objectif_ajustement' => "Basis jaardoel",
    'aide_annualisation.row3_objectif_effet' => "Standaard 1607u",
    'aide_annualisation.row3_objectif_qui' => "Uzelf of een admin, rechtstreeks vanuit de Jaarplanning (een admin kan het ook voor eender wie instellen vanuit Instellingen).",
    'aide_annualisation.row3_fractionnement_ajustement' => "Dagen gesplitst verlof",
    'aide_annualisation.row3_fractionnement_effet' => "<b>−7u</b> (1 dag) of <b>−14u</b> (2 dagen)",
    'aide_annualisation.row3_fractionnement_qui' => "Uzelf of een admin, naargelang de voorwaarden waarin het hoofdverlof werd opgenomen (Art. 6).",
    'aide_annualisation.row3_48h_ajustement' => "Weken van 48u",
    'aide_annualisation.row3_48h_effet' => "<b>−4u</b> per betrokken week, automatisch gedetecteerd",
    'aide_annualisation.row3_48h_qui' => "Niemand — berekend op basis van de uren die u invoert.",
    'aide_annualisation.callout_law_fractionnement_p1' => "<b>Gesplitst verlof</b> (Art. 6 van het akkoord): als uw hoofdverlof in één keer wordt opgenomen over minstens 12 werkdagen (waarvan 2 wekelijkse rustdagen), kent de wet u extra rustdagen toe. Aangezien dit afhangt van de exacte voorwaarden van het opnemen van het verlof, is het niet automatisch berekenbaar: HR bepaalt of u recht heeft op 1 of 2 dagen, en een admin voert het in het hulpmiddel in — het weergegeven doel vermindert dan met het overeenkomstige aantal uren.",
    'aide_annualisation.callout_law_fractionnement_p2' => "<b>Weken van 48u</b> (Art. 3, piekperiodes): weken waarin u werkelijk 48u of meer gewerkt heeft, geven recht op 4u rust, automatisch afgetrokken van het doel — het hulpmiddel detecteert deze weken zelf op basis van uw ingevoerde uren, geen bijkomende invoer nodig.",
    'aide_annualisation.callout_tip_plafond_cp' => "Het akkoord plafonneert ook het doorlopende hoofdverlof op <b>12 werkdagen</b> wanneer het de periode van <b>15 juli tot 30 september</b> overlapt (Art. 6). Overschrijdt u dit plafond, dan verschijnt een alarmbadge op de tegel \"Betaald verlof\" van de jaarsamenvatting, met het detail bij hover.",
    'aide_annualisation.exemples_lede' => "Om het duidelijk te visualiseren, hier vier typische situaties met het detail van de berekening. Technicus \"Léa\" is een fictief voorbeeld.",
    'aide_annualisation.ex1_titre' => "Voorbeeld 1 — Een week betaald verlof",
    'aide_annualisation.ex1_desc' => "Léa neemt 5 dagen betaald verlof op (van maandag tot vrijdag) tijdens een week waarin ze normaal 5 dagen van 8u zou gewerkt hebben.",
    'aide_annualisation.ex1_calc' => "Werkelijk totaal van de week: 5 × 0u = <b>0u</b><br>\nMarkering 35u/week van deze week: 5 × 0u verschuldigd = <b>0u</b><br>\nVerschil: 0u — geen valse achterstand gecreëerd.",
    'aide_annualisation.ex1_verdict' => "Verlof opnemen is nooit nadelig",
    'aide_annualisation.ex2_titre' => "Voorbeeld 2 — Drie dagen ziekte",
    'aide_annualisation.ex2_desc' => "Léa is 3 dagen met ziekteverlof, tijdens een week waarin ze gepland stond voor 7u/dag.",
    'aide_annualisation.ex2_calc' => "Werkelijk totaal: 3 × 7u (automatisch krediet) = <b>+21u</b><br>\nMarkering: 3 × 7u verschuldigd = <b>21u</b><br>\nVerschil: 0u — ze blijft exact op tempo, zonder te hebben kunnen werken.",
    'aide_annualisation.ex2_verdict' => "Geen enkele urenschuld gecreëerd door ziekte",
    'aide_annualisation.ex3_titre' => "Voorbeeld 3 — Een gewerkte feestdag",
    'aide_annualisation.ex3_desc' => "Op 14 juli (feestdag) wordt Léa uitzonderlijk ingezet en werkt 8u 's nachts: ze vinkt de dienst \"Nacht\" <b>en</b> het vakje \"Feestdag\" aan, met 8u ingevoerd.",
    'aide_annualisation.ex3_calc' => "Werkelijk totaal: <b>+8u</b> (de werkelijk ingevoerde uren)<br>\nMarkering: feestdag maar werkelijk gewerkt, geteld als een normale dag = <b>7u</b><br>\nVerschil: <b>+1u</b> — zoals elke dag waarop ze 8u in plaats van 7u zou gewerkt hebben. De looncompensatie voor deze gewerkte feestdag blijft verschuldigd, maar dat is een loonadministratie-kwestie, niet van deze teller.",
    'aide_annualisation.ex3_verdict' => "+1u voorsprong, zoals een normale dag van 8u",
    'aide_annualisation.ex4_titre' => "Voorbeeld 4 — Dagen van 8u in plaats van 7u",
    'aide_annualisation.ex4_desc' => "Léa werkt 20 \"volledige dag\"-diensten van elk 8u (gebruikelijke dienst van het team), over een periode waarin de wettelijke markering 7u/dag verwacht.",
    'aide_annualisation.ex4_calc' => "Werkelijk totaal: 20 × 8u = <b>160u</b><br>\nMarkering: 20 × 7u verschuldigd = <b>140u</b><br>\nVerschil: <b>+20u voorsprong</b>, gewoon omdat haar typische dag 8u duurt en niet 7u.",
    'aide_annualisation.ex4_verdict' => "Dit is normaal en verwacht wanneer de typische dag 8u duurt",
    'aide_annualisation.repere_lede' => "Op uw jaarlijkse voortgangsbalk toont een kleine markering waar u <b>vandaag</b> zou moeten staan als u sinds 1 april een gestaag ritme van 35u/week volgde.",
    'aide_annualisation.repere_li1' => "Van maandag tot vrijdag telt elke sinds 1 april verstreken dag als verschuldigd aan 7u/dag.",
    'aide_annualisation.repere_li2' => "Zaterdag en zondag zijn standaard niets verschuldigd (rustdag) — <b>tenzij ze werkelijk gewerkt worden</b> (dienst + uren ingevoerd), in welk geval ze vergeleken worden met 7u exact zoals een weekdag. Een zaterdag van 8u gewerkt geeft dus slechts +1u voorsprong, geen +8u.",
    'aide_annualisation.repere_li3' => "Betaald verlof, halve dag verlof, Rustdag en <i>niet-gewerkte</i> feestdag zijn niet verschuldigd (0u). Voor betaald verlof/halve dag/feestdag komt dit omdat ze al afgetrokken zijn van de 1607u-drempel; de Rustdag is gewoon de wekelijkse rust van een variabele rotatie, nooit \"gekocht\" met een overschot aan uren. Een <i>werkelijk gewerkte</i> feestdag wordt opnieuw een normale dag vergeleken met 7u — een feestdag werken is niet langer een automatische bonus, enkel de uren boven 7u die dag tellen als voorsprong.",
    'aide_annualisation.repere_li4' => "<b>ADV blijft daarentegen verschuldigd (7u)</b>: ze opnemen verbruikt een reeds opgebouwd urenkrediet, dus ze debiteert die dag 7u van uw voorsprong — verwar dit niet met de Rustdag hierboven, die neutraal blijft.",
    'aide_annualisation.repere_li5' => "Ziekte blijft geteld als verschuldigd (7u), aangezien ze sowieso identiek gecrediteerd wordt in uw werkelijk totaal — het verschil blijft dus neutraal.",
    'aide_annualisation.repere_p_avance_retard' => "\"Voorsprong\" betekent dat uw werkelijk totaal hoger ligt dan wat het wettelijke ritme van 35u/week op die datum van u verwachtte (meestal omdat uw dagen 8u duren en niet 7u). \"Achterstand\" betekent het omgekeerde. Geen van beide is een oordeel — het is gewoon een ritme-indicator, te vergelijken met het uiteindelijke jaardoel (1607u), de enige deadline die echt telt.",
    'aide_annualisation.callout_tip_badge_jour' => "In de <b>Jaarplanning</b> toont elke reeds verstreken dag een klein badge \"+Xu\" (groen) of \"-Xu\" (rood) naast de ingevoerde uren, dat het verschil van die specifieke dag ten opzichte van het verschuldigde toont. Een samenvatting van hetzelfde type verschijnt onder het totaal van elke maand.",
    'aide_annualisation.faq1_q' => "Mijn urentotaal is veranderd na een update van de applicatie, waarom?",
    'aide_annualisation.faq1_a' => "Vóór augustus 2026 crediteerde het hulpmiddel automatisch 7u per opgenomen verlofdag (bovenop eventueel ingevoerde uren), om te vermijden dat verlof opnemen een \"achterstand\" ten opzichte van het doel zou creëren. Deze logica vertrok van een goede bedoeling maar was onjuist: betaald verlof is <b>al afgetrokken</b> in de 1607u-berekening (zie de formule hierboven), dus het extra crediteren deed het behaalde totaal kunstmatig oplopen. Betaald verlof telt voortaan voor 0u, wat de wettelijk correcte waarde is.",
    'aide_annualisation.faq2_q' => "Waarom wordt ziekte niet zoals betaald verlof behandeld?",
    'aide_annualisation.faq2_a' => "Omdat het niet dezelfde juridische situatie is. Betaald verlof is een <i>voorzien</i> recht dat al is afgetrokken van de 1607u-drempel. Ziekte is een <i>ondergane</i>, onvoorziene afwezigheid — de rechtspraak verplicht ze \"alsof\" te neutraliseren, alsof de werknemer zijn gebruikelijke uurrooster gewerkt had, om geen urenschuld te creëren die hij niet zou kunnen inhalen.",
    'aide_annualisation.faq3_q' => "Is ADV hetzelfde als betaald verlof?",
    'aide_annualisation.faq3_a' => "Nee, en hun effect op uw teller verschilt ook. Betaald verlof is een bij wet vastgelegd recht (minstens 25 dagen per jaar) dat al is afgetrokken van de 1607u-drempel: het is nooit verschuldigd, wat er ook gebeurt. ADV bestaat niet in het Arbeidswetboek: het is een mechanisme eigen aan het bedrijfsakkoord, dat een wekelijkse arbeidstijd boven 35u compenseert door u de te veel gewerkte uren te laten \"terugnemen\" als rustdag — een ADV-dag opnemen blijft dus geteld als een verschuldigde dag (7u), wat uw voorsprong dienovereenkomstig debiteert.",
    'aide_annualisation.faq4_q' => "Wat is het verschil tussen ADV en Rustdag?",
    'aide_annualisation.faq4_a' => "ADV verbruikt een urenkrediet dat u al heeft opgebouwd door gemiddeld meer dan 35u te werken: de dag blijft verschuldigd (7u), dus ze opnemen vermindert uw voorsprong. De Rustdag is de wettelijke tegenprestatie van de wekelijkse rust — voor een team op variabele rotatie (ochtend/middag/nacht, met rustdagen die op om het even welke dag van de week vallen naargelang de cyclus), werd deze rust nooit \"verdiend\" door een overschot aan uren, dus is ze nooit verschuldigd (0u), zonder uw ADV-saldo aan te raken.",
    'aide_annualisation.faq5_q' => "Ik heb voorsprong / achterstand op de markering, moet ik me zorgen maken?",
    'aide_annualisation.faq5_a' => "Nee — het is gewoon een tussentijdse ritme-indicator, geen verplichting. Wat echt telt, is het totaal over het volledige jaar (1 april tot 31 maart) vergeleken met het doel van 1607u, weergegeven bovenaan het venster Jaarplanning.",
    'aide_annualisation.gloss1_dt' => "Jaarurenregeling",
    'aide_annualisation.gloss1_dd' => "Verrekening van de arbeidstijd over een periode van een jaar (hier: 1 april tot 31 maart) in plaats van week per week.",
    'aide_annualisation.gloss2_dt' => "Betaald verlof",
    'aide_annualisation.gloss2_dd' => "Wettelijke verlofdag, opgebouwd aan 2,5 werkdagen per gewerkte maand, oftewel minstens 25 dagen/jaar.",
    'aide_annualisation.gloss3_dt' => "ADV",
    'aide_annualisation.gloss3_dd' => "Arbeidsduurvermindering: rustdag die een wekelijks uurrooster boven 35u compenseert, vastgelegd door bedrijfsakkoord (niet rechtstreeks door de wet). Verbruikt een reeds verworven urenkrediet: blijft geteld als verschuldigd (7u) in het hulpmiddel.",
    'aide_annualisation.gloss4_dt' => "Rustdag",
    'aide_annualisation.gloss4_dd' => "Wettelijke tegenprestatie van de wekelijkse rust voor een variabele rotatie (rustdagen die op om het even welke dag van de week vallen naargelang de ochtend/middag/nacht-cyclus). In tegenstelling tot ADV, nooit verschuldigd (0u) en verbruikt geen enkel krediet.",
    'aide_annualisation.gloss5_dt' => "Feestdag",
    'aide_annualisation.gloss5_dd' => "Dag opgesomd door de wet (1 januari, 1 mei, 14 juli…) waarop werk in principe niet verschuldigd is, tenzij de activiteit uitzonderlijk wordt aangehouden.",
    'aide_annualisation.gloss6_dt' => "\"Alsof\"-neutralisering",
    'aide_annualisation.gloss6_dd' => "Jurisprudentieel principe: een gerechtvaardigde en betaalde afwezigheid (ziekte) wordt geteld alsof het voorziene uurrooster gewerkt was, om de werknemer niet te benadelen.",
    'aide_annualisation.gloss7_dt' => "Solidariteitsdag",
    'aide_annualisation.gloss7_dd' => "7u extra onbetaald werk per jaar, toegevoegd aan de 1607u-berekening, bestemd voor de financiering van de autonomie van ouderen en personen met een handicap.",
    'aide_annualisation.gloss8_dt' => "Markering 35u/week",
    'aide_annualisation.gloss8_dd' => "Tussentijdse ritme-indicator op de voortgangskaart: wat u \"zou moeten\" hebben opgebouwd tot vandaag bij een gestaag ritme.",
    'aide_annualisation.gloss9_dt' => "Gesplitst verlof",
    'aide_annualisation.gloss9_dd' => "Extra rustdagen toegekend wanneer het hoofdverlof doorlopend opgenomen wordt over 12 werkdagen of meer (Art. 6): 1 of 2 dagen naargelang de voorwaarden, naar goeddunken van HR.",
    'aide_annualisation.sources_lede' => "De in dit artikel beschreven regels zijn gebaseerd op de officiële 1607u-berekening en de rechtspraak van het Franse Hof van Cassatie inzake jaarurenregeling/modulatie van de arbeidstijd.",
    'aide_annualisation.source1' => "Calcul des 1607 heures et annualisation — guide DRH 2026",
    'aide_annualisation.source2' => "RTT et congés payés : quelles différences ?",
    'aide_annualisation.source3' => "Absence maladie et heures supplémentaires — méthode de calcul (Cour de cassation)",
    'aide_annualisation.source4' => "Arrêt maladie et annualisation : les heures supplémentaires",
    'aide_annualisation.callout_lock_pedagogique' => "Dit artikel is een pedagogische uitleg, geen contractueel document. Bij twijfel over uw persoonlijke situatie, neem contact op met HR of uw onderhoudsverantwoordelijke.",
    'aide_annualisation.devnote_li1' => "Berekening van het werkelijke totaal: <code>planning.php</code>, <code>annualisation.php</code>, <code>stats_tech.php</code> — <code>SUM(heures) + 7h als poste='maladie'</code>. Betaald verlof/ADV/feestdag crediteren niets meer sinds de correctie van augustus 2026 (voordien +7u/+3,5u, onjuist aangezien al afgetrokken van de 1607u-drempel).",
    'aide_annualisation.devnote_li2' => "Markering 35u/week: <code>calculerReferenceHeures35h(tech)</code> in <code>planning.php</code>, dag per dag via <code>referenceDuJour(shift, dStr, isWeekend)</code>. Maandag-vrijdag: 7u verschuldigd standaard, 0u als betaald verlof/Rustdag of <code>jour_ferie</code> aangevinkt <i>en niet gewerkt</i> (<code>estTravaille()</code> controleert dat de dienst geen werkelijk gewerkte dienst is), 3,5u bij halve dag verlof. <b>ADV staat niet langer in deze uitsluitingslijst sinds de correctie van augustus 2026</b>: het blijft verschuldigd aan 7u zoals een normale dag, wat de voorsprong wel degelijk debiteert wanneer opgenomen (het verbruikt een reeds verworven urenkrediet, in tegenstelling tot de Rustdag die er geen verbruikt). Zaterdag-zondag: 0u standaard (<code>ligneVide()</code>), tenzij werkelijk ingesteld/gewerkt, in welk geval dezelfde regels gelden als een weekdag. Een gewerkte feestdag (dienst + uren, <code>jour_ferie=1</code>) is dus niet langer \"niet verschuldigd\": ze wordt vergeleken met 7u zoals een normale dag. Ziekte blijft normaal verschuldigd (niet in de uitsluitingslijst) aangezien ze sowieso identiek gecrediteerd wordt aan de kant van het werkelijk totaal. Diezelfde <code>referenceDuJour()</code> voedt ook de dagelijkse badges \"+Xu/-Xu\" (getoond zodra de rij niet <code>ligneVide()</code> is, dus ook een ADV-dag zonder ingevoerde uren) en de maandelijkse samenvatting van <code>renderAnnualGrid()</code>.",
    'aide_annualisation.devnote_li3' => "\"Rustdag\" (dienst <code>repos</code>, categorie <code>evenement</code>, automatisch gemigreerd naar <code>planning_postes</code> door <code>planning.php</code> en <code>parametres.php</code>): toegevoegd in augustus 2026 voor teams op variabele rotatie, waar de wekelijkse rust niet systematisch in het weekend valt. Behandeld zoals betaald verlof in <code>referenceDuJour()</code> (0u verschuldigd, weekdag en weekend), maar blijft een categorie los van ADV in de samenvatting (<code>recap.repos</code>) — de twee delen geen enkele teller.",
    'aide_annualisation.devnote_li4' => "Sinds de correctie van augustus 2026 is \"Feestdag\" niet langer een exclusieve waarde van <code>poste</code> maar een onafhankelijk vakje (kolom <code>planning_shifts.jour_ferie</code>, zelfde mechanisme als <code>demi_conge</code>): aan te vinken bovenop een werkelijk gewerkte dienst (ochtend/middag/nacht/volledige dag) zonder deze te wissen. Automatische migratie bij het laden: oude rijen <code>poste='jour_ferie'</code> worden <code>poste=NULL, jour_ferie=1</code>.",
    'aide_annualisation.devnote_li5' => "Vaste quota betaald verlof (25 dagen/jaar + 5 toegewijde zaterdagen, dus 30, additief en geen deelverzameling): vastgelegd in de samenvatting van <code>renderAnnualGrid()</code>, geen generieke wettelijke regel. Betaald verlof op een zaterdag verbruikt enkel het <code>cpSamedi</code>-quotum, nooit het <code>cp</code>-quotum. Halve dagen verlof hebben geen aparte tegel meer sinds de correctie van augustus 2026: ze crediteren 0,5 dag rechtstreeks in <code>cp</code> of <code>cpSamedi</code> naargelang de dag.",
    'aide_annualisation.devnote_li6' => "Effectief doel (<code>getObjectifEffectif(tech)</code> in <code>planning.php</code>) = <code>utilisateurs.objectif_heures_annuel</code> − 7u/dag gesplitst verlof (<code>planning_fractionnement</code>, tabel per referentieperiode, bewerkbaar door de betrokken technicus of een admin via <code>maintenance.php?action=save_fractionnement</code>) − 4u per ISO-week waar <code>SUM(heures)</code> ≥ 48 (<code>calculerSemaines48h()</code>, automatische detectie, geen specifieke invoer). Het basisdoel is rechtstreeks bewerkbaar vanuit de Jaarplanning door de betrokken technicus of een admin (<code>action=save_objectif</code>), naast Instellingen. De markering 35u/week (<code>calculerReferenceHeures35h</code>) trekt ook het gesplitst verlof en de weken van 48u af, niet enkel het uiteindelijke doel.",
    'aide_annualisation.devnote_li7' => "Alarm verlofplafond (Art. 6, max. 12 opeenvolgende werkdagen tussen 15/07 en 30/09): gedetecteerd in <code>renderAnnualGrid()</code> door opeenvolgende kalenderdagen met <code>poste='cp'</code> te tellen, waarbij een zondag zonder verlof de reeks niet onderbreekt (wekelijkse rustdag, nooit gewerkt). Badge enkel getoond op de tegel \"Betaald verlof\" van de samenvatting.",

    'aide_parc_machine.page_title_tag' => "Het Machinepark beheren - Hulp GMAO",
    'aide_parc_machine.hero_tagline' => "De volledige boomstructuur van de site — de basis waarop alle andere pagina's steunen.",
    'aide_parc_machine.pill_version' => "Versie <b>1.2</b>",
    'aide_parc_machine.pill_updated' => "Bijgewerkt op <b>30/08/2026</b>",
    'aide_parc_machine.pill_ecrans' => "Betreft scherm <b>Machinepark</b>",
    'aide_parc_machine.pill_lecture' => "Lezen voor iedereen, bewerken door admin",
    'aide_parc_machine.toc_vue_ensemble' => "Overzicht",
    'aide_parc_machine.toc_explorer' => "De boom verkennen",
    'aide_parc_machine.toc_ajouter' => "Een machine toevoegen",
    'aide_parc_machine.toc_modifier' => "Wijzigen, verplaatsen, herordenen",
    'aide_parc_machine.toc_renommer' => "Een site, sector, lijn of zone hernoemen",
    'aide_parc_machine.toc_supprimer' => "Een machine verwijderen",
    'aide_parc_machine.toc_selection_multiple' => "Meervoudige selectie",
    'aide_parc_machine.toc_schema_usine' => "Schema Fabriek C & machinefiches",
    'aide_parc_machine.toc_categories_schema' => "Visuele categorieën van het schema",
    'aide_parc_machine.toc_source_verite' => "Waarom deze pagina centraal staat",
    'aide_parc_machine.toc_droits' => "Wie mag wat doen",
    'aide_parc_machine.toc_astuces' => "Tips & valkuilen",
    'aide_parc_machine.toc_glossaire' => "Woordenlijst",
    'aide_parc_machine.vue_lede' => "Het <b>Machinepark</b> is de volledige boomstructuur van alle uitrusting op de site, georganiseerd in 5 niveaus. Het is de <b>enige referentie</b>: het voedt de locatie-keuzelijsten overal elders in de applicatie (aanmaken van een interventiebon, preventief plan, planning...).",
    'aide_parc_machine.tree_usine' => "Fabriek",
    'aide_parc_machine.tree_secteur' => "Sector",
    'aide_parc_machine.tree_ligne' => "Lijn",
    'aide_parc_machine.tree_zone' => "Zone",
    'aide_parc_machine.tree_machine' => "Machine",
    'aide_parc_machine.vue_p2' => "Bovenaan de pagina vat een ondertitel de totalen samen: <i>\"X site(s) · X sectoren · X lijnen · X zones · X machines\"</i>, en elk knooppunt van de boom toont een badge met het aantal machines dat het bevat.",
    'aide_parc_machine.shot_arbre_alt' => "Machinepark-boom met zoekfunctie en filters per uitrustingstype",
    'aide_parc_machine.shot_arbre_cap' => "De volledige Machinepark-boom: zoeken, filterchips per type, en de knooppunten Fabriek (paars) / Zone (oranje) met hun teller.",
    'aide_parc_machine.callout_tip_lecture_seule' => "Een technicus of een lid van het onderhoudsteam ziet exact dezelfde boom als een admin (volledige raadpleging), maar in <b>alleen-lezen</b>-modus — een badge <b>\"Alleen-lezen\"</b> vervangt de toevoegknop rechtsboven.",
    'aide_parc_machine.explorer_lede' => "Alle rollen beschikken over dezelfde navigatiehulpmiddelen.",
    'aide_parc_machine.card_recherche_titre' => "Zoeken",
    'aide_parc_machine.card_recherche_desc' => "Typ de naam van een machine, een zone, een lijn... De resultaten worden geel gemarkeerd, en de bovenliggende knooppunten worden automatisch uitgeklapt om ze te tonen.",
    'aide_parc_machine.card_filtrer_titre' => "Filteren op uitrustingstype",
    'aide_parc_machine.card_filtrer_desc' => "Chips onder de zoekbalk (Mechanisch, Elektrisch, Koeling...) laten toe machines van één type te isoleren. Combineert met zoeken.",
    'aide_parc_machine.card_deplier_titre' => "Alles uitklappen / inklappen",
    'aide_parc_machine.card_deplier_desc' => "Twee specifieke knoppen. De status van elk knooppunt (open/gesloten) wordt op uw toestel onthouden van het ene bezoek naar het andere.",
    'aide_parc_machine.card_chevrons_titre' => "Aanklikbare chevrons",
    'aide_parc_machine.card_chevrons_desc' => "Elk knooppunt wordt individueel uit-/ingeklapt met een klik op zijn chevron.",
    'aide_parc_machine.ajouter_lede' => "Knop <b>\"+ Machine toevoegen\"</b> rechtsboven, of icoon <b>\"+\"</b> bij het hoveren over een zone in de boom (vult meteen haar locatie vooraf in). Opent een zijpaneel.",
    'aide_parc_machine.a_step1_titre' => "Kies de locatie",
    'aide_parc_machine.a_step1_desc' => "Fabriek/plaats → Sector → Lijn → Zone, cascaderend. Elke lijst biedt de reeds bestaande waarden <b>+ een optie \"+ Nieuw...\"</b> die een vrij veld opent om ter plekke een knooppunt aan te maken. Een voorbeeld van het volledige pad verschijnt live onder de velden.",
    'aide_parc_machine.a_step2_titre' => "Geef de machine een naam",
    'aide_parc_machine.a_step2_desc' => "Verplicht veld.",
    'aide_parc_machine.a_step3_titre' => "Kies een uitrustingstype (optioneel)",
    'aide_parc_machine.a_step3_desc' => "Weergegeven als aanklikbare tegels in plaats van een keuzelijst — één tegel per reeds gekend type, plus een tegel <b>\"Andere\"</b> om er ter plekke een nieuw type te maken.",
    'aide_parc_machine.a_step4_titre' => "Sla op",
    'aide_parc_machine.a_step4_desc' => "De 4 locatievelden en de naam zijn allemaal verplicht — anders: \"Gelieve alle velden in te vullen.\"",
    'aide_parc_machine.callout_tip_reouvre' => "Na het opslaan <b>opent het paneel automatisch opnieuw, vooraf ingevuld met dezelfde locatie</b> — handig om meerdere machines na elkaar toe te voegen in dezelfde zone zonder alles opnieuw in te typen.",
    'aide_parc_machine.card_modifier_titre' => "Een machine wijzigen",
    'aide_parc_machine.card_modifier_desc' => "Potloodicoon bij het hoveren over een machinerij, of rechtstreeks klikken op de machine. Zelfde formulier als toevoegen, vooraf ingevuld.",
    'aide_parc_machine.card_glisser_titre' => "Slepen en neerzetten",
    'aide_parc_machine.card_glisser_desc' => "Herorganiseer vrij de volgorde van machines, zones, lijnen en sectoren door slepen en neerzetten. Een machine naar een andere zone verplaatsen wijzigt echt haar locatie in de database.",
    'aide_parc_machine.callout_tip_historique_suit' => "Een machine wijzigen (naam, of locatie) <b>draagt de wijziging automatisch over op haar interventiegeschiedenis</b> (BI-tabel): de geschiedenis volgt de machine, ze breekt niet af.",
    'aide_parc_machine.renommer_lede' => "Potloodicoon bij het hoveren over de rij van het betrokken knooppunt (geen machine, maar een groeperingsniveau). Opent het venster <b>\"Hernoemen\"</b>.",
    'aide_parc_machine.callout_tip_renommage_masse' => "Een fabriek, sector of zone hernoemen <b>hernoemt in één keer alle machines die ze bevat</b>, en werkt de overeenkomstige interventiegeschiedenis bij. Het is een hernoeming in bulk, niet enkel cosmetisch.",
    'aide_parc_machine.renommer_p2' => "Een knooppunt (sector, lijn, zone) waaraan geen enkele machine meer gekoppeld is, <b>verdwijnt automatisch</b> uit de boom — het hoeft niet expliciet verwijderd te worden.",
    'aide_parc_machine.supprimer_lede' => "Vuilbakicoon bij het hoveren over een machinerij, gevolgd door bevestiging in een specifiek venster.",
    'aide_parc_machine.callout_warn_suppression' => "<b>Er wordt geen enkele controle uitgevoerd</b> op de gekoppelde geschiedenis: een machine verwijderen wist haar vroegere interventies of preventieve plannen niet, maar deze worden \"wees\" — de machine zal niet meer verschijnen in de keuzelijsten van andere pagina's, terwijl haar geschiedenis raadpleegbaar blijft waar ze al geregistreerd werd. Denk twee keer na vóór u een machine met actieve geschiedenis verwijdert: een eenvoudige hernoeming is bijna altijd te verkiezen.",
    'aide_parc_machine.selection_lede' => "Knop <b>\"Meervoudige selectie\"</b> bovenaan de pagina: laat een aan te vinken vakje verschijnen vóór elke machine.",
    'aide_parc_machine.selection_p2' => "Een of meer machines aanvinken laat een zwevende balk onderaan het scherm verschijnen, met de knop <b>\"Een type toewijzen...\"</b> — handig om in één keer alle machines van eenzelfde type die er nog geen hadden te herclassificeren, in plaats van ze één voor één te wijzigen. Ook hier laat een tegel <b>\"Andere\"</b> toe een nog niet bestaande typenaam in te voeren in een klein veld dat net eronder verschijnt.",
    'aide_parc_machine.schema_lede' => "Knop <b>\"Schema Fabriek C\"</b> bovenaan de pagina (zichtbaar voor iedereen, admin zowel als technicus): opent een interactieve weergave van lijn C, met elke machine en elke genummerde schroef/band aanklikbaar.",
    'aide_parc_machine.card_tri_titre' => "Sorteerruimte",
    'aide_parc_machine.card_tri_desc' => "Eg, kloppers, Sinex, Aero 1/2, trilelementen, breker, en de 36 genummerde schroeven, weergegeven in twee stroomlijnen: \"productlijn\" (schroeven 1 tot 25) en \"afvallijn\" (schroeven 26 tot 36).",
    'aide_parc_machine.card_cond_titre' => "Verpakking / Palletiseren",
    'aide_parc_machine.card_cond_desc' => "Doseerder, zakvulmachine, sluitmachines, metaaldetector, weegschaal, etiketteermachine, robot, omwikkelaar... en de 19 Pattyn-banden (T1 tot T19).",
    'aide_parc_machine.schema_p2' => "Klikken op een machine of een nummer opent haar <b>machinefiche</b>, met 6 tabbladen:",
    'aide_parc_machine.li_fiche_technique' => "<b>Technische fiche</b>: bovenaan toont een kader de naam van de gekoppelde Machinepark-machine samen met haar volledige locatie (fabriek / sector / lijn / zone), automatisch opgehaald — nooit met de hand opnieuw ingevoerd. Daarna volgen de referenties van motor, reductor, riem, voor-/achterlagers, motor- en kabelnummers, en het <b>automaatkenmerk</b> (het nummer gebruikt op de elektrische/automatiseringsschema's, bv. <code>201052</code>) — te onderscheiden van het mechanische nummer (schroef/band).",
    'aide_parc_machine.li_historique_bi' => "<b>BI-geschiedenis</b>: als de fiche gekoppeld is aan een Machinepark-machine, verschijnt de lijst van reeds uitgevoerde interventiebonnen automatisch, met op elke kaart het interventietype, een eventuele breuk of uitbestede interventie, en een voorbeeld van het verslag. Klikken op een kaart opent het volledige interventierapport; een admin kan er een reeds afgeronde bon heropenen.",
    'aide_parc_machine.li_interventions' => "<b>Interventies</b>: een journaal in vrije invoer, om een interventie te noteren zelfs zonder via een formele BI te gaan.",
    'aide_parc_machine.li_documentation' => "<b>Documentatie</b>: upload van technische documenten (PDF, afbeeldingen, Word, Excel) vanaf om het even welk toestel op het netwerk — opgeslagen per element. Enkel voor admins. Bestanden tot 300 MB.",
    'aide_parc_machine.li_devis' => "<b>Offertes</b>: zelfde principe als Documentatie (zelfde formaten, zelfde 300 MB), om de voor deze machine ontvangen offertes te centraliseren — eveneens enkel voor admins.",
    'aide_parc_machine.li_aide_pannes' => "<b>Hulp / Gekende storingen</b>: vrije nota's (vastgestelde storing + oplossing) om terugkerende storingen en hun oplossing bij te houden, raadpleegbaar door het hele team.",
    'aide_parc_machine.callout_tip_plan_reprend' => "Het plan neemt de exacte positie, vorm en kleur over van de originele technische PowerPoint-schema's.",
    'aide_parc_machine.callout_lock_droits_fiche' => "Admin en technicus zien allebei de gekoppelde Machinepark-machine (naam + locatie) en kunnen allebei de technische fiche invullen en een interventie toevoegen. Enkel de <b>admin</b> kan een document/offerte versturen of verwijderen, en een fiche aan een Machinepark-machine koppelen/ontkoppelen (voor de automatische BI-geschiedenis).",
    'aide_parc_machine.h3_modifier_plan' => "Het plan zelf wijzigen (admin)",
    'aide_parc_machine.modifier_plan_p' => "Knop <b>\"Plan wijzigen\"</b> bovenaan het schema (enkel admin): elke vorm wordt rechtstreeks met de muis verplaatsbaar en herschaalbaar (of met de vinger op tablet). Een <b>linkerklik</b> selecteert een vorm om ze te verplaatsen/herschalen; een <b>rechterklik</b> (of het toevoegen van een nieuwe vorm) opent bovendien het paneel <b>\"Eigenschappen van de vorm\"</b>:",
    'aide_parc_machine.li_texte_forme' => "<b>Tekst</b> weergegeven op de vorm, en <b>Vorm</b> (uitgebreide bibliotheek: rechthoeken, cirkels, driehoeken, veelhoeken, pijlen, organigramsymbolen...).",
    'aide_parc_machine.li_categorie' => "<b>Categorie</b>: <code>Vrije eigenschappen</code> (standaard — alle onderstaande instellingen blijven zichtbaar en rechtstreeks aanpasbaar) of een van de categorieën aangemaakt in <a href=\"#categories-schema\">Instellingen</a> (Schroef, Transportband...). Een categorie kiezen past onmiddellijk haar kleuren en startwaarden toe, en <b>klapt dan de gedetailleerde instellingen in</b> achter een knop <b>\"Geavanceerde instellingen tonen\"</b> — te openen om deze specifieke vorm aan te passen zonder de andere te raken. Het icoon <i class=\"fa-solid fa-rotate\"></i> naast het menu past de waarden van de reeds geselecteerde categorie opnieuw toe (nuttig als haar kleuren intussen gewijzigd werden in Instellingen).",
    'aide_parc_machine.li_couleurs' => "<b>Kleuren</b>: vulling / rand / tekst, vakje \"Zonder rand\", vakje \"Verloop\" (2 kleuren, met een richtingskeuze) en <b>Effect</b> (Geen, Schaduw, Reliëf, Verdiept, Gloed).",
    'aide_parc_machine.li_taille_rotation' => "<b>Grootte &amp; rotatie</b>: breedte, hoogte, tekstgrootte, <b>Rotatie vorm</b> en <b>Rotatie tekst</b> (twee onafhankelijke instellingen).",
    'aide_parc_machine.li_comportement' => "<b>Gedrag</b>: <b>Aanklikbaar</b> (uitvinken om een machine in een louter decoratief element te veranderen, of het omgekeerde aanvinken op een achtergrondelement om er een machinefiche aan te geven) en de volgorde voor-/achtergrond.",
    'aide_parc_machine.li_supprimer_forme' => "<b>Deze vorm verwijderen</b> — verwijdert ook haar machinefiche, interventies en documenten.",
    'aide_parc_machine.p_ajouter_forme' => "Knop <b>\"+ Vorm toevoegen\"</b> om een volledig nieuw element aan te maken. Elke wijziging wordt automatisch opgeslagen (geen aparte \"Opslaan\"-knop).",
    'aide_parc_machine.callout_tip_rotation_texte' => "De tekst van een vorm die <b>hoger is dan breed</b> (bijvoorbeeld een schroef) draait automatisch om van onder naar boven te lezen (kop naar links gekanteld), of u nu een breedte/hoogte typt of met de muis herschaalt — en keert terug naar horizontaal als de vorm opnieuw breder dan hoog wordt. Deze automatisering raakt nooit een handmatig gekozen tekstrotatie.",
    'aide_parc_machine.categories_lede' => "In <b>Instellingen → Categorieën van het schema</b> (of via het icoon <i class=\"fa-solid fa-gear\"></i> naast \"+ Vorm toevoegen\" in het schema, dat er in één klik naartoe leidt), kan de admin herbruikbare categorieën aanmaken — <i>Schroef</i>, <i>Afvalschroef</i>, <i>Transportband</i>... — om in één keer alle vormen van eenzelfde type te stylen in plaats van elke vorm één voor één in te stellen.",
    'aide_parc_machine.categories_p2' => "Een categorie groepeert twee soorten instellingen, met bewust verschillend gedrag voor elk:",
    'aide_parc_machine.li_apparence' => "<b>Uiterlijk</b> (vullingskleur, verloop, rand, effect): <b>altijd gesynchroniseerd</b>. Deze kleuren wijzigen in Instellingen draagt de wijziging onmiddellijk over op alle vormen die al aan deze categorie toegewezen zijn.",
    'aide_parc_machine.li_valeurs_depart' => "<b>Startwaarden</b> (vorm, grootte, rotatie, standaardtekst, aanklikbaar): <b>eenmalig</b> toegepast, op het moment dat de categorie gekozen wordt op een vorm in het schema. Een latere wijziging van deze waarden in Instellingen wijzigt nooit reeds toegewezen vormen — hun individuele instellingen (met de hand aangepaste grootte, rotatie, tekst eigen aan elke machine...) blijven dus altijd behouden.",
    'aide_parc_machine.callout_tip_exemple_vis' => "Handig in de praktijk: wijzig de kleur van een categorie \"Afvalschroef\" in Instellingen, en de 36 schroeven die al op \"Afvalschroef\" staan op het schema veranderen in één keer van kleur — zonder de individueel ingestelde groottes en rotaties van elk ervan te verliezen.",
    'aide_parc_machine.source_lede' => "Het Machinepark is de <b>enige bron</b> van de locatie-keuzelijsten die elders in de applicatie gebruikt worden.",
    'aide_parc_machine.route_tag' => "Gebruikt door",
    'aide_parc_machine.route1_titre' => "Een BI / aanvraag aanmaken",
    'aide_parc_machine.route1_desc' => "De cascade Fabriek → Sector → Zone → Machine, in <a href=\"aide_ot.php\">Invoer &amp; Geschiedenis</a> en het aanvraagportaal, komt rechtstreeks van hier.",
    'aide_parc_machine.route2_titre' => "Preventief & Planning",
    'aide_parc_machine.route2_desc' => "De preventieve onderhoudsplannen en bepaalde formulieren van de Planning steunen op dezelfde machinelijst.",
    'aide_parc_machine.callout_warn_absente' => "Als een machine <b>niet verschijnt</b> in een keuzelijst elders in de applicatie, is dat bijna altijd omdat ze niet — of niet meer — bestaat in het Machinepark. De oplossing is haar hier eerst aan te maken.",
    'aide_parc_machine.tbl_th_action' => "Actie",
    'aide_parc_machine.tbl_th_technicien' => "Technicus",
    'aide_parc_machine.tbl_th_admin' => "Admin",
    'aide_parc_machine.droit1_action' => "De boom raadplegen, zoeken, filteren",
    'aide_parc_machine.droit2_action' => "Een machine toevoegen / wijzigen / verplaatsen",
    'aide_parc_machine.droit3_action' => "Een site / sector / lijn / zone hernoemen",
    'aide_parc_machine.droit4_action' => "Een machine verwijderen",
    'aide_parc_machine.droit5_action' => "Een type in bulk toewijzen",
    'aide_parc_machine.astuces_li1' => "<b>Verkies hernoemen boven verwijderen + herscheppen</b> van een machine of zone: hernoemen behoudt de volledige geschiedenis, verwijderen koppelt ze los.",
    'aide_parc_machine.astuces_li2' => "<b>\"+ Nieuw...\"</b> in de locatievelden maakt een echt knooppunt aan zodra er een machine aan gekoppeld wordt — geen nood om vooraf een \"lege sector\" aan te maken.",
    'aide_parc_machine.astuces_li3' => "<b>Een knooppunt zonder machine verdwijnt vanzelf</b> uit de boom — normaal, geen bug.",
    'aide_parc_machine.astuces_li4' => "<b>De meervoudige selectie</b> dient enkel om een uitrustingstype in bulk toe te wijzen — er bestaat geen groepsverwijdering.",
    'aide_parc_machine.gloss1_dt' => "Knooppunt",
    'aide_parc_machine.gloss1_dd' => "Een niveau van de boomstructuur (een fabriek, een sector, een lijn of een zone).",
    'aide_parc_machine.gloss2_dt' => "Uitrustingstype",
    'aide_parc_machine.gloss2_dd' => "Een technische categorie (Mechanisch, Elektrisch...), configureerbaar vanuit Instellingen.",
    'aide_parc_machine.gloss3_dt' => "Referentiebron",
    'aide_parc_machine.gloss3_dd' => "De referentiegegevens waarvan de andere pagina's afhangen — hier, het Machinepark voor elke locatie.",
    'aide_parc_machine.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan administratiezijde:",
    'aide_parc_machine.devnote_li1' => "Er bestaat geen enkele echte foreign key tussen <code>machines</code> en <code>taches</code>/preventieve plannen — de koppeling gebeurt via tekstovereenkomst (fabriek+sector+zone+naam). Het verwijderen van een machine breekt dus technisch niets, maar maakt haar geschiedenis wees ten opzichte van de referentiegegevens.",
    'aide_parc_machine.devnote_li2' => "Een <b>lijn</b> hernoemen werkt <code>taches</code> niet bij (deze tabel heeft geen kolom <code>ligne</code>) — enkel fabriek/sector/zone/machine worden doorgegeven.",
    'aide_parc_machine.devnote_li3' => "Een uitrustingstype \"ter plekke\" aangemaakt via de tegel \"Andere\" wordt niet toegevoegd aan de referentietabel <code>types_equipement</code> — het verschijnt enkel zolang minstens één machine het gebruikt, met een generiek icoon.",

    'aide_sous_traitants.page_title_tag' => "Onderaannemers beheren - Hulp GMAO",
    'aide_sous_traitants.hero_tagline' => "Een extern bedrijf plannen, hun aanwezigheid op de site opvolgen, en hun Preventieplannen up-to-date houden.",
