    'aide_sous_traitants.toc_pdp' => "Het Preventieplan (PdP)",
    'aide_sous_traitants.toc_annuaire' => "De bedrijvengids",
    'aide_sous_traitants.toc_historique' => "De geschiedenis",
    'aide_sous_traitants.toc_droits' => "Wie mag wat doen",
    'aide_sous_traitants.toc_astuces' => "Tips & valkuilen",
    'aide_sous_traitants.toc_glossaire' => "Woordenlijst",
    'aide_sous_traitants.vue_lede' => "Het scherm <b>Onderaannemers</b> is het dashboard van alle externe bedrijven die op de site interveniëren: wie is gepland, wie is op dit moment fysiek aanwezig, en de geschiedenis van wat al gedaan is. Een uitbestede interventie blijft een <b>interventiebon (BI)</b> zoals een andere — ze verschijnt met dezelfde nummers en hetzelfde detail als die aangemaakt vanuit <a href=\"aide_ot.php\">Invoer &amp; Geschiedenis</a>, met gewoon een extra label \"uitbesteed\".",
    'aide_sous_traitants.vue_p2' => "Drie zones structureren de pagina:",
    'aide_sous_traitants.card_planification_titre' => "Planning",
    'aide_sous_traitants.card_planification_desc' => "De tabel van komende of gepauzeerde interventies, met hun Preventieplan.",
    'aide_sous_traitants.card_sursite_titre' => "Momenteel op de site",
    'aide_sous_traitants.card_sursite_desc' => "Realtime kaarten voor elk fysiek aanwezig bedrijf.",
    'aide_sous_traitants.card_historique_titre' => "Geschiedenis",
    'aide_sous_traitants.card_historique_desc' => "De reeds afgesloten interventies (toegankelijk via een specifieke knop).",
    'aide_sous_traitants.vue_p3' => "Drie tellers bovenaan de pagina geven een onmiddellijke stand van zaken: <b>Bedrijven op de site</b>, <b>Geplande interventies</b>, en <b>Ontbrekende / Verlopen PdP</b> (een alarm om nauwlettend op te volgen, zie hieronder).",
    'aide_sous_traitants.shot_dashboard_alt' => "Dashboard van de onderaannemers: tellers, planning en aanwezigheid op de site",
    'aide_sous_traitants.shot_dashboard_cap' => "Het volledige dashboard: de 3 tellers, de planning, en het paneel \"Momenteel op de site\".",
    'aide_sous_traitants.planifier_lede' => "Knop <b>\"NIEUWE INTERVENTIE\"</b> bovenaan de planningstabel.",
    'aide_sous_traitants.p_step1_titre' => "Vink een of meer bedrijven aan",
    'aide_sous_traitants.p_step1_desc' => "De lijst \"Extern Bedrijf\" biedt aan te vinken vakjes. Meerdere bedrijven aanvinken maakt <b>een aparte interventie per bedrijf</b>, elk met zijn eigen BI-nummer.",
    'aide_sous_traitants.p_step2_titre' => "Geef het type, de datum en het uur op",
    'aide_sous_traitants.p_step2_desc' => "Type (Werf / Preventief / Curatief), datum van de interventie, verwacht aankomstuur (standaard 8u).",
    'aide_sous_traitants.p_step3_titre' => "Kies de locatie",
    'aide_sous_traitants.p_step3_desc' => "Cascade Fabriek → Sector → Zone → Machine, elk menu wordt vrijgegeven zodra het vorige is ingevuld (gevoed door het <a href=\"aide_parc_machine.php\">Machinepark</a>).",
    'aide_sous_traitants.p_step4_titre' => "Wijs de verantwoordelijke technicus voor de opvolging aan",
    'aide_sous_traitants.p_step4_desc' => "Een lid van het onderhoudsteam dat het interne aanspreekpunt blijft voor deze interventie.",
    'aide_sous_traitants.p_step5_titre' => "Beschrijf de aard van de werken",
    'aide_sous_traitants.p_step5_desc' => "Verplicht veld, bv. \"Vervanging van de bandmotor...\". Vink \"BREUK\" aan als de interventie het gevolg is van een accidentele breuk.",
    'aide_sous_traitants.p_step6_titre' => "Bevestig met \"DE INTERVENTIEBON AANMAKEN\"",
    'aide_sous_traitants.p_step6_desc' => "Zonder aangevinkt bedrijf, zonder datum of zonder beschrijving weigert de app en toont: \"Gelieve minstens één bedrijf aan te vinken, en de datum en beschrijving in te vullen!\"",
    'aide_sous_traitants.callout_tip_numero_bi' => "Het <b>BI-nummer</b> (bv. <code>BI26-014</code>) wordt automatisch gegenereerd, zoals voor elke interventie. De aangewezen verantwoordelijke technicus ontvangt ook, meteen bij het aanmaken, een <b>tijdregistratie van 0u</b> die hem officieel aan deze BI koppelt — hij zal vanaf dat moment in zijn planning verschijnen, zelfs vóór hij werkelijk tijd geregistreerd heeft.",
    'aide_sous_traitants.planifier_p2' => "Het potlood op een rij van de tabel opent hetzelfde venster in modus <b>\"Planning wijzigen\"</b>, vooraf ingevuld.",
    'aide_sous_traitants.presence_lede' => "Een uitbestede interventie volgt een aanwezigheidscyclus, los van de status van de BI zelf.",
    'aide_sous_traitants.cy_planifie_label' => "Gepland",
    'aide_sous_traitants.cy_planifie_trig' => "Aangemaakt via \"NIEUWE INTERVENTIE\"",
    'aide_sous_traitants.cy_who_vous' => "U",
    'aide_sous_traitants.cy_sursite_label' => "Op de site",
    'aide_sous_traitants.cy_sursite_trig' => "Knop \"LATEN BINNENKOMEN\" in de tabel",
    'aide_sous_traitants.cy_pause_label' => "Gepauzeerd",
    'aide_sous_traitants.cy_pause_trig' => "Knop \"UITGAAN (PAUZE)\" op de kaart",
    'aide_sous_traitants.cy_termine_label' => "Afgerond",
    'aide_sous_traitants.cy_termine_trig' => "Knop \"AFSLUITEN\" + verslag",
    'aide_sous_traitants.presence_p2' => "Een bedrijf \"op de site\" verschijnt als een kloppende groene kaart in het paneel \"Momenteel op de site\". De knop <b>\"UITGAAN (PAUZE)\"</b> sluit niets af: de technicus verlaat gewoon de fabriek, de interventie keert terug naar de planningstabel met een oranje badge <b>\"GEPAUZEERD\"</b>, klaar om later \"terug te laten binnenkomen\".",
    'aide_sous_traitants.cloturer_lede' => "Vanaf een kaart \"op de site\" opent de groene knop <b>\"AFSLUITEN\"</b> het afsluitvenster.",
    'aide_sous_traitants.callout_warn_compte_rendu' => "Het veld <b>\"Interventieverslag\"</b> is verplicht. Als u probeert af te sluiten zonder iets te schrijven: <i>\"Oeps! Het verslag is verplicht om de interventie van het externe bedrijf te kunnen afsluiten.\"</i>",
    'aide_sous_traitants.cloturer_p2' => "Eenmaal bevestigd, gaat de interventie naar de status <b>Afgerond</b> en verhuist naar de geschiedenis.",
    'aide_sous_traitants.pdp_lede' => "De PdP is het veiligheidsdocument dat de interventie van een extern bedrijf omkadert. Zijn status wordt automatisch berekend op basis van de vervaldatum opgegeven in de directory.",
    'aide_sous_traitants.tbl1_th_badge' => "Badge",
    'aide_sous_traitants.tbl1_th_condition' => "Voorwaarde",
    'aide_sous_traitants.badge_valide' => "PdP Geldig",
    'aide_sous_traitants.cond_valide' => "De vervaldatum is vandaag of in de toekomst.",
    'aide_sous_traitants.badge_expire' => "PdP Verlopen",
    'aide_sous_traitants.cond_expire' => "De vervaldatum is overschreden.",
    'aide_sous_traitants.badge_attente' => "In afwachting",
    'aide_sous_traitants.cond_attente' => "Geen vervaldatum opgegeven voor het bedrijf.",
    'aide_sous_traitants.pdp_p2' => "Elk bedrijf heeft een <b>PdP-type</b> in de directory, dat de weergavelogica wijzigt:",
    'aide_sous_traitants.route_tag_annuel' => "Jaarlijks type",
    'aide_sous_traitants.route_annuel_titre' => "Jaarlijkse PdP",
    'aide_sous_traitants.route_annuel_desc' => "De status volgt werkelijk de vervaldatum (groene/rode/oranje badge).",
    'aide_sous_traitants.route_tag_ponctuel' => "Eenmalig type",
    'aide_sous_traitants.route_ponctuel_titre' => "Eenmalige PdP",
    'aide_sous_traitants.route_ponctuel_desc' => "Opnieuw gemaakt bij elke werf: de status wordt altijd geforceerd op \"ok\" (geen vals rood alarm), getoond met een specifieke oranje badge en de vermelding \"Gekoppeld aan de lopende werf\" in plaats van een datum.",
    'aide_sous_traitants.callout_tip_bouclier' => "Vanuit de directory genereert het <b>paarse schildicoon</b> een <b>blanco PdP</b> vooraf ingevuld met de gegevens van het bedrijf, klaar om te laten ondertekenen (nieuw tabblad). Eenmaal ondertekend en gescand, wordt de PDF gekoppeld aan de bedrijfsfiche (rood PDF-icoon) en met één klik raadpleegbaar vanuit de planningstabel.",
    'aide_sous_traitants.pdp_p3' => "De teller <b>\"Ontbrekende / Verlopen PdP\"</b> bovenaan de pagina bewaakt <i>alle</i> bedrijven van de directory, niet enkel die met een lopende interventie — het is een globale compliance-indicator om regelmatig te raadplegen.",
    'aide_sous_traitants.annuaire_lede' => "Toegankelijk via de knop <b>\"De bedrijvengids beheren\"</b>, <b>enkel voor administrators</b>.",
    'aide_sous_traitants.annuaire_p2' => "Elke bedrijfsfiche groepeert: naam, contact, telefoon, e-mail, PdP-type, vervaldatum, en het PDF-bestand van de ondertekende PdP.",
