    'aide_sous_traitants.row_type_detail' => "Jaarlijks of Eenmalig — bepaalt de weergave van de status (zie hierboven).",
    'aide_sous_traitants.row_fin_champ' => "Vervaldatum PdP",
    'aide_sous_traitants.row_fin_detail' => "Datum, gebruikt om de statusbadge in jaarlijkse modus te berekenen.",
    'aide_sous_traitants.row_fichier_champ' => "PdP-bestand (PDF)",
    'aide_sous_traitants.row_fichier_detail' => "Upload van één enkel bestand, <b>enkel in PDF-formaat</b> — elk ander formaat wordt om veiligheidsredenen geweigerd.",
    'aide_sous_traitants.callout_warn_suppression_entreprise' => "Een bedrijf uit de directory verwijderen is <b>definitief</b>, met een eenvoudige bevestiging. De reeds uitgevoerde interventies met dit bedrijf blijven zichtbaar in de geschiedenis, maar de bijhorende bedrijfsfiche bestaat niet meer.",
    'aide_sous_traitants.historique_lede' => "Knop <b>\"GESCHIEDENIS\"</b> bovenaan de planningstabel: de laatste 100 afgesloten uitbestede interventies, met BI-nummer (aanklikbaar), datum, bedrijf, machine, technici die geregistreerd hebben, en het verslag.",
    'aide_sous_traitants.historique_p2' => "Vanaf de detailfiche van een bedrijf in de directory wordt dezelfde geschiedenistabel gefilterd <b>enkel voor dit bedrijf</b> — handig om snel alles terug te vinden wat een dienstverlener op de site gedaan heeft.",
    'aide_sous_traitants.tbl3_th_action' => "Actie",
    'aide_sous_traitants.tbl3_th_technicien' => "Technicus",
    'aide_sous_traitants.tbl3_th_admin' => "Admin",
    'aide_sous_traitants.droit1_action' => "De planningstabel / aanwezigheid / geschiedenis bekijken",
    'aide_sous_traitants.droit2_action' => "Een interventie plannen / wijzigen",
    'aide_sous_traitants.droit3_action' => "Laten binnenkomen / uitgaan / afsluiten",
