    'aide_sous_traitants.droit4_tech' => "Knop verborgen",
    'aide_sous_traitants.droit5_action' => "Een blanco PdP genereren",
    'aide_sous_traitants.droit5_tech' => "Link verborgen",
    'aide_sous_traitants.astuces_li1' => "<b>Het filter \"Deze week / Deze maand / Alle\"</b> bovenaan de planningstabel is voorlopig niet actief — het heeft geen enkel effect op de weergave.",
    'aide_sous_traitants.astuces_li2' => "<b>Volg regelmatig de teller \"Ontbrekende / Verlopen PdP\" op</b> — het is de enige plaats die u waarschuwt over bedrijven in gebreke inzake veiligheidscompliance, zelfs zonder lopende interventie.",
    'aide_sous_traitants.astuces_li3' => "<b>Verwar \"UITGAAN (PAUZE)\" en \"AFSLUITEN\" niet</b>: de eerste houdt de interventie open voor een latere hervatting, de tweede beëindigt ze definitief en vereist een verslag.",
    'aide_sous_traitants.astuces_li4' => "<b>Een \"Eenmalige\" PdP</b> heeft geen permanent bijgewerkte vervaldatum nodig — het is normaal dat ze altijd als geldig weergegeven blijft.",
