    'aide_sous_traitants.gloss3_dt' => "Gepauzeerd",
    'aide_sous_traitants.gloss3_dd' => "Onafgewerkte interventie waarvan de technicus de site tijdelijk verlaten heeft.",
    'aide_sous_traitants.gloss4_dt' => "Directory",
    'aide_sous_traitants.gloss4_dd' => "De lijst van geregistreerde externe bedrijven, met hun gegevens en hun PdP.",
    'aide_sous_traitants.devnote_intro' => "Punten opgemerkt bij het analyseren van de code, om in gedachten te houden aan administratiezijde:",
    'aide_sous_traitants.devnote_li1' => "De keuzeschakelaar \"Deze week / Deze maand / Alle\" van de planningstabel heeft geen enkele bijhorende JS-logica — voorlopig cosmetisch.",
    'aide_sous_traitants.devnote_li2' => "De bescherming van de directory (knop verborgen voor niet-admins) is <b>enkel visueel aan PHP-zijde</b>: de serververwerking <code>action_entreprise</code> controleert de rol niet opnieuw.",
    'aide_sous_traitants.devnote_li3' => "Enkel de extensie <code>.pdf</code> wordt aanvaard bij het uploaden van de PdP, gecontroleerd serverzijde — goede praktijk om te behouden.",
    'aide_sous_traitants.devnote_li4' => "Een bedrijf uit de directory verwijderen controleert de gekoppelde interventies niet (<code>entreprise_ext_id</code> wordt wees, maar de naam blijft weergegeven via de join die op het moment van de query vastligt).",

